window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_007"]={"n":"凌云翰","dyn":"元","poems":[{"t":"一剪梅 寿俞子中紫芝","f":"曲","c":["苍颜白发称乌纱。","瘦似黄花。","清似梅花。","窗吟山月乐无涯。","知是儒家。","知是仙家。","紫芝服食胜胡麻。","不爱繁华。","却爱年华。","词成笔底是龙蛇。","寿酒流霞。","寿气成霞。"]},{"t":"凤凰台上忆吹箫 赋凤仙花","f":"曲","c":["菊婢标名，凤仙题品，纷纷随处成丛。","甚玉钗浑小，宝髻微松。","依旧花分五彩，毗陵画、总付良工。","谁为伴，鸡冠染紫，雁阵来红。","玲珑。","英英秀质，多想是花神，剪綵铺茸。","却易分高下，难辨雌雄。","疑把守宫同捣，端可爱、深染春葱。","开还谢，从风乱飘，好上梧桐。"]},{"t":"无俗念","f":"曲","c":["等闲屈指，算今来古往，谁为英杰。","耳目聪明天赋予，怎肯虚生虚灭。","去燕来鸿，飞乌走兔，世事何时歇。","风波境界，大川不用频涉。","踏遍万户千门，五湖四海，一样中秋月。","正面相看君记取，全体本来无缺。","空里非空，梦中真梦，莫对痴人说。","便须骑鹤，夜深朝礼金阙。"]},{"t":"木兰花慢 寿侄云逵时七月十四日也","f":"曲","c":["问初秋明月，更一夕、十分圆。","喜鸿雁行中，居然生子，眉目娟娟。","秪今年踰弱冠，遇生朝刚要赋诗篇。","莫学汝家痴叔，蹉跎已傍中年。","博山风袅水沉烟。","绛蜡照华筵。","有檀板歌词，金樽劝酒，银甲弹弦。","阶庭旧时玉树，正朱颜绿鬓似神仙。","丹桂不妨似窦，紫荆还见如田。"]},{"t":"木兰花慢 赋白莲 和宇舜臣韵","f":"曲","c":["怅波翻太液，谁留住、蕊珠仙。","向水殿云廊，玉容花貌，几度争鲜。","人间延秋无计，掩霓裳、犹忆舞便娟。","画里倾城倾国，望中非雾非烟。","雁飞不到九重天。","水调谩流传。","柰花老房空，菂存心苦，藕断丝连。","西风环佩轻解，有冰弦、谁复记华年。","留得锦囊遗墨，魂消古汴宫前。"]},{"t":"风入松 寿郭仲和","f":"曲","c":["传家应自郭汾阳。","馀裔在钱唐。","傍人莫笑儒酸在，亲曾接、鹓鹭班行。","赢得身心稳住，须鬓却苍苍。","中和相隐旧书堂。","弦诵乐时康。","梅花枝上春犹小，朋簪盍、次第称觞。","莫问商瞿年纪，也须载弄之璋。"]},{"t":"风入松 和贝廷琚助教韵","f":"曲","c":["谁教齿豁更头童。","从唤作衰翁。","惜花已自因花瘦，况飘零、万点随风。","须信人生如梦，休言世事皆空。","紫骝嘶过画桥东。","犹记软尘红。","重来绿遍西湖路，消魂是、杜宇声中。","经眼倚妆飞燕，伤心照影惊鸿。"]},{"t":"沁园春 嘲昆季析居","f":"曲","c":["树上凌霄，堂前紫荆，秋来尚芳。","柰牝鸡晨语，鹡鸰憔悴，妖狐昼啸，鸿雁分张。","仁智匪周，喜忧非舜，一旦天伦忍遂忘。","如何好，望松楸感泣，桑梓悲伤。","古今祸起专房。","总一国、犹然况一乡。","家有妇人，岂无长舌，世无男子，谁有刚肠。","树大枝分，瓜熟蒂落，此语应非是义方。","聊书此，要惩鉴诫，不在文章。"]},{"t":"鸣鹤遗音 苏武慢 其二 并序","f":"曲","c":["智不如愚，辩何如讷，大巧又何如拙。","螳黠蝉痴，鹤长凫短，总是一番消歇。","逝者如斯，挠之不浊，止水本来明彻。","君试看、云散天开，见出自家秋月。","谁种得、白雪黄芽，交梨火枣，不怕北风吹裂。","头上簪花，手中拍板，稽首金银宫阙。","见说麻姑，高骑鹏背，载酒过门相谒。","便呼童、拗折松枝，扫取一庭残雪。"]},{"t":"鸣鹤遗音 苏武慢 其四 并序","f":"曲","c":["芳草纤纤，游丝冉冉，可爱地晴江碧。","世事浮云，人生大梦，岐路谩悲南北。","漉酒春朝，步蟾秋夜，却忆旧时巾舄。","问故园、何日归欤，松菊已非畴昔。","谁似我、十亩柔桑，千头佳橘，饱有绿阴朱实。","溉釜烹鱼，饭疏饮水，胜咀绛霞琼液。","鸟倦知还，水流不竞，乔木且容休息。","喜闲来、事事从容，睡觉半窗晴日。"]},{"t":"鸣鹤遗音 苏武慢 其七 并序","f":"曲","c":["雾驾云軿，雨巾风帽，一剑凌风飞过。","下视茫茫，遥观历历，不复更知天大。","日月居诸，春秋代谢，几见授衣流火。","记岳阳、三度曾游，未必世人知我。","游戏处、柳树为徒，榴皮作字，聊说行藏如左。","列豹重关，封狐千里，不满楚人哀些。","瓦砾黄金，蓬莱别馆，归去有谁知那。","不须分、天上人间，南北东西皆可。"]},{"t":"鸣鹤遗音 苏武慢 其三 并序","f":"曲","c":["玉砌雕阑，朱门紫陌，争似道人茅宇。","樽有新醪，盘无兼味，自傍小溪垂缕。","富贵何淫，贱贫亦乐，此外更无他语。","有时将、明月为家，或共白云为侣。","还俯视、六合之间，茫茫何物，不入灵台丹府。","绿水青山，野花啼鸟，已把此心留住。","梦熟黄粱，尘飞沧海，转首便为千古。","问雪堂、归去何时，江上一犁春雨。"]},{"t":"鸣鹤遗音 苏武慢 其十二 并序","f":"曲","c":["君实园中，尧夫窝内，独乐正同安乐。","维水泱泱，予怀渺渺，西望每思伊洛。","草色随车，花香袭屦，风景至今犹昨。","被杜鹃、啼破天津，便觉市朝萧索。","谁复见、万古龙门，三春桃浪，冲岸紫鳞争跃。","月到风来，水流山在，安得二贤同酌。","心上经纶，鉴中治乱，叹息九原难作。","笑红尘、逐利争名，总是蝇头蜗角。"]},{"t":"鸣鹤遗音 苏武慢 其六 并序","f":"曲","c":["身在云间，目穷天际，一带远山如隔。","隐隐迢迢，霏霏拂拂，蔓草寒烟秋色。","数著残棋，一声长啸，谁识洞庭仙客。","对良宵、明月清风，意味少人知得。","君记取、黄鹤楼前，紫荆台上，神有青蛇三尺。","土木形容，水云情性，标韵自然孤特。","碧海苍梧，白蘋红蓼，都是旧时行迹。","细寻思、离乱伤神，莫厌此生欢剧。"]},{"t":"鸣鹤遗音 苏武慢 其十 并序","f":"曲","c":["有酒无殽，柰何良夜，客有鲈鱼相惠。","如此山川，几何日月，三国竟成何事。","目断风帆，江空岁晚，觅句谩思无已。","怕多情、笑我华颠，甚矣吾衰久矣。","客知夫、水与月乎，盈亏如彼，逝者有如斯水。","舟放中流，听其所止，夜久江流声细。","鹤为予来，客辞予去，予亦就眠篷底。","忽羽衣、过我林皋，惊觉一番残醉。"]},{"t":"鸣鹤遗音 苏武慢 其一 并序","f":"曲","c":["云缕虹竿，月钩星饵，海上金鳌曾钓。","蓬岛连根，昆崙无外，不比人间嵩少。","返本还源，成功满行，坐待紫皇飞诏。","笑令威、千岁来归，知换几番华表。","谁曾伴、阿母重游，蟠桃再结，目断西飞青鸟。","林屋无扃，洞天不老，铁笛一声云杪。","皎皎灵台，荧荧明镜，尘土等闲昏了。","看火轮、飞出扶桑，万户千门皆晓。"]},{"t":"鸣鹤遗音 苏武慢 其九 并序","f":"曲","c":["醉里闲吟，兴来独往，山静悄无人语。","两岸桃花，一溪春水，似忆仙源无路。","花上莺啼，云间犬吠，偶到洞仙琳宇。","便相留、闲话长生，嗟我委形非故。","图画里、昔日天台，当年刘阮，此说荒唐无取。","避世秦人，放舟渔子，却恐偶然相与。","岭日将沉，林风忽动，吹落半帘红雨。","待少焉、月出东方，拄个瘦藤归去。"]},{"t":"鸣鹤遗音 苏武慢 其十一 并序","f":"曲","c":["仙客难逢，白云谁扫，知是采芝何处。","皓鹤归来，金鸡啼罢，梦断阆风玄圃。","松下高歌，橘中残著，饥后自餐龙脯。","待偷桃，曼倩重来，为问木公金母。","君不见、洞里桃花，花间啼鸟，又是一番春暮。","弱水三千，巫山十二，指点虚无归路。","君抱琴来，我邀君饮，我醉欲眠君去。","向人间、游遍朱门，静看只如蓬户。"]},{"t":"鸣鹤遗音 苏武慢 其五 并序","f":"曲","c":["破帽多情，布帆无恙，兴尽便寻溪转。","明月来时，浮云飞尽，千古翠屏宜晚。","桂棹兰桨，荷衣芰制，偏称药炉经卷。","看轻鸥、点破长烟，一望水连天远。","尝记得、雪满山阴，舟回剡曲，何必过门相见。","浩气难消，哀情谁会，万里碧空横剑。","一道虹桥，半天龙驾，尚忆幔亭开燕。","要长生、须出人间，未卜道缘深浅。"]},{"t":"鸣鹤遗音 苏武慢 其八 并序","f":"曲","c":["驴背驮诗，鸱夷盛酒，晓踏苏堤残雪。","露阙云门，璇阶玉宇，照耀日华光洁。","见说孤山，犹存老树，清兴一时超越。","画船归、更有渔舟，此景顿成奇绝。","还四顾、表里通明，高低一色，尘土不容毫发。","却忆韩郎，花开顷刻，谁得染根仙诀。","雪后园林，天开图画，眼界迥然俱别。","待黄昏、约取林逋，湖上朗吟香月。"]},{"t":"定风波慢 商角调 赋崔莺莺传","f":"曲","c":["把丽情、分付良工，传奇谩为重省。","开户迎风，拂花动月，写尽西厢景。","笑书生，最侥倖。","刚道师婚胜琴聘。","沉静。","问姓名非是，近时三影。","空思蔗境。","画盐梅、不济调羹鼎。","翻残金旧日，诸宫调本，才入时人听。","减容光，懒窥镜。","凤枕鸳衾与谁□。","重赠。","李绅歌意，续微之咏。"]},{"t":"狮儿词 赋梅 和仇山村韵","f":"曲","c":["蹇驴破帽，知是几度寻春，山南山北。","惆怅亭荒仙远，苔枝空绿。","村醪正熟。","为花醉、何妨留宿。","春光似、怕人冷落，先回空谷。","潇洒生意自足。","有高标、不厌矮篱低屋。","与雪相期，侧耳隔窗虫扑。","晚晴纵步，又还信、一枝筇竹。","莫嫌独。","月在画阑东曲。"]},{"t":"浪淘沙 赋元夕遇雨次俞紫芝韵","f":"曲","c":["雨打上元灯。","无处邀朋。","何如窗下且瞢腾。","谩忆牙旗穿夜市，铁马春冰。","歌舞有人曾。","倦与争能。","越罗裁服换吴绫。","尽道先生归隐也，乌帽乌藤。"]},{"t":"渔家傲 寿杨复初","f":"曲","c":["采芝步入南山道。","道深宛似蓬莱岛。","闻说村居诗思好。","还被恼。","苍苔满地无人扫。","载酒亭前松合抱。","客来便许同倾倒。","玉兔已将灵药捣。","秋意早。","月华长似人难老。"]},{"t":"满江红 咏梨花鸟图","f":"曲","c":["谁写琼英，空惊讶、年华虚度。","依约似、清明池馆，粉容遮路。","蝴蝶又来丛里闹，鹪鹩还占枝头语。","向东阑、惆怅几回看，愁如许。","疑有月，光摇树。","疑是雪，香生处。","自洗妆人去，凄凉非故。","白发宫娃歌吹远，青旗酒舍诗吟古。","记黄昏、灯暗掩重门，听春雨。"]},{"t":"瑶华慢 赋雪","f":"曲","c":["喜深惊密。","试问滕神，有多少寒力。","如圆似瑩，总疑是、满眼隋珠和璧。","五更书幌，早已觉、寒光穿隙。","料禽影、波上渐稀，径里悄无行迹。","有人独倚危楼，望千里江山，高下同色。","坡仙饮处，甚尚然、不减醉翁宾客。","等闲评论，算柳絮、梨花非白。","画堂深、弦管方调，一任低垂帘额。"]},{"t":"蝶恋花","f":"曲","c":["过雨春波浮鸭绿。","草阁三间，人住清溪曲。","旧种小桃多似竹。","乱红遮断松边屋。","有客抱琴穿翠麓。","隔水呼舟，应是怜幽独。","历历武陵如在目。","几时同借仙源宿。"]},{"t":"蝶恋花 杏庄为莫景行题","f":"曲","c":["一色杏花三百树。","茅屋无多，更在花深住。","旋压小槽留客醉。","举杯忽听黄鹂语。","醉眼看花花亦舞。","风捲残红，飞过邻墙去。","恰似牧童遥指处。","清明时节纷纷雨。"]},{"t":"重过柳洲次陆德阳韵","f":"七言律诗","c":["买花载酒忆当年，风景依稀最可怜。","彭泽有人归栗里，海波何处变桑田。","联拳鹭立枯荷雨，寂寞鸦栖古树烟。","几度涌金门外望，居民犹说总宜船。"]},{"t":"钟馗画","f":"七言古诗","c":["北风吹沙目欲眯，官柳摇黄拂溪水。","终南进士倔然起，猬磔于思含缺齿。","袍蓝带角形甚傀，乌帽裹头靴露指。","白泽在傍口且哆，驯扰不异麟之趾。","手持上帝书满纸，若曰新岁锡尔祉。","一声竹爆物尽靡，明日春光万馀里。"]},{"t":"扇面画竹","f":"曲","c":["故人清风，美人明月。","胡为来哉，君子之节。"]},{"t":"郭景谅画","f":"曲","c":["月来中天，琴声以和。","爰有君子，于焉咏歌。","松风递清，石泉流响。","顾瞻白云，入我遐想。","有道之裔，媲美林宗。","假此图画，像此从容。","云月无穷，松泉有待。","善琴弗鼓，万境斯在。"]},{"t":"旭斋诗","f":"曲","c":["九日为旭，羿不能射。","荒唐之言，孰有知者。","旭日始旦，出日东方。","君子昭德，如彼朝阳。","以诚而倾，类葵与藿。","日入日出，我息我作。","惟刘氏子，志于高明。","爰有斋居，以旭自名。","日新又新，用之曷匮。","其休以德，其拙以伪。","我作此诗，惟明自资。","孰传草圣，为汝书之。"]},{"t":"画梅 其一","f":"五言绝句","c":["老枝如屈铁，陡觉数花新。","若露真消息，能令大地春。"]},{"t":"画梅 其二","f":"五言绝句","c":["吐花当暮景，结实待炎风。","无限调和意，都归笔砚中。"]},{"t":"四皓图","f":"五言绝句","c":["松下紫芝曲，宫中鸿鹄歌。","谁知四皓力，还比酂侯多。"]},{"t":"松云图为吴以道赋","f":"五言绝句","c":["云闲常尽日，松老不知年。","甚似匡庐下，开亭待谪仙。"]},{"t":"太白像","f":"五言绝句","c":["正尔吟秋浦，如何谪夜郎。","尚疑颜色在，落月满空梁。"]},{"t":"东坡像","f":"五言绝句","c":["雨笠有时借，雪堂从此闲。","眉山秋夜月，清影在人间。"]},{"t":"宋授之所画扇","f":"五言绝句","c":["楼拥千章木，山横一段云。","夕阳遮不尽，犹照白鸥群。"]},{"t":"雨竹扇面","f":"五言绝句","c":["月满潇湘浦，移舟试一过。","如何今夜雨，重听竹枝歌。"]},{"t":"画 其一","f":"五言绝句","c":["新居鉴湖曲，烂熳藉花开。","留得舟行路，频看载酒来。"]},{"t":"画 其二","f":"五言绝句","c":["不是王猷宅，如何竹树幽。","山阴夜来雪，有兴也回舟。"]},{"t":"为林子山题王叔明所作羌山隐居图","f":"五言绝句","c":["诗人头未白，又欲隐羌山。","好把无声意，光传满世间。"]},{"t":"画红梅 其一","f":"五言绝句","c":["江县春光早，红梅却放迟。","是谁枯彩笔，写得向阳枝。"]},{"t":"画红梅 其二","f":"五言绝句","c":["林下藐姑射，山中萼绿华。","驻颜无别药，一味服丹砂。"]},{"t":"俞文辅竹石","f":"五言绝句","c":["怪石玄云立，修篁翠雨垂。","虽非与可笔，消得子瞻诗。"]},{"t":"云松观瀑图","f":"五言绝句","c":["悬崖见飞瀑，界破一天秋。","松密云深处，巢居在上头。"]},{"t":"竹枝二鸟图","f":"五言绝句","c":["二鸟占丛竹，喧啾春雨时。","朝阳有鸣凤，栖老碧梧枝。"]},{"t":"枯木立雀图","f":"五言绝句","c":["木杪怜孤雀，蓬蒿亦可依。","好于生处乐，何用履危机。"]},{"t":"鼠衔芦菔图","f":"五言绝句","c":["太仓多积粟，任汝穴其间。","何事衔芦菔，生红破一班。"]},{"t":"墨竹扇面 其一","f":"五言绝句","c":["剪得责鸾尾，凉阴欠被分。","山风一披拂，扫动石坛云。"]},{"t":"墨竹扇面 其二","f":"五言绝句","c":["山幽多美竹，不畏雪霜寒。","好共丛生桂，移来月里看。"]},{"t":"高士谦竹石","f":"五言绝句","c":["翠雨何曾湿，苍云本自低。","湘山不可到，转觉望中迷。"]},{"t":"墨菊","f":"五言绝句","c":["谁写鹅毛菊，垐开或半开。","露华如许湿，都向墨池来。"]},{"t":"钩勒竹为沈景王赋 其一","f":"五言绝句","c":["钩勒筼筜叶，浑疑雪压枝。","全胜东老壁，诗写石榴皮。"]},{"t":"钩勒竹为沈景王赋 其二","f":"五言绝句","c":["孤竹生来瘦，挥毫欲动摇。","双溪风月夜，想像沈郎腰。"]},{"t":"画扇 其一","f":"五言绝句","c":["水阔秋光变，乡心在客船。","高楼见红柚，诗意写樊川。"]},{"t":"画扇 其二","f":"五言绝句","c":["三泖有佳处，孤舟无定居。","秋风纨扇底，归兴起鲈鱼。"]},{"t":"题李渊之所藏裴日英翠竹黄花图","f":"五言绝句","c":["翠竹闲旌节，黄花老佩环。","玉关秋梦断，纸上看南山。"]},{"t":"为李渊之题张师夔所作二图 其一","f":"五言绝句","c":["石好竹亦好，营丘到蓟丘。","无端闲草木，相与斗清幽。"]},{"t":"为李渊之题张师夔所作二图 其二","f":"五言绝句","c":["脩竹比君子，好山如故人。","先生归栗里，无复见清新。"]},{"t":"姚江放舟图","f":"五言绝句","c":["一雨众山绿，姚江春水生。","云林回首处，方觉去舟轻。"]},{"t":"琴","f":"五言绝句","c":["膝上横焦尾，何人识正音。","汾亭空有操，不及杏坛吟。"]},{"t":"书","f":"五言绝句","c":["僧舍兰亭帖，萧郎取得还。","昭陵一片墨，依旧出人间。"]},{"t":"方季长红梅翠竹二图 其一","f":"五言绝句","c":["江县红梅放，雪中先满春。","杏园消息近，为报探花人。"]},{"t":"方季长红梅翠竹二图 其二","f":"五言绝句","c":["为爱新梢绿，呼童竟护持。","他时霜雪操，总是出墙枝。"]},{"t":"刘伯伦像","f":"五言绝句","c":["痛饮日操卮，朝昏总不知。","却嫌犹未达，荷锸使人随。"]},{"t":"李太白像","f":"五言绝句","c":["被酒出金銮，宫袍尚未乾。","屋梁今夜月，颜色梦回看。"]},{"t":"画","f":"五言绝句","c":["白鹤行先远，追随倦小童。","囊琴何用解，倚杖听松风。"]},{"t":"渔村暮景图","f":"五言绝句","c":["鸦乱暮林近，鲈肥秋水深。","江南无限好，图画亦关心。"]},{"t":"叶本蕃扇上竹石","f":"五言绝句","c":["石林春色晚，老节有清芬。","待得儿孙长，抽梢尽入云。"]},{"t":"蕉石图","f":"五言绝句","c":["石畔色蕉叶，经霜便不留。","偶传方子笔，宜夏亦宜秋。"]},{"t":"悬崖梅图","f":"五言绝句","c":["悬枝生笔底，春色乱纷纷。","疑把孤鸾尾，巅崖扫白云。"]},{"t":"郑敬常函扇","f":"五言绝句","c":["远屿连沙渚，西风满客船。","独怜江上月，今夜向人圆。"]},{"t":"宋授之所作美人欠伸图","f":"五言绝句","c":["春日深宫静，闲观女史箴。","倦来俄起立，蝴蝶下庭心。"]},{"t":"杨妃春睡图","f":"五言绝句","c":["倦舞霓裳曲，曾教枕簟开。","可怜魂梦短，不到蜀关西。"]},{"t":"海棠风燕图","f":"五言绝句","c":["社日来双燕，低徊佛画檐。","海棠风不定，谁为捲珠帘。"]},{"t":"四景图 其一","f":"五言绝句","c":["驴背驮诗去，溪桥有路通。","花村茅店小，春日酒旗风。"]},{"t":"四景图 其二","f":"五言绝句","c":["偶看云起处，指点隔溪山。","莫问凉多少，能令羽扇闲。"]},{"t":"四景图 其三","f":"五言绝句","c":["遥山深秋色，总被草堂分。","篱外涓涓水，流来半是云。"]},{"t":"四景图 其四","f":"五言绝句","c":["山村风雪夜，犬吠有人归。","不道梅花冷，悬灯掩竹扉。"]},{"t":"四鹰图 其一","f":"五言绝句","c":["旷野秋先肃，鴐鹅见一群。","老拳犹健在，击透几重云。"]},{"t":"四鹰图 其二","f":"五言绝句","c":["锦架丝绦旧，羁縻气转雄。","草间狐兔尽，饱食待秋风。"]},{"t":"四鹰图 其三","f":"五言绝句","c":["饱飏饥则附，物欲一天机。","会有长风便，冲霄试一飞。"]},{"t":"四鹰图 其四","f":"五言绝句","c":["立臂从秋狝，穿云得羽毛。","特将献天子，应不负微劳。"]},{"t":"潇湘八景图为镏养愚赋 其一 潇湘夜曲","f":"五言绝句","c":["巴山一夜雨，剪烛话西窗。","何似潇湘浦，孤篷宿大江。"]},{"t":"潇湘八景图为镏养愚赋 其二 远浦归帆","f":"五言绝句","c":["江头晚风急，飒飒片帆秋。","极浦苍茫外，何人独倚楼。"]},{"t":"潇湘八景图为镏养愚赋 其三 烟寺晚钟","f":"五言绝句","c":["漠漠长烟际，钟鸣寺已昏。","山僧归去晚，和月扣松门。"]},{"t":"潇湘八景图为镏养愚赋 其四 洞庭秋月","f":"五言绝句","c":["月色秋逾好，波澄影更深。","有人横铁笛，惊起老龙吟。"]},{"t":"潇湘八景图为镏养愚赋 其五 平沙落雁","f":"五言绝句","c":["相逐云间侣，翩翩落远沙。","晚风吹不断，爱此一行斜。"]},{"t":"潇湘八景图为镏养愚赋 其六 渔村夕照","f":"五言绝句","c":["绿树村村暗，黄茆处处低。","渔人贪落照，晒网屋檐西。"]},{"t":"潇湘八景图为镏养愚赋 其七 山市晴岚","f":"五言绝句","c":["山气不成雨，晓晴人趁虚。","相逢尽相识，大半是樵渔。"]},{"t":"潇湘八景图为镏养愚赋 其八 江天暮雪","f":"五言绝句","c":["江树晚模糊，前村认有无。","不须摩诘画，已似辋川图。"]},{"t":"俞文辅墨竹","f":"五言绝句","c":["文同本进士，家有筼筜谷。","所以俞省元，胸中出淇澳。"]},{"t":"扇面画梅","f":"五言绝句","c":["团扇写横枝，吴华可含咀。","谁知江南春，消尽人间暑。"]},{"t":"梨花画鸠图","f":"五言绝句","c":["年年寒食节，院落梨花吐。","何处鹁鸠鸣，纱窗夜来雨。"]},{"t":"浦长源林亭远岫图","f":"五言绝句","c":["崇山千仞馀，历览不盈尺。","亭中人未来，烟霞日朝夕。"]},{"t":"画 其一","f":"五言绝句","c":["山雨忽开霁，溪流绕茆屋。","时有濯缨人，云端看飞瀑。"]},{"t":"画 其二","f":"五言绝句","c":["饥禽值游蜂，欲喙屡张口。","那知挟弹儿，林间候之久。"]},{"t":"春望","f":"五言绝句","c":["西望北高峰，南瞻东海水。","不是登吴山，那知春万里。"]},{"t":"剡西八景为开明空相寺僧华月江赋 其一 乌石卧云","f":"五言绝句","c":["青天堕玄云，万古收不起。","毋劳一点头，已悟二生理。"]},{"t":"剡西八景为开明空相寺僧华月江赋 其二 南轩进月","f":"五言绝句","c":["月到南轩外，中庭可一方。","开门才放入，满室白毫光。"]},{"t":"剡西八景为开明空相寺僧华月江赋 其三 梅林逗阴","f":"五言绝句","c":["绿阴坐昼寒，林深不知路。","子熟定何时，山中雨如雾。"]},{"t":"剡西八景为开明空相寺僧华月江赋 其四 竹窗挹秀","f":"五言绝句","c":["三面连高竹，苍凉画亦迷。","道人参玉版，窗下说曹溪。"]},{"t":"剡西八景为开明空相寺僧华月江赋 其五 眺白凭阑","f":"五言绝句","c":["凭阑见西山，满目青历历。","太白如可招，三美无花笛。"]},{"t":"剡西八景为开明空相寺僧华月江赋 其六 临清涤砚","f":"五言绝句","c":["砚垢须频涤，何如只洗心。","纤尘浑不染，顽石变黄金。"]},{"t":"剡西八景为开明空相寺僧华月江赋 其七 双桂秋芳","f":"五言绝句","c":["西方金粟身，仁立双林下。","给园无秋风，布地却非假。"]},{"t":"剡西八景为开明空相寺僧华月江赋 其八 孤松晚翠","f":"五言绝句","c":["岁晚归来日，苍枝忽转东。","神龙能护法，日夜吼天风。"]},{"t":"画 其一","f":"曲","c":["寻源幽涧长往，倚杖斜阳未还。","桥下潺潺春水，和云流出空山。"]},{"t":"画 其二","f":"曲","c":["春日村村花柳，人家处处桑麻。","小艇却寻溪转，好山不用云遮。"]},{"t":"画 其三","f":"曲","c":["小艇东去西去，长江朝流暮流。","笑入芦花深处，清风明月悠悠。"]},{"t":"画 其四","f":"曲","c":["问讯南屏隐者，草堂竹树谁栽。","昨夜何时雨过，山禽几个飞来。"]},{"t":"画 其五","f":"曲","c":["长松落落千丈，大厦渠渠万间。","应笑樗材拥肿，等闲空老深山。"]},{"t":"画 其六","f":"曲","c":["童子携瓶沽酒，仆夫汲水煎茶。","坐对青山扪虱，不妨终老烟霞。"]},{"t":"画 其七","f":"曲","c":["石上悠然独酌，空山谁与相亲。","满目长松流水，安知不是佳宾。"]},{"t":"高士谦墨竹 其一 雨竹","f":"曲","c":["阴浓愈觉重叠，翠湿何曾动摇。","静里试听馀韵，评来清胜芭蕉。"]},{"t":"高士谦墨竹 其二 晴竹","f":"曲","c":["新篁解箨春尽，畏日移阴昼长。","一枕南薰破梦，时闻粉节吹香。"]},{"t":"高士谦墨竹 其三 风竹","f":"曲","c":["紫极宫中暂宿，黄陵庙下曾行。","一夜洞庭木落，打窗都是秋声。"]},{"t":"高士谦墨竹 其四 雪竹","f":"曲","c":["天寒翠袖正薄，月满琼枝又新。","祗恐凤凰巢冷，截筒吹转阳春。"]},{"t":"画梅","f":"曲","c":["乱插繁花晴昊，不禁冷蕊疏枝。","江树垂垂又发，无声总是新诗。"]},{"t":"双松独步图","f":"曲","c":["高士清癯比鹤，长松夭矫犹龙。","如在山阴道上，经行万壑千峰。"]},{"t":"墨竹 其一","f":"曲","c":["笔下筼筜有谷，胸中清渭成川。","为问湖州老可，何如赤壁坡仙。"]},{"t":"墨竹 其二","f":"曲","c":["山童偶敲茶臼，野老闲歌竹枯。","明月不离襟袖，好风都在蒲葵。"]},{"t":"墨竹 其三","f":"曲","c":["墨君写以老可，石丈拜之来颠。","何似王维高适，一时诗崡同传。"]},{"t":"枯木竹石","f":"曲","c":["脩篁美如君子，古木秀似衰翁。","赖有米家石丈，挥毫正待南宫。"]},{"t":"林子山画二首 其一 春山趣游","f":"七言绝句","c":["蹇驴随意踏苍苔，行到溪桥首重回。","想得山家春尚早，过墙桃李未全开。"]},{"t":"林子山画二首 其二 秋江意钓","f":"七言绝句","c":["雨过矶头流水香，水深更放钓丝长。","分明一段江南意，枫叶芦花共夕阳。"]},{"t":"沈思礼画 其一","f":"七言绝句","c":["渔在江湖樵在林，相逢肯信有机心。","沙鸥尚未能忘我，飞过云山不可寻。"]},{"t":"沈思礼画 其二","f":"七言绝句","c":["隔水楼台映翠微，山桃风暖欲花飞。","一溪春水深无主，却被诗人载得归。"]},{"t":"杨生溪居图","f":"七言绝句","c":["满眼溪山庵尽开，草玄亭子半荒苔。","如何秪写渔家意，不及扁舟载酒来。"]},{"t":"阎仲彬墨菊","f":"七言绝句","c":["立本丹青不自誇，戏拈秃笔写秋花。","秪疑风雨重阳日，夜访柴桑处士家。"]},{"t":"次徐总制韵 其一","f":"七言绝句","c":["柳绕沙堤花绕城，千门万户赏春晴。","谁知画戟凝香处，人与湖山一样清。"]},{"t":"次徐总制韵 其二","f":"七言绝句","c":["燕子来时花满城，海棠丝雨半笼晴。","行人最爱西湖水，流入官河也自清。"]},{"t":"孙生二画 其一 槐安国","f":"七言绝句","c":["木槐为国竟如何，梦境浑如世事多。","老我久无名利念，笈看行蚁上南柯。"]},{"t":"孙生二画 其二 竹叶舟","f":"七言绝句","c":["长安流落嗼途穷，一叶归舟便向东。","咫尺图中能缩地，秪疑山叟是壶公。"]},{"t":"破窑图","f":"七言绝句","c":["日暮归来雪已深，破窑无奈夜沉沉。","谁知拨尽寒炉火，鍊出经纶一片心。"]},{"t":"并入易履墨菊","f":"七言绝句","c":["写到黄花韵更高，墨池秋水染鹅毛。","幽香一掬谁分得，知是并州快剪刀。"]},{"t":"春色","f":"七言绝句","c":["寒不能生暖不消，融融转觉望中遥。","东皇富贵谁能识，尽把黄金铸柳条。"]},{"t":"草堂图","f":"七言绝句","c":["锦江玉垒入霜毫，亦有人家荫白茅。","道是草堂元来信，秪因梅柳是西郊。"]},{"t":"贾岛推敲图","f":"七言绝句","c":["蹇驴随处恣游遨，京兆相逢即定交。","看取古人三百首，工夫元不在推敲。"]},{"t":"西湖渔者","f":"七言绝句","c":["家住钱唐西子湖，钓竿几度拂珊瑚。","扁舟载月归来晚，不觉全身入画图。"]},{"t":"钓台图","f":"七言绝句","c":["夷惠真为百世师，先生高节亦如之。","只将立懦廉顽意，九鼎分明圱一丝。"]},{"t":"访唐丹崖留饮","f":"七言绝句","c":["故人相见话襟期，草草杯盘近午时。","莫道越乡风味薄，香醪如蜜菜如丝。"]},{"t":"为朱大理赋墨梅寓丹家意以大理明此故求正云 其一","f":"七言绝句","c":["剥尽群阴见一阳，千花万蕊总包藏。","笔头会得先天意，写出寒花朵朵香。"]},{"t":"为朱大理赋墨梅寓丹家意以大理明此故求正云 其二","f":"七言绝句","c":["知白全资守黑功，一花便与万花同。","要知玉兔翻身处，春满乾坤六六宫。"]},{"t":"为朱大理赋墨梅寓丹家意以大理明此故求正云 其三","f":"七言绝句","c":["雨熟金丸万万株，黄中通理及肌肤。","此花自是真铅汞，却倩仙毫作药炉。"]},{"t":"为朱大理赋墨梅寓丹家意以大理明此故求正云 其四","f":"七言绝句","c":["真水元从火里来，等闲相过即胚胎。","檀心玉蕊分明见，莫作黄芽白雪猜。"]},{"t":"王本初小像","f":"七言绝句","c":["童子穿云得紫芝，仙翁倚杖听黄鹂。","香风两袖归来晚，正是松花落粉时。"]},{"t":"总司牛宴郑都司以所知徐总制诗见示因次其韵 其一","f":"七言绝句","c":["梅子黄时雨气凉，金炉不断热沉香。","座中总是朝天客，伋醉君门白玉觞。"]},{"t":"总司牛宴郑都司以所知徐总制诗见示因次其韵 其二","f":"七言绝句","c":["水晶帘捲午风凉，薝卜花开树树香。","独有总成偏好客，拟倾江海入壶觞。"]},{"t":"杨妃春睡图 其一","f":"七言绝句","c":["天生祸水灭炎精，能使君王万乘轻。","不独昭阳有飞燕，玉环沉醉在华清。"]},{"t":"杨妃春睡图 其二","f":"七言绝句","c":["沉香亭北好风光，春色无端属海棠。","纵使胭脂变成雪，莫教一片到渔阳。"]},{"t":"杨妃春睡图 其三","f":"七言绝句","c":["温泉浴罢力犹疲，睡足春风总不知。","香冷马嵬坡下土，令人愁诵北征诗。"]},{"t":"杨妃春睡图 其四","f":"七言绝句","c":["三十六宫春昼长，杨花扑帐暖生香。","美人毕竟成黄土，不及双丫识玉皇。"]},{"t":"观奕图为夏伯玘作","f":"七言绝句","c":["春雨春风长紫芝，山中日月自推移。","斧柯烂在松阴下，知换人间几局棋。"]},{"t":"画菜","f":"七言绝句","c":["风露含滋挟土膏，肥甘浑不让溪毛。","丹青貌得田园意，绝胜春前带雪桃。"]},{"t":"何彦恭观奕图","f":"七言绝句","c":["山风吹日昼阴阴，几见松花落远林。","总使棋枰能换世，仙人那得有机心。"]},{"t":"翠竹红梅图","f":"七言绝句","c":["绛服仙人跨翠鸾，御风乘月下瑶坛。","画图谁为开生面，留与苍官共岁寒。"]},{"t":"青山白云图","f":"七言绝句","c":["柴门无径小桥低，绿树阴阴雨后齐。","却笑白云闲不得，也随流水过溪西。"]},{"t":"江山高远图为马宪章赋","f":"七言绝句","c":["万里江山万里舟，烟云竹树远相缪。","何人写出无穷意，似记当年太史游。"]},{"t":"为杨子东题竹石扇面","f":"七言绝句","c":["歌罢南风解愠诗，含毫长想凤来仪。","明时又见箫韶作，留取苍崖碧玉枝。"]},{"t":"陈居中女猎图","f":"七言绝句","c":["猎事应难属女工，院人名尽说居中。","蛾眉狐媚唐家妇，逐鹿何曾用角弓。"]},{"t":"李思训并骑图","f":"七言绝句","c":["美人如玉马如云，误却开元万乘君。","不写班姬辞辇意，画师空说李将军。"]},{"t":"刘文质松溪小像","f":"七言绝句","c":["为听松风直过溪，长琴分与小童携。","白云不隔天台路，千树桃花一鸟啼。"]},{"t":"宋授之钟馗小妹图","f":"七言绝句","c":["戏担双鬼当双鱼，小妹停肩雪霁初。","莫道丹青资一笑，人间物物是苞苴。"]},{"t":"洗马图","f":"七言绝句","c":["层冰蹙裂度交河，天马谁能更作歌。","却忆少陵诗思好，乱蝉鸣处晚凉多。"]},{"t":"墨梅","f":"七言绝句","c":["两蕊三花便可人，分明笔底有阳春。","平生一点和羹意，不到中书未是真。"]},{"t":"画红梅","f":"七言绝句","c":["漫传丹桂冠西风，文彩重教下笔同。","谁信岁寒冰雪后，花中还有状元红。"]},{"t":"画 其一","f":"七言绝句","c":["溪山花柳斗清妍，几度春来放酒船。","画里生绡无一尺，为谁展尽白鸥天。"]},{"t":"画 其二","f":"七言绝句","c":["扁舟与客共游遨，风月无边入彩毫。","长为江山增感慨，后前两赋类庄骚。"]},{"t":"画 其三","f":"七言绝句","c":["柳阴楼阁又清和，拂晓薰风入扇罗。","女伴相呼知有约，水边亭子看新荷。"]},{"t":"画 其四","f":"七言绝句","c":["山寺风烟一半遮，水香知是落松花。","青鞋布袜曾来往，不记云门与若耶。"]},{"t":"画扇面","f":"七言绝句","c":["青天飞鹭柳鸣莺，万里桥头杜甫情。","何似合欢纨扇里，一联诗句却无声。"]},{"t":"龚翠岩所画煎茶索句图","f":"七言绝句","c":["玉川和靖总清标，煮茗吟梅共寂寥。","时世不同人物似，正如雪里见芭蕉。"]},{"t":"画 其一","f":"七言绝句","c":["云白山青万古春，桃花屋底读书人。","扁舟忽有东来客，笈指飞流得句新。"]},{"t":"画 其二","f":"七言绝句","c":["闲里琴书白日长，岸花相妾水花香。","桥东信马吟诗客，不是若耶游冶郎。"]},{"t":"道原为慧公赋","f":"七言绝句","c":["著意穷原莫外求，随波逐混是凡流。","泠泠一勺谁能识，又在曹溪最上头。"]},{"t":"九日前二日陈子善送酒并诗一绝因用其韵以谢 其一","f":"七言绝句","c":["秋丛绕舍樽无绿，九日风光不称贫。","谁信柴桑千载后，东篱重见白衣人。"]},{"t":"九日前二日陈子善送酒并诗一绝因用其韵以谢 其二","f":"七言绝句","c":["青州从事声名重，过我篷门不厌贫。","白菊花前上弦月，会须对饮作三人。"]},{"t":"雪中骑驴图","f":"七言绝句","c":["山耸寒肩乱岣劳，蹇驴冲雪尚游遨。","野桥谩道关清思，不及袁安卧最高。"]},{"t":"沈炜扇上竹","f":"七言绝句","c":["昔人种竹绕东村，雨后曾看长子孙。","春梦觉来纨扇在，晓风凉月重销魂。"]},{"t":"宋复古画","f":"七言绝句","c":["老知书画益人多，奈此无情岁月何。","欢识营丘平淡意，高堂秉烛看岷峨。"]},{"t":"孔子送周元亮先生因以诗索之","f":"七言绝句","c":["秋风篱落漫徘徊，那得黄花大似杯。","谁送草庭三四朵，可能分寄一枝来。"]},{"t":"高士谦所画烟竹","f":"七言绝句","c":["江上秋阴生暮寒，平林浑似老年看。","九疑霭霭云深处，更得诗人眼界宽。"]},{"t":"裴日英水墨莲塘四禽图","f":"七言绝句","c":["香销太液锦云空，长使诗人忆汉宫。","青鸟不来仙仗远，露盘无力倚秋风。"]},{"t":"鼠衔芦菔图","f":"七言绝句","c":["学圃经年不惮劳，野人生意满东皋。","种来芦菔从蔜吃，懒用随身却鼠刀。"]},{"t":"墨梅","f":"七言绝句","c":["姑射仙人冰雪肌，夜乘明月访瑶池。","自怜绰约谁能见，却被龙香道士知。"]},{"t":"元夕联句","f":"七言绝句","c":["过雨天街月色新，楼台灯火照阳春。","盍簪赖有诸公子，总是东风得意人。"]},{"t":"傲窗诗卷","f":"七言绝句","c":["偶向南窗倚暮秋，寄情宁复傲公侯。","谁知容膝无多地，高似元龙百尺楼。"]},{"t":"为安道题墨竹","f":"七言绝句","c":["何事清风满剡溪，琅玕长得与云齐。","此君若得王猷见，兴尽应须为品题。"]},{"t":"梁大用所作青松红梅二画 其一","f":"七言绝句","c":["仙馆长松老更奇，过门曾见出墙枝。","谁传月下蛟龙影，应有风雷起砚池。"]},{"t":"梁大用所作青松红梅二画 其二","f":"七言绝句","c":["占得魁名即赐绯，调羹心事尚依依。","玉堂别有如椽笔，更待春风为发挥。"]},{"t":"方李长所作梅竹 其一","f":"七言绝句","c":["竹里梅花巧耐寒，正如红袖倚阑干。","诗翁传淂春风面，曾在家山别墅看。"]},{"t":"方李长所作梅竹 其二","f":"七言绝句","c":["竹传唐帖双钩法，梅效徐家没骨图。","谁道茂林春已暮，不知春色在西湖。"]},{"t":"渊明像","f":"七言绝句","c":["两晋文章在此翁，阳秋都寄杖藜中。","诗人秪写归来意，不道闲情似国风。"]},{"t":"画","f":"七言绝句","c":["草堂筑得傍林丘，溪友相过即放舟。","翻爱白云如画意，终朝长在碧山头。"]},{"t":"沈养性画","f":"七言绝句","c":["长虹如瀑蛎如山，万竹深藏屋数间。","夜半秋声最堪听，抱琴来此不须还。"]},{"t":"鬼猎图 其一","f":"七言绝句","c":["飞鹰走狗猎山坡，狐兔全驱入网罗。","不有唐家钟进士，人间魑魅更应多。"]},{"t":"鬼猎图 其二","f":"七言绝句","c":["谁遣馗翁作鬼雄，形容彷佛记唐宫。","山林川泽今无此，转忆先生铸鼎功。"]},{"t":"鬼猎图 其三","f":"七言绝句","c":["虚耗驱除若羽毛，开元天子赐蓝袍。","空令鬼物持戎器，不管雄狐向窟嗥。"]},{"t":"渭川烟雨图","f":"七言绝句","c":["渭川曾见竹青青，和雨和烟画杳冥。","不似九疑云雾隔，空教瑶瑟怨湘灵。"]},{"t":"牧牛图","f":"七言绝句","c":["桃林地瘠奈牛何，此日周王已止戈。","芳草平原春万里，牧童能唱太平歌。"]},{"t":"赤壁图","f":"七言绝句","c":["江水东流赤壁孤，曹瞒曾此战周瑜。","山川不逐英雄去，却为坡仙入画图。"]},{"t":"滕王阁图","f":"七言绝句","c":["画栋朱帘云雨间，朝看南浦暮西山。","风帆不送诗人到，高阁临江亦等闲。"]},{"t":"裴日英墨菊","f":"七言绝句","c":["披图便欲醉秋光，映竹幽花似有香。","昨日山中新酒熟，先生闲户作重阳。"]},{"t":"秋山渔影图为方仲敏赋","f":"七言绝句","c":["秋色都从点染成，白云妚树故山情。","溪渔钓得归来得，卧听松窗瀑布声。"]},{"t":"林子山诗意扇面","f":"七言绝句","c":["门前春水碧如苔，不见鸥来见鹤来。","翻意断桥曾唤渡，满身花雨荡舟回。"]},{"t":"钱宗文扇","f":"七言绝句","c":["吴淞江上见秋风，水色山光下笔同。","闻道四腮驴最美，几时归去作渔翁。"]},{"t":"为沈景玉题高士谦所作烟雨万竿图","f":"七言绝句","c":["影薄犹疑翠袖寒，东林日暮忆曾看。","渭川千亩谁能写，烟雨空濛千万竿。"]},{"t":"高士谦竹石扇面","f":"七言绝句","c":["何处参差舞翠鸾，瑶台明镜上云端。","如今织女支机石，也被姮娥借得看。"]},{"t":"林子山画菜上有蜗牛故及之","f":"七言绝句","c":["晓畦春雨细如毛，菜本青肥挟土膏。","叶底蜗牛曾湿久，诗人犹欲剌升高。"]},{"t":"渔隐图","f":"七言绝句","c":["渔者虽多屡数难，磻溪彷佛到严滩。","东都名教西周业，不枉人间把钓竿。"]},{"t":"杏花暮雨图","f":"七言绝句","c":["杏花庭院暮寒多，酒醒其如客思何。","绛蜡烧残犹觅句，不知春雨湿渔蓑。"]},{"t":"画鱼","f":"七言绝句","c":["谁写群鱼入画图，相忘浑似在江湖。","诗人忽作丰年梦，还有宣王考牧无。"]},{"t":"为杨复初题秋江归棹图仍次其韵","f":"七言绝句","c":["不为莼鲈若忆归，缁尘惟恐上人衣。","欲知此日思亲意，长似征帆带雨飞。"]},{"t":"钱舜举二菊 其一","f":"七言绝句","c":["露华如酒晓淋漓，醉色和秋上别枝。","若使罗虬重有作，此花瑞合比红儿。"]},{"t":"钱舜举二菊 其二","f":"七言绝句","c":["尽道西施类玉环，多因醉里认容颜。","馆娃宫与华清似，都在秋风十二鬟。"]},{"t":"裴日英墨菊","f":"七言绝句","c":["浓墨淋漓写折枝，便从纸上见东篱。","玉蟾分得南阳水，一衣秋香满砚池。"]},{"t":"邹汝舟画","f":"七言绝句","c":["童子言师去未还，采芝多在白云间。","谁知流水桃花外，更有高人卧碧山。"]},{"t":"青山白云图","f":"七言绝句","c":["何处青山无白云，每来松顶便氤氲。","儿童不识飞扬意，刚道摩霄是鹤群。"]},{"t":"二仙图","f":"七言绝句","c":["松枯石烂自春秋，游入依然昼夜流。","要觉仙人忘世虑，未应钟吕胜巢由。"]},{"t":"墨梅","f":"七言绝句","c":["每爱高人杨补之，小窗横幅写疏枝。","繁花乱插当晴昊，胜似黄昏月上时。"]},{"t":"方季长画","f":"七言绝句","c":["家山移在画图间，桑柘连村水一弯。","知是方千高隐处，白云长为护柴关。"]},{"t":"芙蓉狮犬图","f":"七言绝句","c":["太液芙蓉秋苑深，闲看双犬吠花阴。","旅獒写出忠君意，未必丹青识此心。"]},{"t":"刘耀卿雪景","f":"七言绝句","c":["健步寻梅远未还，无端诗思满溪山。","洛阳更有多风雪，独有高人昼掩关。"]},{"t":"辋川别业诗意","f":"七言绝句","c":["夏木轩窗瞰水田，黄鹂白鹭总堪怜。","那知诗到无声处，能使高人忆辋川。"]},{"t":"松雪翁兰蕙 其一","f":"七言绝句","c":["干密花疏更作丛，深林空谷自春风。","王孙去后多芳草，零落馀香茧纸中。"]},{"t":"松雪翁兰蕙 其二","f":"七言绝句","c":["翠转光风百里馀，吴兴画法宛如书。","凄凉九辩无人诵，空忆中庭雪霁初。"]},{"t":"柯敬仲墨竹","f":"七言绝句","c":["闻韶曾见凤来仪，回首苍梧又一时。","写出竹枝歌外意，楚云湘水不胜悲。"]},{"t":"马虚中剡溪图 其一","f":"七言绝句","c":["清兴都生眺望间，放舟溪上又空还。","道人笔底天机熟，尽把云山变雪山。"]},{"t":"马虚中剡溪图 其二","f":"七言绝句","c":["鸡黍交情不可违，如何兴尽便空归。","诗翁偶写胸中趣，肯道溪山有是非。"]},{"t":"钟馗","f":"七言绝句","c":["柳梢风转不多寒，薄雪初消路未乾。","应笑髯翁殊矍铄，也随春色上长安。"]},{"t":"王元章墨梅并次诗韵","f":"七言绝句","c":["山阴陈迹老莓苔，为探梅花踏雪来。","传淂一枝溪上景，眼明相见亦惊猜。"]},{"t":"吴以道扇","f":"七言绝句","c":["清溪雨过晚渔蓑，倒坐船头逸兴多。","只有好山看不厌，又随图画入轻罗。"]},{"t":"高士谦竹石","f":"七言绝句","c":["秋色分毫待客挥，云根烟筱巧相依。","梦回记得吹笙处，倒跨青鸾月下归。"]},{"t":"画梅纸扇","f":"七言绝句","c":["剡藤湘竹付良工，扑蝶轻罗巧与同。","谁向炎天写梅蕊，仁风都在动摇中。"]},{"t":"为潘晋之题忠孝图","f":"七言绝句","c":["石畔葵萱总看花，黄金杯侧注丹砂。","艾宣笔意谁传得，孝子忠臣在一家。"]},{"t":"画梅","f":"七言绝句","c":["花纵繁时影亦疏，瑶台和月夜模糊。","何人识得春风面，收拾馀香入画图。"]},{"t":"为夏节题子昂画白马","f":"七言绝句","c":["十二天闲烂锦云，世人专美五花文。","吴门匹练吴兴笔，一出能空冀北群。"]},{"t":"倦绣图","f":"七言绝句","c":["纂组犹能害汝功，倦容谁为写东风。","空知想像唐宫事，绣出杨家一捻红。"]},{"t":"墨菊","f":"七言绝句","c":["鹅毛剪得墨淋漓，香满秋风洗砚池。","画法若从书法入，赵昌应也学羲之。"]},{"t":"王叔明画次张一笑韵","f":"七言绝句","c":["高人自是爱林泉，每向山中枕石眠。","今日偶然溪上去，松风吹转橛头船。"]},{"t":"竹石扇面","f":"七言绝句","c":["雨细珊瑚晚未乾，秋声一叶满西阑。","何人手把青鸾尾，扫退浮云看广寒。"]},{"t":"画棘丛白头翁","f":"七言绝句","c":["鸟中亦有白头翁，底事卑栖向棘丛。","不道朝阳孤凤好，飞鸣元只在梧桐。"]},{"t":"画 其一","f":"七言绝句","c":["枯树婆娑近竹丛，欲将心事托春风。","江南庾信今头白，不为愁多赋未工。"]},{"t":"画 其二","f":"七言绝句","c":["抱画求题莫厌频，好诗比竹更清新。","坐来不待风敲户，满眼相看是故人。"]},{"t":"柯敬仲竹为陈常仲赋","f":"七言绝句","c":["奎章阁下日谈经，曾写幽姿上御屏。","云暗苍梧清泪尽，空教瑶瑟怨湘灵。"]},{"t":"徐子方竹","f":"七言绝句","c":["蝌蚪曾闻写汗青，先生人复理图经。","故人赠竹缘何事，要使清风满笏庭。"]},{"t":"徐希杰二色梅图 其一","f":"七言绝句","c":["酒痕晕透雪饥肤，红影春园见一株。","好似石家金谷里，戏将如意击珊瑚。"]},{"t":"徐希杰二色梅图 其二","f":"七言绝句","c":["疏影曾看上薄纱，挥毫落纸使横斜。","骊珠一颗谁探得，散作东风满树花。"]},{"t":"松云王为周元亮作露华清晓图同张一笑方竹居俞紫芝题其上","f":"七言绝句","c":["爱菊渊明后鲜闻，濂溪孙子况能文。","露华清晓凉如许，湿却松间一段云。"]},{"t":"李景中待月延桂图","f":"七言绝句","c":["阑倚西风月未生，露凉转觉桂香清。","诗成月在桂花上，此景如何画得成。"]},{"t":"为徐子方题徐熙杏花青鸟","f":"七言绝句","c":["青色分红闹别枝，写生谁复似徐熙。","露华不在金茎上，青鸟飞来也自疑。"]},{"t":"方方壶画","f":"七言绝句","c":["画到方壶思不群，乱山佳处屋平分。","溪头艇子如梭大，只许先生载白云。"]},{"t":"王叔明为俞子贤作山居图于尚友堂后为郑敬常所得俾题其上","f":"七言绝句","c":["画把交游迹已陈，西庄依旧锁松筠。","也知谷口烟霞趣，造物应留待子真。"]},{"t":"沈景王画","f":"七言绝句","c":["云压春山远更低，心知是画德空迷。","林间亭子无人到，雨脚垂垂欲度溪。"]},{"t":"李迪梅","f":"七言绝句","c":["抱子攀萝过别枝，满身松露湿金丝。","冷泉不复闻清啸，把烛观图有所思。"]},{"t":"溪山才子图","f":"七言绝句","c":["曲折清溪有路通，吟诗驴背任西东。","披图记得经行处，人在千山万木中。"]},{"t":"鹰","f":"七言绝句","c":["擒来凡鸟不言巧，狡兔妖狐穴未空。","四顾激昂如有待，平原昨夜起秋风。"]},{"t":"溪山图为张长司一中题","f":"七言绝句","c":["西塞山明碧王如，桃花流水称舟居。","玄真心事非张翰，不为鲈鱼为鳜鱼。"]},{"t":"明辨之画","f":"七言绝句","c":["云抹山腰晚更奇，高人应不愧王维。","钓丝收起船头坐，看到风波欲定时。"]},{"t":"赠沈山樵","f":"七言绝句","c":["连蜷雌霓赋中闻，别有山樵管白云。","能为苍生作霖雨，道人应不愧休文。"]},{"t":"画鸡","f":"七言绝句","c":["萱草丛高石渐低，薰风庭院午时鸡。","偶因元日同观画，笑饮屠苏为品题。"]},{"t":"杨懋臣以红墨梅二幅赠彦真命题其上 其一","f":"七言绝句","c":["珊瑚击碎冷无声，散作疏花点点明。","远寄馀音溪上去，春风百里故人情。"]},{"t":"杨懋臣以红墨梅二幅赠彦真命题其上 其二","f":"七言绝句","c":["人到英溪识浚仪，寒窗索句重相思。","江空岁晚无芳草，聊折琼瑶赠一枝。"]},{"t":"寒江独钓图","f":"七言绝句","c":["诗画难评劣与优，声无声有巧相侔。","寒江钓雪何人笔，得句真如柳柳州。"]},{"t":"俞文辅墨菊","f":"七言绝句","c":["间色幽花却耐看，墨香和露不曾乾。","魏家池馆如栽得，唤作秋风小牡丹。"]},{"t":"赵休穆画马","f":"七言绝句","c":["吴兴自得曹韩法，父子丹青更一家。","神骏按图犹不识，空今天马涉流沙。"]},{"t":"梅月水仙图","f":"七言绝句","c":["形影相看愈觉真，花中人是月中人。","丹青想像惊鸿态，不及思王赋洛神。"]},{"t":"画菜 其一","f":"七言绝句","c":["寒士须尝百瓮齑，莫教此色到群黎。","盐梅不入和羹用，空使君王梦蔡齐。"]},{"t":"画菜 其二","f":"七言绝句","c":["一抹生红著土酥，曾同菘菜付庖厨。","先生欲补冰壶传，燥吻时时看画图。"]},{"t":"为沈竹窗题竹梅二图 其一","f":"七言绝句","c":["生纸何人写墨君，翠痕馀处白纷纷。","翻疑手把孤鸾尾，扫出南山一段云。"]},{"t":"为沈竹窗题竹梅二图 其二","f":"七言绝句","c":["寻花曾记历山坡，年后如何却厌多。","赖有小窗横幅在，空将老眼重摩挲。"]},{"t":"戊午元夕遇雨次莫景行韵 其一","f":"七言绝句","c":["张灯秪许到更阑，纵有笙歌懒作欢。","空忆旧时明月色，连宵还恨不曾看。"]},{"t":"戊午元夕遇雨次莫景行韵 其二","f":"七言绝句","c":["门门种树翠成层，准拟元宵映綵棚。","游兴不因风雨阻，夜窗闲却读书灯。"]},{"t":"庐山图","f":"七言绝句","c":["梦里庐山亦偶然，披图重见意犹怜。","白云万顷松千个，看得人间李谪仙。"]},{"t":"马麟长春蝶并杨太后扑蝶图二小幅成一卷","f":"七言绝句","c":["蝶骇花飞春事无，扇罗又见内家姝。","昆虫草木端平画，不是豳风七月图。"]},{"t":"枯林墨蕙","f":"七言绝句","c":["转蕙光风百里馀，空庭曾见雪消初。","数丛一干谁能写，笔法浑如贝叶书。"]},{"t":"僧月海兰蕙","f":"七言绝句","c":["光风转蕙汎崇兰，墨润浑疑露未乾。","春色夜来深似海，空留清影月中看。"]},{"t":"画 其一 太白诗意","f":"七言绝句","c":["君去还当我醉时，东坡解道谪仙诗。","百年粉素消磨尽，犹有山花一两枝。"]},{"t":"画 其二 少陵诗意","f":"七言绝句","c":["谁写江村枫树林，草堂如有客相寻。","野船怪得轻如叶，秋水今朝五尺深。"]},{"t":"五花马图","f":"七言绝句","c":["八尺乌骓散五花，披图一见重咨嗟。","何人笔底藏风雨，解使神龙起渥洼。"]},{"t":"张复初松下垂钓图","f":"七言绝句","c":["春雨朝朝长绿波，桃花时节鳜鱼多。","遥知松下投竿者，定是当年老志和。"]},{"t":"徐陵墨梅","f":"七言绝句","c":["尽道徐熙似赵昌，墨花有韵却无香。","诗人又动杨州兴，春色真疑到玉堂。"]},{"t":"扇面山水","f":"七言绝句","c":["溪抱重山曲曲通，野航长得载诗翁。","旧时纨扇丹青在，不入凉风箧笥中。"]},{"t":"俞碧窗画紫菊","f":"七言绝句","c":["菊有黄花秋满篱，谁看紫艳半开时。","碧窗分得研朱露，写出无声赵嘏诗。"]},{"t":"戊午七月六日书事 其一","f":"七言绝句","c":["徒步寻僧岂得舟，过门不接慢迟留。","炎天赤日空乘兴，笑杀山阴王子猷。"]},{"t":"戊午七月六日书事 其二","f":"七言绝句","c":["伏日殊无兴可秉，欲谈儒墨重寻僧。","茶瓜不解留佳客，笑杀成都杜少陵。"]},{"t":"钓鱼图","f":"七言绝句","c":["衣食全家寄一丝，人间荣辱几曾知。","瓦瓯蓬底高歌起，正是鲈鱼上钓时。"]},{"t":"洛神图","f":"七言绝句","c":["子建才名托楚辞，为因留枕寄相思。","泱泱洛水清无底，谁见惊鸿照影时。"]},{"t":"画","f":"七言绝句","c":["欲向春山访隐君，野桥行过路才分。","上方楼阁应无数，留与闲僧管白云。"]},{"t":"为赵玘题高士谦墨竹","f":"七言绝句","c":["公子翩翩也自佳，从人写竹写幽怀。","只今有酒谁浇笔，能使清风到小斋。"]},{"t":"姚伯和所藏五马图","f":"七言绝句","c":["识得骊黄不在毛，天机从此付霜毫。","使君五马行春处，犹忆城西看小桃。"]},{"t":"墨梅","f":"七言绝句","c":["才见花开似见春，江空岁晚寄何人。","芳香只恐有消歇，凭伏金壶墨写真。"]},{"t":"画红梅","f":"七言绝句","c":["花到浓时花欲无，桃嫌太俗杏嫌粗。","孤山别有春风面，消得徐熙没骨图。"]},{"t":"洛神图","f":"七言绝句","c":["嬉游湍濑采玄芝，罗袜淩波不自持。","毕竟形容何所似，玉芙蓉在碧琉璃。"]},{"t":"阎中得画","f":"七言绝句","c":["杖头驴背又微吟，君出深山我入林。","邂逅不须交一语，春来花鸟总关心。"]},{"t":"吴孟文水影月香图 其一","f":"七言绝句","c":["却因清浅见横斜，水是湖湾影是花。","赖有吴生能写得，不须重到老逋家。"]},{"t":"吴孟文水影月香图 其二","f":"七言绝句","c":["欲知浮动近黄昏，风有清香月有痕。","貌得玉妃真面目，缟衣无复夜敲门。"]},{"t":"题梅用陆柳洲寄杨村居韵","f":"七言绝句","c":["数枝开傍石桥西，纵有寒香蝶不栖。","何似南山千百树，梨花落寞路都迷。"]},{"t":"画兰 其一","f":"七言绝句","c":["萋萋芳草空无数，惆怅王孙去不归。","何似幽兰纫作佩，也胜游子芰荷衣。"]},{"t":"画兰 其二","f":"七言绝句","c":["深林绿艳恐消歇，故假人间膏沐容。","忽见一丛崖石上，动摇浑似汎光风。"]},{"t":"吴孟文墨梅","f":"七言绝句","c":["吴生妙绝宫墙画，不向冰纨寄墨痕。","怪得炎天见梅蕊，姚江知有季章孙。"]},{"t":"吴孟文以古蜡笺画梅因赋","f":"七言绝句","c":["旧笺新墨未曾乾，如倚黄昏月下阑。","不是一枝斜更好，令人误作蜡花看。"]},{"t":"吴孟文以白团扇画梅因赋","f":"七言绝句","c":["海波寒浸玉蟾蜍，勾引清风入座隅。","借得诗人掣鲸手，骊龙颔下摘明珠。"]},{"t":"溪居图","f":"七言绝句","c":["水上风来麦气生，绿阴窗户有棋声。","桃花不隔仙源路，应使秦人见太平。"]},{"t":"二仙像 其一 铁拐","f":"七言绝句","c":["一拐随身四海闻，剑锋久暗七星文。","等闲磨砺光芒出，划断青天万里云。"]},{"t":"二仙像 其二 风僧","f":"七言绝句","c":["似醉如痴不顾身，谁知一一露天真。","露台便是中秋月，养就蟾蜍白胜银。"]},{"t":"月娥扇面","f":"七言绝句","c":["灵药当年悔一偷，海天空度几春秋。","凉飙又改班姬扇，莫道孀娥不解愁。"]},{"t":"陆本高镜奁红梅","f":"七言绝句","c":["要将明镜别妍媸，勋业频看祗自疑。","红艳一枝谁为写，倚阑人在影娥池。"]},{"t":"群峰春晓图赠王士贞之官三山","f":"七言绝句","c":["唱彻阳关酒未阑，渭城朝雨别篱难。","三山春色多于柳，总在王维画里看。"]},{"t":"乔松双鹄图为俞仲和赋","f":"七言绝句","c":["一个长松雨鹤栖，上头不许子规啼。","仙翁应在春山裹，丹井云多路更迷。"]},{"t":"画梅 其一","f":"七言绝句","c":["诗到无声也自奇，眼明窗不见疏枝。","江南四月冥冥雨，空忆曹瞒止渴时。"]},{"t":"画梅 其二","f":"七言绝句","c":["每爱多才赋洛神，凌波曾见袜生尘。","谁知更有梅兄在，消得思王一写真。"]},{"t":"桂娥梅仙二图 其一","f":"七言绝句","c":["金栗平铺满树头，画阑西畔月如钩。","风鬟雾鬓归来晚，折得天香总是秋。"]},{"t":"桂娥梅仙二图 其二","f":"七言绝句","c":["倚树仙人是阿谁，雪肤花貌认参差。","恐惊青鸟枝头梦，玉笛拈来不敢吹。"]},{"t":"唐子华画","f":"七言绝句","c":["我识吴兴唐子华，丹青一出便名家。","抱琴童仆随驴去，山县今朝早放衙。"]},{"t":"卢伯庸宰水图","f":"七言绝句","c":["桃李家山春欲无，草堂留得望西湖。","墓门宰木今如许，惆怅临风展画图。"]},{"t":"画梅 其一","f":"七言绝句","c":["墨作南枝却耐看，北枝何似怯馀寒。","诗人不用劳区别，开到春来总一般。"]},{"t":"画梅 其二","f":"七言绝句","c":["飞来峰下雪垂垂，近水人家玉两枝。","燕子春寒来不得，却教鸿雁见开时。"]},{"t":"海棠白头翁鸟图","f":"七言绝句","c":["驷马桥边忆旧游，海棠红湿雨初收。","春禽似识文园令，也向花前叹白头。"]},{"t":"高房山画","f":"七言绝句","c":["尚书京口住经年，每写云山出自然。","此幅得来如有意，虹光曾射米家船。"]},{"t":"咏海棠","f":"七言绝句","c":["春色三分已二分，海棠红软半梨云。","银缸休照东风树，愁杀杨州杜使君。"]},{"t":"三香图","f":"七言绝句","c":["淮山彭泽与沅湘，几度经行揽众芳。","梦觉广寒环佩远，却将吟笔写秋香。"]},{"t":"题竹并梅兰图 其一","f":"七言绝句","c":["卖珠不惜买芳春，山暮天寒翠袖新。","竹外一枝谁貌得，分明空谷见佳人。"]},{"t":"题竹并梅兰图 其二","f":"七言绝句","c":["江上寒梅已报春，幽兰还与斗清新。","纤毫解把明珠赠，信有湘皋解佩人。"]},{"t":"画扇面 其一","f":"七言绝句","c":["阿母蟠桃花又红，七香车下五云中。","群仙奏罢霓裳曲，春满瑶台第一宫。"]},{"t":"画扇面 其二","f":"七言绝句","c":["万户千门锦绣堆，沉香亭北看花开。","真妃睡足初扶起，更待君王玉辇来。"]},{"t":"为方仲敏题白云深处","f":"七言绝句","c":["千山万水入登临，犬吠鸡鸣杳莫寻。","试问白云深几许，仙家更在白云深。"]},{"t":"温日观墨蒲萄 其一","f":"七言绝句","c":["风飘露洒一棚秋，路入沧江忆旧游。","凭伏金壶翻墨汁，老禅胸次有凉州。"]},{"t":"温日观墨蒲萄 其二","f":"七言绝句","c":["天风动地拂苍须，摇落骊龙颔下珠。","一斗竟须浇渴吻，道人从此厌醍醐。"]},{"t":"秋林才子图","f":"七言绝句","c":["木落山林秋满天，蹇驴背上耸吟肩。","濡桥郑綮曾如此，况是襄阳孟浩然。"]},{"t":"鉴仲明上人画","f":"七言绝句","c":["老禅曾隐虎跑泉，笔底山林似巨然。","此是太平真气象，家家茅屋起炊烟。"]},{"t":"画菜","f":"七言绝句","c":["谁写春菘入画图，借如挑得付庖厨。","此根咬得知滋味，方是人间士大夫。"]},{"t":"诗意扇面","f":"七言绝句","c":["采药仙人去未还，偶逢童子问松间。","何人解写云山意，不放青团扇影闲。"]},{"t":"题墨菊有怀王士中","f":"七言绝句","c":["采菊东篱事已非，按图长是惜芳菲。","西斋谩有盈樽酒，惆怅何由见白衣。"]},{"t":"墨菊为杨复初赋","f":"七言绝句","c":["黄花韵与墨花同，一洗人间万卉空。","不许陶潜都占断，守玄聊且效杨雄。"]},{"t":"裴日英写红梅翠竹","f":"七言绝句","c":["空谷佳人翠袖单，红颜长是怯天寒。","河东邂逅绯衣子，写作疏花竹里看。"]},{"t":"张师夔思意图","f":"七言绝句","c":["花木禅房常建诗，吴兴曾为写幽姿。","龙溪渔子天机熟，见画令人忆旧时。"]},{"t":"岁寒三友图","f":"七言绝句","c":["岁暮天寒雪四垂，竹边松下出斜枝。","似人又向图中见，方信山阴有戴逵。"]},{"t":"庄子观泉图","f":"七言绝句","c":["秋水成河灌百川，濠梁何必更观泉。","欲知无限逍遥意，总在南华第一篇。"]},{"t":"宋授之遗墨","f":"七言绝句","c":["宋玉多才赋远游，曾拈彩笔写清秋。","西风吹断南州梦，翡翠兰苕总是愁。"]},{"t":"二乔观兵书图","f":"七言绝句","c":["不为师婚不动心，肯教铜雀锁春深。","书中谩识孙吴意，何似同观女史箴。"]},{"t":"豳风图","f":"七言绝句","c":["蚕月条桑为茧丝，筑场纳稼应天时。","欲知王业艰难处，尽在豳风七月诗。"]},{"t":"行春图","f":"七言绝句","c":["野桥村店见青旗，玉勒雕鞍且缓驰。","十日春光浓似酒，等闲开尽小桃枝。"]},{"t":"墨菊","f":"七言绝句","c":["淋漓浓墨染香云，秋色秋光总不分。","醉眼只疑乌帽落，令人重忆孟参军。"]},{"t":"忠孝图","f":"七言绝句","c":["葵萼倾心向太阳，萱花树背在高堂。","忠臣孝子如佳卉，凭伏丹青为发扬。"]},{"t":"孟母断机图","f":"七言绝句","c":["慈亲教子意何如，直至三迁始定居。","一自寒机初断后，经纶都在七篇书。"]},{"t":"张骞出使图","f":"七言绝句","c":["漫从西域度流沙，八月虚回奉使槎。","天上白榆那可摘，归时只得带榴花。"]},{"t":"柳塘春水图","f":"七言绝句","c":["杨柳池塘春昼迟，画船犹记听黄鹂。","飞花又逐东流去，消尽年光总不知。"]},{"t":"桂月凭阑","f":"七言绝句","c":["银屏深掩烛烧残，金粟枝头玉露寒。","阵阵西风吹不断，肯教闲却画阑杆。"]},{"t":"秋江雁阵图","f":"七言绝句","c":["江流东去雁南翔，波影涵秋一两行。","不待平沙观落处，便从图画认潇湘。"]},{"t":"寒江钓雪图","f":"七言绝句","c":["风满空江雪满舟，一竿波面自夷犹。","钩丝更放长三尺，不信寒鱼不上钩。"]},{"t":"舜举桃花二首 其一 碧桃","f":"七言绝句","c":["花开记得涌金池，一片枝头不受吹。","十万人家春似海，瑶笙谁向月中归。"]},{"t":"舜举桃花二首 其二 绯桃","f":"七言绝句","c":["晴日蒸红烂若霞，一枝如影绿窗纱。","去年花里寻诗处，错认溪桥卖酒家。"]},{"t":"咏长桥","f":"七言绝句","c":["飞梁压水跨虹腰，知是吴江第一桥。","安得鲈鱼共樽酒，秋风亭上酹三高。"]},{"t":"梅仙图","f":"七言绝句","c":["曾向松林梦美人，雪肤花貌认来真。","一声横玉惊么凤，枝北枝南总是春。"]},{"t":"美人图 其一","f":"七言绝句","c":["白玉搔头压鬓垂，困人天气觉来迟。","帘前一任杨花过，爱惜春纤不画眉。"]},{"t":"美人图 其二","f":"七言绝句","c":["渊明谩尔赋闲情，托物如何写得成。","欲识春风无限意，樱桃花下背人行。"]},{"t":"跨驴图","f":"七言绝句","c":["曾见洪崖降雪图，寒云四野正模糊。","何如驴背驮诗去，濡岸桥头酒可沽。"]},{"t":"秋江图","f":"七言绝句","c":["极目沧浪映翠微，钓船初放客船归。","渔歌一曲长烟外，惊起沙鸥隔树飞。"]},{"t":"次韵范石湖田园杂兴诗六十首 春日十二首之一 其一","f":"七言绝句","c":["夜听檐声似雨声，晚窗操笔喜诗成。","东风消尽门前雪，又见墙阴荠菜生。"]},{"t":"次韵范石湖田园杂兴诗六十首 春日十二首之二 其二","f":"七言绝句","c":["桃杏何曾羯鼓催，春风先后自吹开。","为怜红影临清泚，不惜芒鞋得得来。"]},{"t":"次韵范石湖田园杂兴诗六十首 春日十二首之三 其三","f":"七言绝句","c":["草芽雨后一番青，处处郊原趁雨耕。","我亦村居聊避俗，傍人错比晋渊明。"]},{"t":"次韵范石湖田园杂兴诗六十首 春日十二首之四 其四","f":"七言绝句","c":["村扉寂寂掩荆柴，雨阻清明客少来。","自把新茶试新火，喜看榆柳变炉灰。"]},{"t":"次韵范石湖田园杂兴诗六十首 春日十二首之五 其五","f":"七言绝句","c":["连宵急雨送轻雷，又见郊原草色回。","此去城门三十里，踏青能有几人来。"]},{"t":"次韵范石湖田园杂兴诗六十首 春日十二首之六 其六","f":"七言绝句","c":["花柳村村社鼓喧，花含宿雨柳含烟。","野夫何处堪行乐，不是花边即柳边。"]},{"t":"次韵范石湖田园杂兴诗六十首 春日十二首之七 其七","f":"七言绝句","c":["高陂分水出湾头，宿雨晴时好放舟。","闻说春山多胜事，几时寻壑入经丘。"]},{"t":"次韵范石湖田园杂兴诗六十首 春日十二首之八 其八","f":"七言绝句","c":["筠笼采摘小童回，樱豆堆盘杂笋梅。","正尔客怀寥落甚，不妨频覆掌中杯。"]},{"t":"次韵范石湖田园杂兴诗六十首 春日十二首之九 其九","f":"七言绝句","c":["野蔌村醪暂遣怀，每呼邻叟尽馀杯。","醉来却倚柴门立，闲数昏鸦几个回。"]},{"t":"次韵范石湖田园杂兴诗六十首 春日十二首之十 其十","f":"七言绝句","c":["春日田家始作劳，下乡胥吏苦频搔。","如何学得仙源隐，不种桑麻只种桃。"]},{"t":"次韵范石湖田园杂兴诗六十首 春日十二首之十一 其十一","f":"七言绝句","c":["断岸防颓费石包，雨声又听响中宵。","杏花零落飘香远，明日扶筇度石桥。"]},{"t":"次韵范石湖田园杂兴诗六十首 春日十二首之十二 其十二","f":"七言绝句","c":["积雨初乾理菜畦，味含膏土胜酥肥。","野夫不厌根频嚼，惭愧村童日摘归。"]},{"t":"次韵范石湖田园杂兴诗六十首 晚春十二首之一 其十三","f":"七言绝句","c":["木奴花发四邻香，静里偏知日晷长。","坐久出门看野色，乱山平处是钱唐。"]},{"t":"次韵范石湖田园杂兴诗六十首 晚春十二首之二 其十四","f":"七言绝句","c":["狂蜂浪蝶尚飞翻，春去浑无一点痕。","秪有东风知客意，乱吹花片拥篱根。"]},{"t":"次韵范石湖田园杂兴诗六十首 晚春十二首之三 其十五","f":"七言绝句","c":["春色相将到楝花，柴门深掩似山家。","日长无事琴书罢，纱帽笼头自煮茶。"]},{"t":"次韵范石湖田园杂兴诗六十首 晚春十二首之四 其十六","f":"七言绝句","c":["林绕方塘水绕洲，杖藜随处得迢游。","却嫌薄暮东风急，便觉经寒似麦秋。"]},{"t":"次韵范石湖田园杂兴诗六十首 晚春十二首之五 其十七","f":"七言绝句","c":["田头纵步午风凉，陂水青青浸稻秧。","爱杀檐前双燕子，落花多处得泥香。"]},{"t":"次韵范石湖田园杂兴诗六十首 晚春十二首之六 其十八","f":"七言绝句","c":["蚕事忙时三月中，苍苔门径少人踪。","抱篮知是谁家女，偶向柔柔陌上逢。"]},{"t":"次韵范石湖田园杂兴诗六十首 晚春十二首之七 其十九","f":"七言绝句","c":["水村高下自成围，处处人家白板扉。","榆荚杨花正无赖，等闲又欲送春归。"]},{"t":"次韵范石湖田园杂兴诗六十首 晚春十二首之八 其二十","f":"七言绝句","c":["门外都无车马尘，绿阴幽草与时新。","小窗日日风兼雨，赖有蔷薇占得春。"]},{"t":"次韵范石湖田园杂兴诗六十首 晚春十二首之九 其二十一","f":"七言绝句","c":["水面秧针长绿茸，雨馀樱颗染深红。","东皋伫想生盈陌，西蜀应知赠满笼。"]},{"t":"次韵范石湖田园杂兴诗六十首 晚春十二首之十 其二十二","f":"七言绝句","c":["晴云满户日光迟，柏子烧残火渐微。","人在小轩闲读易，一双蝴蝶上阶飞。"]},{"t":"次韵范石湖田园杂兴诗六十首 晚春十二首之十一 其二十三","f":"七言绝句","c":["酴醾压架雪成堆，一日须看一百回。","满袖清香浑不记，却怜蜂蝶趁人来。"]},{"t":"次韵范石湖田园杂兴诗六十首 晚春十二首之十二 其二十四","f":"七言绝句","c":["雨中红迤晓来稀，愁见花飞镇掩扉。","不是杜鹃啼彻夜，无人知道又春归。"]},{"t":"次韵范石湖田园杂兴诗六十首 夏日十二首之一 其二十五","f":"七言绝句","c":["重重绿叶障林肥，点点黄花入麦稀。","绝似辋川图画里，水田时有鹭鹚飞。"]},{"t":"次韵范石湖田园杂兴诗六十首 夏日十二首之二 其二十六","f":"七言绝句","c":["乱蛙声急雨声寒，坐拥衾裯尚觉单。","畎亩却思天下事，几时民受一分宽。"]},{"t":"次韵范石湖田园杂兴诗六十首 夏日十二首之三 其二十七","f":"七言绝句","c":["闲看行蚁上苔钱，日永依稀似小年。","麦饭正香葵菜熟，祗将耕凿报尧天。"]},{"t":"次韵范石湖田园杂兴诗六十首 夏日十二首之四 其二十八","f":"七言绝句","c":["稻秧新插绿如波，正值田头雨一蓑。","未到秋成先有望，差科不比去年多。"]},{"t":"次韵范石湖田园杂兴诗六十首 夏日十二首之五 其二十九","f":"七言绝句","c":["人生出处在知几，西塞山空鹭自飞。","学取玄真归隐好，钓船闲理绿蓑衣。"]},{"t":"次韵范石湖田园杂兴诗六十首 夏日十二首之六 其三十","f":"七言绝句","c":["略彴歌斜跨浅流，茅茨萧洒枕清沟。","绿阴满地无来客，忽听蝉声起树头。"]},{"t":"次韵范石湖田园杂兴诗六十首 夏日十二首之七 其三十一","f":"七言绝句","c":["屋后方池可沤麻，暗分流水过邻家。","人间有地皆堪隐，不独青门好种瓜。"]},{"t":"次韵范石湖田园杂兴诗六十首 夏日十二首之八 其三十二","f":"七言绝句","c":["水亭傍午好追凉，白鸟飞来玉一双。","脩竹似嫌炎暑近，并移清影过南窗。"]},{"t":"次韵范石湖田园杂兴诗六十首 夏日十二首之九 其三十三","f":"七言绝句","c":["浊酒倾来白似浆，葛中新漉手犹香。","溪泉冷浸荷筒饮，共向槐阴纳晚凉。"]},{"t":"次韵范石湖田园杂兴诗六十首 夏日十二首之十 其三十四","f":"七言绝句","c":["角巾微服恣游嬉，偶值溪翁得缓归。","独有蜻蜓如对客，一双时掠钓丝飞。"]},{"t":"次韵范石湖田园杂兴诗六十首 夏日十二首之十一 其三十五","f":"七言绝句","c":["千亩荒烟傍晓锄，源头水少每忧枯。","何如老子书田好，纵使丰年不上租。"]},{"t":"次韵范石湖田园杂兴诗六十首 夏日十二首之十二 其三十六","f":"七言绝句","c":["人间三伏畏骄阳，我独观书爱日长。","为问此时何所乐，暑风凉簟竹方床。"]},{"t":"次韵范石湖田园杂兴诗六十首 秋日十二首之一 其三十七","f":"七言绝句","c":["东轩睡足日初红，起汲清泉灌菊丛。","不是幽人勤种植，要看佳卉傲秋风。"]},{"t":"次韵范石湖田园杂兴诗六十首 秋日十二首之二 其三十八","f":"七言绝句","c":["晚凉何处听秋声，脩竹千竿翠绕扃。","自起开窗看微月，风萤撩乱一池星。"]},{"t":"次韵范石湖田园杂兴诗六十首 秋日十二首之三 其三十九","f":"七言绝句","c":["巧夕争看织女机，彩云销尽不成衣。","如何村落柴门外，乌鹊都无一个飞。"]},{"t":"次韵范石湖田园杂兴诗六十首 秋日十二首之四 其四十","f":"七言绝句","c":["坐对疏林日渐低，闲看归鸟正高飞。","野夫自为吟诗苦，不是悲秋减带围。"]},{"t":"次韵范石湖田园杂兴诗六十首 秋日十二首之五 其四十一","f":"七言绝句","c":["行道真如行路难，归来依旧客毡寒。","灯前笑对家童说，恰似琴川作冷官。"]},{"t":"次韵范石湖田园杂兴诗六十首 秋日十二首之六 其四十二","f":"七言绝句","c":["雨后晴空碧四垂，斜阳却与乱山宜。","怪来举目浑无碍，正是秋风落叶时。"]},{"t":"次韵范石湖田园杂兴诗六十首 秋日十二首之七 其四十三","f":"七言绝句","c":["一棹夷犹任野夫，苕乡人号小西湖。","鸡头菱角随时有，桂子荷花此地无。"]},{"t":"次韵范石湖田园杂兴诗六十首 秋日十二首之八 其四十四","f":"七言绝句","c":["田家望望待升平，甲子欣逢烂熳晴。","茅舍竹篱还自好，此身不愿谒承明。"]},{"t":"次韵范石湖田园杂兴诗六十首 秋日十二首之九 其四十五","f":"七言绝句","c":["酿酒盈缸粟满仓，秪将辛苦度星霜。","诗书教子如何似，羡杀燕山窦十郎。"]},{"t":"次韵范石湖田园杂兴诗六十首 秋日十二首之十 其四十六","f":"七言绝句","c":["自笑迷方著处家，去年犹记客天涯。","今朝又是重阳节，鐏有新醪菊有花。"]},{"t":"次韵范石湖田园杂兴诗六十首 秋日十二首之十一 其四十七","f":"七言绝句","c":["琴川官舍漫多鱼，却忆松江巨口鲈。","偶见秋风动归兴，不知还是季鹰无。"]},{"t":"次韵范石湖田园杂兴诗六十首 秋日十二首之十二 其四十八","f":"七言绝句","c":["欲避兵尘不厌深，远携琴剑到梅林。","绿樽紫蟹聊消日，喜有床头未尽金。"]},{"t":"次韵范石湖田园杂兴诗六十首 冬日十二首之一 其四十九","f":"七言绝句","c":["新居添得屋茅高，梅柳栽成似蜀郊。","岁晚归来无一事，小窗闲看鹊营巢。"]},{"t":"次韵范石湖田园杂兴诗六十首 冬日十二首之二 其五十","f":"七言绝句","c":["年来读易太冬烘，赖有先贤为启蒙。","三十六宫都历遍，眼中物物是春风。"]},{"t":"次韵范石湖田园杂兴诗六十首 冬日十二首之三 其五十一","f":"七言绝句","c":["新筑书堂荫白茅，萧然终胜老禅寮。","雪天最爱风敲竹，似向瑶台听凤箫。"]},{"t":"次韵范石湖田园杂兴诗六十首 冬日十二首之四 其五十二","f":"七言绝句","c":["门外沙寒月半笼，柴荆元不置帘栊。","年来闲气都消尽，坐对书灯一点红。"]},{"t":"次韵范石湖田园杂兴诗六十首 冬日十二首之五 其五十三","f":"七言绝句","c":["归隐方谋一亩宫，论交溪友与园公。","春风会到门前柳，好插长条满屋东。"]},{"t":"次韵范石湖田园杂兴诗六十首 冬日十二首之六 其五十四","f":"七言绝句","c":["溪头冻合雪风晴，寒袭重裘一气凝。","谁把玻瓈都击碎，定知渔榜晚收冰。"]},{"t":"次韵范石湖田园杂兴诗六十首 冬日十二首之七 其五十五","f":"七言绝句","c":["紫芥九宜配白菘，响生牙颊味偏浓。","拟同坡老残年饱，肯教何曾一日供。"]},{"t":"次韵范石湖田园杂兴诗六十首 冬日十二首之八 其五十六","f":"七言绝句","c":["久客偏谙闾里情，每逢邻叟即班荆。","浊醪酿得邀人吃，为喜今秋万宝成。"]},{"t":"次韵范石湖田园杂兴诗六十首 冬日十二首之九 其五十七","f":"七言绝句","c":["晓起惊看雪拥门，地炉火煖自添春。","交游岁晚俱零落，谁复扁舟访故人。"]},{"t":"次韵范石湖田园杂兴诗六十首 冬日十二首之十 其五十八","f":"七言绝句","c":["不眠吟苦爱更长，石鼎煎茶满注汤。","诗句欲成缘底事，梅花隔屋暗吹香。"]},{"t":"次韵范石湖田园杂兴诗六十首 冬日十二首之十一 其五十九","f":"七言绝句","c":["苍朮频烧烟雾蒸，紫藤初爇蕙兰清。","岁除却忆升平夜，萧鼓喧喧满凤城。"]},{"t":"次韵范石湖田园杂兴诗六十首 冬日十二首之十二 其六十","f":"七言绝句","c":["人事匆匆岁月催，检残官历待春来。","已闻树里琴声变，更看天边斗柄回。"]},{"t":"兰亭卷","f":"七言绝句","c":["字体纷纷变若云，后人惟睹永和文。","昭陵一刻谁能学，尽道吴兴似右军。"]},{"t":"墨梅","f":"七言绝句","c":["客里俄惊岁又残，燕山十月雪花寒。","江南驿使无消息，却把春光纸上看。"]},{"t":"王太守马图","f":"七言绝句","c":["衮尘六马记唐宫，失却图中玉面骢。","好逐劝农贤太守，东郊明日踏春风。"]},{"t":"梅 其一","f":"七言绝句","c":["罗浮谁写梦中春，便觉芳香暗袭人。","不整缟衣风外舞，水边来倩为传神。"]},{"t":"梅 其二","f":"七言绝句","c":["蛾眉淡扫玉纤纤，碧海春浓酒正酣。","青羽无端啼月溶，令人日夜忆江南。"]},{"t":"虎溪三笑","f":"七言绝句","c":["典午乾坤迹已陈，东林聊复避风尘。","虎溪偶过何须笑，似笑清谈解误人。"]},{"t":"橐驼图","f":"七言绝句","c":["内山高并两峰寒，万里毡裘雪未乾。","今日江南人见惯，不须常展画图看。"]},{"t":"霜月梅","f":"七言绝句","c":["北枝消得铁心肝，却恐南枝不耐寒。","好倩东风与吹散，只留疏影月中看。"]},{"t":"边伯京为瑞应宫吴提点作枯木竹石图吴之甥郑敬常得之俾题其左","f":"七言绝句","c":["瑞应宫前竹木苍，边鸾曾写赠吴刚。","一拳怪石疑琼玉，空使诗人忆渭阳。"]},{"t":"二马图","f":"七言绝句","c":["形体支离两可怜，胸中历历旧山川。","当时伯乐曾回顾，肯信人间有暮年。"]},{"t":"芍药图","f":"七言绝句","c":["十载杨州锦怅遮，红红白白斗繁华。","人生总被春瞒却，元是山中药草花。"]},{"t":"孟得名画雪景寒鸦","f":"七言绝句","c":["飞散寒鸦不可招，数株封雪落长条。","茅檐尽日无人到，何处高楼酒未消。"]},{"t":"次韵周公辅游东阳东岘因其所述之实而赋之 其一","f":"七言绝句","c":["置守当年为罢侯，剖符皆是帝王州。","一瓢挂在长松下，方信箕山有许由。"]},{"t":"次韵周公辅游东阳东岘因其所述之实而赋之 其二","f":"七言绝句","c":["旧说东阳山水郡，邑中济济盛宾僚。","能令百里无愁叹，未足涓埃答圣朝。"]},{"t":"题白云孙画 其一","f":"七言绝句","c":["风雨虚空不可凭，如何上下恣飞腾。","神仙变化谁能识，笑杀终南谭景升。"]},{"t":"集古句题苏小小像","f":"七言绝句","c":["柳色深藏苏小家，昔年相望尚天涯。","不知谁唱归春曲，才见开花又落花。"]},{"t":"刘耀卿画 其一","f":"七言绝句","c":["重叠春山罨画开，柳边花底抱琴回。","谁家庭院东风里，一片笙歌隔水来。"]},{"t":"刘耀卿画 其二","f":"七言绝句","c":["画桥南畔藕花香，坦腹湖亭爱午凉。","醉拍阑干因得句，不知惊去睡鸳鸯。"]},{"t":"刘耀卿画 其三","f":"七言绝句","c":["老桂吹香袭绛袍，并将秋兴写秋毫。","何人记得南楼夜，月过松梢一丈高。"]},{"t":"刘耀卿画 其四","f":"七言绝句","c":["曾倚江亭看雁飞，梅花和雪亚荆扉。","客帆自向沙头落，不是山阴兴尽归。"]},{"t":"画 其一 子陵","f":"七言绝句","c":["世祖中兴忆故人，风云不应应星辰。","一丝九鼎关轻重，未必丹青写得真。"]},{"t":"画 其二 巢父许由","f":"七言绝句","c":["清谈又复到巢由，洗耳元非况饮牛。","尧舜得人天下事，画师那识帝心忧。"]},{"t":"画 其三 仁知山水","f":"七言绝句","c":["仁知微分动静间，不师端木即师颜。","图中隐者无名姓，乐水何妨更乐山。"]},{"t":"画 其四 渔樵闲话","f":"七言绝句","c":["渔罢樵林岂惮劳，溪头闲话偶相遭。","会稽太守诚何事，不及严陵隐最高。"]},{"t":"四时花鸟图 其一 梨花白颊","f":"七言绝句","c":["溶溶院落月三更，此影如何画得成。","一树梨花双白颊，诗人闲户作清明。"]},{"t":"四时花鸟图 其二 榴花绣眼","f":"七言绝句","c":["满院薰风清画迟，海榴开到过墙枝。","美人窗下闲针线，却爱花间绣眼儿。"]},{"t":"四时花鸟图 其三 桂花佳雀","f":"七言绝句","c":["天香一夕满人间，佳雀飞来意自闲。","纵使枝头风露冷，也应不是纥千山。"]},{"t":"四时花鸟图 其四 梅花鲍老","f":"七言绝句","c":["红梅竹里报春光，双鸟依依恋夕阳。","自有天生好毛羽，当筵舞袖错教长。"]},{"t":"谒仇山村墓迢和张仲举诗韵","f":"七言绝句","c":["敬吊先生落照中，纸烟销尽酒樽空。","牛羊上垄无人管，岂为当时面发红。"]},{"t":"鉴湖八景为周履常赋 其一 柳庄","f":"五言律诗","c":["绕庄都是柳，远近翠相连。","种树思前度，飞花记此年。","闭门时系马，攲枕忽闻蝉。","自得陶潜趣，清风为飒然。"]},{"t":"鉴湖八景为周履常赋 其二 桂林","f":"五言律诗","c":["分得岩前种，年深自作林。","因思大廷对，何似小山吟。","浸叶为沉水，收花当屑金。","中秋还有约，载酒过山阴。"]},{"t":"鉴湖八景为周履常赋 其三 兰渚","f":"五言律诗","c":["爱此芳洲小，渔家许卜邻。","如何挑菜处，亦有艺兰人。","杂佩谁相问，孤琴尔独亲。","山阴亭子近，修褉及馀春。"]},{"t":"鉴湖八景为周履常赋 其四 瓜田","f":"五言律诗","c":["瓜种阳坡下，纷披半顷田。","杞包原有象，枣比或逄仙。","白兔官徒援，青门地自偏。","冰盆曾荐处，六月鉴湖船。"]},{"t":"鉴湖八景为周履常赋 其五 芙蓉港","f":"五言律诗","c":["芙蓉开港二，一路入红云。","露湿光犹泫，波明影自分。","仙人四酒棹，游女妒罗裙。","若共荷花拨，秋风岂属君。"]},{"t":"鉴湖八景为周履常赋 其六 筼筜坡","f":"五言律诗","c":["旧说筼筜谷，如今别有坡。","为怜清节好，不厌绿阴多。","暖逼冬生笋，凉深夏近荷。","中郎如到此，应更择良柯。"]},{"t":"鉴湖八景为周履常赋 其七 按鹤亭","f":"五言律诗","c":["本是青云物，依亭也是幽。","鼓琴思魏野，相鹤记浮丘。","三叠俄成舞，千龄或可留。","永怀曾听处，私月故山秋。"]},{"t":"鉴湖八景为周履常赋 其八 放鱼池","f":"五言律诗","c":["陶朱元有法，岛峙在陂塘。","春雨翻萍藻，丰年梦稻粱。","奋时须一跃，乐处永相忘。","不是池中物，风雷起浩茫。"]},{"t":"刘松年诗意图","f":"五言律诗","c":["野水连村绿，云山隔岸青。","桥低疑碍艇，树密不遮亭。","奇字无人问，清琴只自听。","百年栖宿意，把卷忆曾经。"]},{"t":"舒啸轩为陈经仲赋","f":"五言律诗","c":["何处堪舒啸，轩楹眺望间。","清风生爽籍，皓月动空山。","欲宄声音妙，都缘意趣闲。","东皋伊迩地，每到即忘还。"]},{"t":"赠写真吴天碧","f":"五言律诗","c":["名士号天碧，传家由道玄。","常于多暇日，每纵写凌烟。","妙笔知吾子，峨冠识进贤。","何如风雪里，著我耸吟肩。"]},{"t":"送黄允迪","f":"五言律诗","c":["青门黄氏子，雅量出奇姿。","濯濯三春柳，汪汪万顷陂。","霜啼惊电掣，云翼讶天垂。","况有麟经学，何姑独抱遗。"]},{"t":"挽孔徵夫","f":"五言律诗","c":["滔滔洙泗水，一脉到西湖。","山木符先梦，乾坤失钜儒。","空遗重席坐，无复过庭趋。","回首东山墓，何时一致刍。"]},{"t":"送章环","f":"五言律诗","c":["昔捧宾兴诏，归途过富春。","慇勤寻故友，邂逅识斯人。","黄卷方游自，青云已致身。","世家传象笏，郇国本王臣。"]},{"t":"怡云轩为魏良赋","f":"五言律诗","c":["爱汝怡云处，同看却异情。","应知陶弘景，不是狄怀英。","气逐龙身远，光摇鹤发明。","名扬亲显日，霖雨在苍生。"]},{"t":"鸣鹤轩为徐文质赋","f":"五言律诗","c":["双唳轩前鹤，松梢更作群。","在阴其子和，随处有人闻。","夜警多因露，皋鸣每切云。","从兹縻好爵，细玩易中文。"]},{"t":"论诗次张行中韵","f":"五言律诗","c":["开门方觅句，折简复论诗。","每到真成趣，由来不费辞。","艰深文浅近，臭腐化神奇。","得失真悬绝，须劳一转移。"]},{"t":"双松轩为沈廉赋","f":"五言律诗","c":["双松何岁植，秀色满庭隅。","拔地疑千尺，参天见两株。","蓝田重作记，栗里有成图。","门对双溪水，扁舟或可呼。"]},{"t":"悼三叔明室张氏","f":"五言律诗","c":["结发为夫妇，齐眉若主宾。","山同黄鹤隐，书逼彩鸾真。","兰树人皆羡，蘋蘩尔独亲。","情伤坦臒者，临穴重沾巾。"]},{"t":"柯敬仲枯木竹石","f":"五言律诗","c":["欲问奎章石，无言似照头。","竹昏虞庙晚，木落洞庭秋。","楚客心偏苦，湘娥黛正愁。","百年成俛仰，题画忆丹丘。"]},{"t":"雪景卷","f":"五言律诗","c":["山雪大如许，能令老树低。","仙翁双屐没，童子一琴携。","院画留冬景，臣名识夏圭。","免园宾客散，把卷重悽悽。"]},{"t":"送沈钦叔屯种苜蓿","f":"五言律诗","c":["苜蓿能肥马，曾闻汉苑誇。","送迟讥艾子，见远感榴花。","既有躬耕地，宁辞著处家。","圣朝多雨露，不久在天涯。"]},{"t":"题梅用张蜕庵寄杨村居韵","f":"五言律诗","c":["阳春微露痕，都在老梅根。","冰雪好同洁，杏桃空自繁。","吟诗扶短杖，移席了残樽。","旧住南山下，花时不出村。"]},{"t":"送罗宗敬","f":"五言律诗","c":["之子观光日，江山入望深。","春秋三传学，忠孝百年心。","群马闻空冀，孤罴见出林。","西风黄菊酒，留别重登临。"]},{"t":"挽卢处士","f":"五言律诗","c":["吴山卢处士，潇洒地行仙。","云卧怜丹壑，茶歌慕玉川。","盖棺方事定，刻石又名传。","清逸重题号，明经有子贤。"]},{"t":"宋授之春山隐居图","f":"五言律诗","c":["楼倚东风外，凭高取次吟。","柳低黄鸟近，日抚翠屏深。","世换如收局，人亡不在琴。","凄凉图画里，愁绝百年心。"]},{"t":"赠医僧朗碧天为高子威指挥赋","f":"五言律诗","c":["师号胡为朗，碧天无点埃。","宁知药草品，能济栋梁材。","大道传龙树，芳名达凤台。","从兹开寿域，雨露日边来。"]},{"t":"槐阴书舍为四明王德修赋","f":"五言律诗","c":["问讯城东地，三槐德又新。","谁知种树者，自是读书人。","阴满晋公舍，芳连孟氏邻。","象山游学处，相对碧嶙峋。"]},{"t":"庚申岁八月十三日陪祭山川因怀诸友","f":"五言律诗","c":["山川陪祭祀，引望见江云。","月到今宵好，秋从此日分。","声驰黄鸟咏，梦绕白鸥群。","谩忆岩头桂，无由折赠君。"]},{"t":"是夜宿三一庵次俞文辅题韵","f":"五言律诗","c":["庵在色山下，依坛路稍平。","主人多道气，留客见真情。","天籁秋号水，星河夜入城。","江心有明月，待得海潮生。"]},{"t":"悼吾子行道士","f":"五言律诗","c":["布衣吾道士，举世莫能偕。","遽作骑鲸客，空遗梦蝶斋。","阳冰书瘦硬，方朔语诙谐。","墓碣铭贞白，临文每怆怀。"]},{"t":"次俞子中病起韵","f":"五言律诗","c":["桐江清隐客，头白太平时。","每唱紫芝曲，闲临碧落碑。","无愁何用解，示病不须医。","恐有登高兴，先期报我知。"]},{"t":"拟赋野无遗贤","f":"七言律诗","c":["束帛丘园起隐沦，翩翩明诏不辞频。","风云自合从龙虎，郊薮那能隐凤麟。","五百馀年逢圣主，普天之下尽王臣。","陈谟幸际唐虞世，膏泽应知及兆民。"]},{"t":"西湖怀古次杨彦振韵","f":"七言律诗","c":["登临长使客魂消，剩水残山阅市朝。","柳色也知随处好，莺声不似旧时娇。","云和冷落闲来袖，风景苍茫失画桥。","回首故宫荒草合，欲寻前事竟寥寥。"]},{"t":"南山飞流亭","f":"七言律诗","c":["山溜泠泠来不竭，激成飞瀑散空明。","虹霓下饮秋无际，河漠西流夜有声。","横剑谁思仙子过，作亭人羡老僧清。","平生惯诵天台赋，不记香炉记赤城。"]},{"t":"寄王彦强府倅 其一","f":"七言律诗","c":["西蜀人材天下奇，使君来此济时危。","云龙风虎王褒颂，官柳江梅杜甫诗。","苍海只疑瞻锦水，越山浑似见峨眉。","不才谬作兰亭客，又到君家洗砚池。"]},{"t":"寄王彦强府倅 其二","f":"七言律诗","c":["野水平桥直到门，幽居绝胜浣花村。","半帘草色留宾客，满院书声教子孙。","庭下甘棠阴渐密，道傍苦李寔应繁。","自公退食多清事，剩有诗书共讨论。"]},{"t":"寄王彦强府倅 其三","f":"七言律诗","c":["日日呼奴采涧芹，柁楼晚饭愧慇勤。","草堂不用忧春雨，尘甑应劳念史云。","关塞巳通流马道，江湖空羡白鸥群。","来禽青李犹堪寄，为向山阴报右军。"]},{"t":"送清溪濂上人归金华","f":"七言律诗","c":["六年西崦闭禅扉，夜梦东阳隔翠微。","溪柳野桃频入咏，清风明月又思归。","案头贝叶如云积，座上天花学雨飞。","闻道春陵周子裔，墨名终不愧儒衣。"]},{"t":"碧梧生诗为马伯庸赋","f":"七言律诗","c":["丞相当年号碧梧，生因同姓转相呼。","玉岗春霁鸣威凤，金井秋阴集好乌。","琴荐虞廷应有待，圭封唐叔岂相诬。","人材特立真如此，高拂青冥见一株。"]},{"t":"樵云","f":"七言律诗","c":["伐木丁丁山径通，林深长觉昼冥濛。","栋梁自挟扶舆气，斤斧全收造化功。","莘野谩耕十亩雨，渭川空钓一丝风。","谁知作楫为林者，只在商岩版筑中。"]},{"t":"蓼蒐庵诗为王必先太守赋","f":"七言律诗","c":["王氏坟庵颇易寻，旧栽松柏巳成林。","蓼莪每动双亲念，春草难忘一寸心。","峰远蟠桃红日薄，波澄彭蠡白云深。","题诗不尽劬劳意，聊为君侯写德音。"]},{"t":"栖鹤斋诗为丁虚一赋","f":"七言律诗","c":["仙禽变化出胚胎，栖室琳宫丈室开。","七日缑山期一见，千年华表记重来。","身轻白雪闲依竹，顶重丹砂误啄苔。","龙虎真人新著号，会乘骐骥到迁莱。"]},{"t":"詹尚书同文以堵文明所作云树图寄徐大参复初仍寄以诗因次其韵","f":"七言律诗","c":["长句和平见治音，京华犹记盍朋簪。","声传珠履星辰近，影动金莲雨露深。","云树有图凭鹰寄，春山无伴听莺吟。","悬知两地看明月，爱国忧民共此心。"]},{"t":"次徐总制浙江亭剩柳诗韵","f":"七言律诗","c":["论射江亭当午日，沙头雨过少轻尘。","七重札透威无敌，两石弓开臂有神。","地插绿杨云叶小，腰悬白羽雪花新。","他时会见天山定，肯让凌烟第一人。"]},{"t":"次无溢满上人纪梦诗韵","f":"七言律诗","c":["上人梦赴天王供，兰若依稀似五台。","地布黄金龙象出，笙吹白玉凤鸾来。","贝多叶古人能诵，优钵花繁孰与栽。","出定了知身是幻，袈裟从此不须裁。"]},{"t":"送项履初归慈溪","f":"七言律诗","c":["秋风捧檄娱亲日，一叶飘然渡大江。","堂上正须衣五彩，沙头那得玉瓶双。","同游葛岭风吹帽，独宿钱清月在窗。","想共东邻钱处士，到家搜句对银缸。"]},{"t":"挽谨严先生方直卿","f":"七言律诗","c":["赋罢归田返故庐，神游乐国类华胥。","遗经绝笔无司马，学礼趋庭有伯鱼。","春树暮云空忆汝，屋梁落月倍愁予。","谨严斋冷留图像，尘掩前朝荐鹗书。"]},{"t":"草心轩为林子山赋","f":"七言律诗","c":["北堂深处别开轩，为奉慈亲背树萱。","一脉有情通雨露，百年无力报乾坤。","芰荷衣敞怜缝线，菽水供微愧倚门。","欲问春晖何所在，渭阳犹是旧王孙。"]},{"t":"壬子秋帘次迮士霖韵","f":"七言律诗","c":["雨馀公馆夜沉沉，香爇金炉觉坐深。","群马昔年空冀北，孤罴今日见丛林。","贺公自是工吴语，庄写何须动越吟。","官烛风帘同试事，正宜把酒细论心。"]},{"t":"赠道士毛启宗","f":"七言律诗","c":["上士高居有好客，每因斋戒阐玄宗。","青天尽处来孤鹤，黄道中间卜六龙。","说法宝珠悬黍米，步虚仙履蹑芙蓉。","有时对客谈中诫，应有人疑是赤松。"]},{"t":"秋闱对月次桂彦良韵","f":"七言律诗","c":["露下松阴鹤梦醒，古香吹桂满空庭。","云端半壁悬孤月，天上连珠灿五星。","诗思每因秋兴发，江声浑作夜潮听。","求贤正为明时用，荐士须当效古灵。"]},{"t":"爱日轩为金华许景和赋","f":"七言律诗","c":["春晖欲报意无穷，大母高年母氏同。","表述陈情犹李密，轩名爱日似杨雄。","五纹添线空怜影，三舍挥戈谩纪功。","何似北堂称寿酒，忘忧花照彩衣红。"]},{"t":"洪武壬子夏六月望日赍诏新城事竣县令徐安卿邀饮池上出诗见示因次其韵时故友袁彦善为本县训导故及之","f":"七言律诗","c":["山雨留樽记此来，临池儗泛碧筒杯。","邑中故友能相间，阶下宜男方半开。","胜日偶陪珍日醉，轻风又送彩舟回。","圣王宵旰忧民瘼，会见新萌发旧荄。"]},{"t":"追挽节孝周先生","f":"七言律诗","c":["偶题节孝先生传，甚似罗城徐仲车。","陇上白杨空复见，庭前翠草不曾除。","何多名士能为咏，为有佳儿好读书。","西崦久违应怅望，晴云犹护旧时居。"]},{"t":"送道士杨秋月赴京","f":"七言律诗","c":["南送和王五世孙，便从总角悟玄门。","灵台皎洁澄秋月，虚室光芒炫晓暾。","儗服刀圭生羽翼，旦书符篆役精魂。","聪明忠孝神仙事，好赴蓬莱觐至尊。"]},{"t":"题如山安上人诗卷","f":"七言律诗","c":["何年竺国远分支，认淂来龙始出奇。","要使岱宗超㟝嵝，还将芥子纳须弥。","疾风甚雨应难动，绝壁悬崖岂易知。","一任石头行路滑，随身竿木解扶持。"]},{"t":"催雪次钱善长韵","f":"七言律诗","c":["岁暮时昏雪未垂，膝神何事苦愆期。","六花自信霄中有，三白要教天下知。","古道停鞭思入画，寒窗呵笔拟题诗。","几家羔酒销金怅，频揭珠帘怅望时。"]},{"t":"送徐文年归严陵","f":"七言律诗","c":["高士声名正蔼如，去年承诏赴公车。","玉堂久待欧公学，金匮深藏太史书。","华服归来惊野鸟，竹竿留得钓江鱼。","风帆好借春涛便，重访桐君旧隐庐。"]},{"t":"挽段礼庭","f":"七言律诗","c":["庐陵山林龙溪雄，趋庭问礼惟此翁。","逸士非如段太尉，阡表甚似欧阳公。","年来洞究无极妙，夜半忽感抟桑红。","佳儿求铭勒页石，欲以潜德垂无穷。"]},{"t":"送刘本中归海昌","f":"七言律诗","c":["泮宫乐育万菁莪，折柳西湖奈别何。","鹦鹉莫题当日赋，骊驹须唱旧时歌。","新居近海鱼虾贱，旧学闻诗草木多。","绿发交游今白发，河梁携手重吟哦。"]},{"t":"杏轩为倪伯温赋","f":"七言律诗","c":["倪氏锄经自有堂，还于花下结丹房。","夕阳坛上非前事，春雨江南是故乡。","况是仙人如董奉，何须女子识韩康。","重来轩外绿阴合，煮酒银瓶得共尝。"]},{"t":"吴山伟观","f":"七言律诗","c":["谯楼佳丽倚高寒，城郭浑疑画里看。","旧说青山如五马，新题华表似飞鸾。","东西淮海三千里，左右江湖十二阑。","区宇清宁民物乐，卧闻鼓角报平安。"]},{"t":"溪山隐居图为吴以道题","f":"七言律诗","c":["松下茅斋清昼寒，乘闲来此得盘桓。","雨深南涧乘纶钓，云出西山拄笏看。","黄鸟引雏过院落，白鸥忘我近阑干。","桃花流水非人世，傍晚移舟过浅滩。"]},{"t":"东郊劝农为王侯必先赋","f":"七言律诗","c":["灵雨初零动土膏，东郊五马出游遨。","老农欲遂三秋望，贤守宁辞一日劳。","牛角无歌何用扣，豚蹄有酒正颜操。","题诗记得豳风句，祭韭开冰复献羔。"]},{"t":"董士勉架阁所藏霅溪翁观梅诗意图","f":"七言律诗","c":["欲写寒梅愧未工，丹青赖有霅溪翁。","要观清浅黄昏处，尽有经营惨澹中。","一鹤一琴犹旧日，集丘集水自春风。","郎官画省多才思，东阁吟诗兴颇同。"]},{"t":"送李克进经历护二亲丧归葬维杨克进蓟州李息斋之孙工画竹寓居维杨先为平阳府经历二亲俱殁于闽至洪武壬子冬始得归葬徐大参命作诗以赠其行","f":"七言律诗","c":["清时人物自风流，写竹真如老蓟丘。","绿水芙蓉思晋地，琼花芍药记杨州。","两昏云暗双亲恨，岁晚江空独客愁。","赖有故人知己者，会须能赠麦盈舟。"]},{"t":"钱塘十咏 其一 东海朝暾","f":"七言律诗","c":["照槛扶桑望转遥，海霞蒸赤丽璇霄。","梧冈影动鸣孤凤，蓬岛光浮抃六鳌。","山迥尚留将坠月，江明正带欲归潮。","寅宾自是羲和事，秪有葵心仰帝尧。"]},{"t":"钱塘十咏 其二 西湖夜月","f":"七言律诗","c":["南北峰前里外湖，秋清偏爱月轮孤。","神鱼听乐有时出，倦鸟安巢不夜呼。","十里水云涵玉鉴，万家民物在冰壶。","涌金门外曾行处，人道贤侯似大苏。"]},{"t":"钱塘十咏 其三 浙江秋涛","f":"七言律诗","c":["八月观涛独虎林，朱轓皂盖浙江浔。","偶因威武三军勇，还感朝宗万古心。","沧海神龙从变化，长空孤鸟付消沉。","美潮有禁关仁政，民说若谟直到今。"]},{"t":"钱塘十咏 其四 北关夜市","f":"七言律诗","c":["罗绮明春数里馀，郊关迤理接民居。","须知北郭夜为市，不似南州人趁虚。","景类元宵堪入画，家殊周易岂同书。","使君五马归来晚，夹道纱笼照隼旟。"]},{"t":"钱塘十咏 其五 孤山霁雪","f":"七言律诗","c":["快雪时晴春尚悭，梅花开遍旧孤山。","入林僧舍浑迷路，隔岸人家尽掩关。","茶鼎旋烹新水活，钓舟空伴白鸥闲。","因思李及曾来日，童子开笼鹤未还。"]},{"t":"钱塘十咏 其六 两峰白云","f":"七言律诗","c":["南山雪接北山松，云气何曾离两峰。","无色飞扬常类鹤，有时变化忽从龙。","乐天偶向诗中道，弘景还于岭上逢。","忽忆鄱阳亲舍远，凭高望极几千重。"]},{"t":"钱塘十咏 其七 九里云松","f":"七言律诗","c":["九里闲云万个松，经行记得旧时踪。","黄金曾饰宋儒士，苍狗岂知秦代封。","风露横陈鸣鹳鹤，波涛澎湃起蛟龙。","我来朗诵庐山句，清气飘飘欲荡胸。"]},{"t":"钱塘十咏 其八 六桥烟柳","f":"七言律诗","c":["疏柳长烟远自迷，六桥南北带沙堤。","乱分雌霓连蜷挂，深蔽娇莺自在啼。","红出天桃销处薄，翠和芳草望中低。","赤阑于外清阴满，曾见苏公过马蹄。"]},{"t":"钱塘十咏 其九 灵石樵歌","f":"七言律诗","c":["伐木丁丁澜谷春，行歌落日见樵人。","青山重叠自今古，黄鸟嘤鸣如主宾。","清响有时谐雅调，语言随意出天真。","画船檀板西湖曲，何似林泉乐在民。"]},{"t":"钱塘十咏 其十 冷泉猿啸","f":"七言律诗","c":["飞来峰高多白云，垑猿啼处夜将分。","三声忽向岭头度，一个真如峡口闻。","哀杂涧泉遥历历，清和萝月乱纷纷。","亭中白传曾留记，明日重来看刻文。"]},{"t":"小桃源为未质夫赋","f":"七言律诗","c":["桃源欲觅恐荒唐，此境依稀在海昌。","避世尝闻隐君子，问津何必待渔郎。","绛霞蒸处层层远，红雨飞时点点香。","欲效陶潜重作记，东风回首意微茫。"]},{"t":"挽王母散人沈氏","f":"七言律诗","c":["萱草香销泪湿衣，白头人去思依依。","春风堂上闲初服，夜雨窗前冷断机。","蝴蝶已知俱是梦，杜鹃犹道不如归。","翩翩丹旐西湖路，回首南山尽翠微。"]},{"t":"福源精舍为魏仲远赋","f":"七言律诗","c":["福源精舍年何有，学士亲书湖上坟。","卜地依稀封马鬣，种松次第变龙纹。","魏公笏在多遗泽，忧盖山高尽白云。","前代名人留制作，子孙从此蔼清芬。"]},{"t":"喜晴次刘可与经历韵","f":"七言律诗","c":["兼旬淫雨连吴楚，今日晴光满树头。","淮白鱼来人不网，冬青花落客凭楼。","借车踏水青秧出，拄笏看山绿树稠。","民不怨咨缘底事，使君五马出来游。"]},{"t":"次杨仲弘宗阳宫对月韵","f":"七言律诗","c":["古月只同今月看，月华更好岁华更。","露凝仙掌横秋气，云度天河学水声。","金母自来青鸟使，玉童对按紫鸾笙。","箫台占断蓬壶景，何必重寻海上瀛。"]},{"t":"题叶伯政经历水北山居图","f":"七言律诗","c":["水北山人类石洪，故居宛在画图中。","纵如雁荡留吟屐，何似鸥波看钓蓬。","出处要知天下重，声名当与古人同。","草堂归隐须他日，猿鹤休疑蕙怅空。"]},{"t":"宝州为庄上人赋","f":"七言律诗","c":["大宝州中无不有，难分高下与洪纤。","海名香水随心见，珠号摩尼信手拈。","莫道山河如幻化，须知世界要庄严。","上人燕坐悠然处，俗士如何不具瞻。"]},{"t":"白云为英上人赋","f":"七言律诗","c":["白云之白何英英，孝子洁白同其情。","种私每慕卢六祖，起石不羡黄初平。","老龙听法雨随至，苍狗变熊天同行。","平公弟子似公少，不枉违叟知能名。"]},{"t":"陈叔起松石图为峨嵋山人张原题","f":"七言律诗","c":["谁将青李来禽帖，写作苍松怪石图。","大厦他年要梁栋，长竿此日拂珊瑚。","辞存飞白看来好，直计兼金买得无。","何处曾经照颜色，峨嵋山馆月轮孤。"]},{"t":"白云堆为朗元白上人赋","f":"七言律诗","c":["要使闲身到处闲，白云堆里著禅关。","龙归不觉袈裟湿，犬吠方知杖锡还。","有用一时苏大旱，无心终日在空山。","万松岭上何人屋，秪许平分住半间。"]},{"t":"云门草堂为徐彦钟赋","f":"七言律诗","c":["云门寺近若耶溪，溪上人家云半迷。","秋雨正愁茅屋破，春星还傍草堂低。","白鸦谷远松筠老，碧藻坊深海柳齐。","何似南州徐孺子，故居新璧待重题。"]},{"t":"素华内景为毛启宗赋","f":"七言律诗","c":["内景元从太素分，空花无际住缤纷。","室生虚白光疑月，肤达中黄气若云。","玉局降神从地见，宝珠遗响自天闻。","碧桃木老春常在，方外谁能识隐君。"]},{"t":"镜湖渔隐","f":"七言律诗","c":["家住镜湖流水东，门前日日藕花风。","酒船不用寻狂客，渔钓犹能学放翁。","九鼎一丝轩冕外，千岩万壑画图中。","沧浪歌罢无人听，惆怅归来月满空。"]},{"t":"江山图为傅德让赋","f":"七言律诗","c":["江上愁心曾有赋，烟江叠嶂偶成图。","丹青自可追小李，翰墨谁能继大苸。","野店山桥吟杖短，桃花流水钓舟孤。","人生适志真名语，命驾归来不为鲈。"]},{"t":"挽沙子中进士","f":"七言律诗","c":["吴山台榭锁烟霞，知是前朝进士家。","翠竹碧梧今代见，灵椿丹桂昔人誇。","功名梦断邯郸枕，乡国心随博望槎。","欲觅衣冠迷处所，寒云满日重兴嗟。"]},{"t":"挽沈子龄","f":"七言律诗","c":["胸襟洒落世称贤，握手论心二十年。","忍向青山葬黄土，愁看丹旐破苍烟。","眼中无复金钱会，身后空遗宝剑篇。","一束生刍一杯酒，临风三酹重悽然。"]},{"t":"题克俊主事蓟丘山传","f":"七言律诗","c":["生号蓟丘今有传，为因先世重怀思。","白云瞻怅空千里，铜狄摩挲又一时。","盘谷隐居知李愿，辋川图画见王维。","他年昼锦归来日，准拟登堂诵此诗。"]},{"t":"商与渊水竹居","f":"七言律诗","c":["不待高秋爽气新，幽居水竹自相亲。","已从淇澳思君子，更向湘江望美人。","小艇依林缘载鹤，大竿当槛为牵鳞。","商家霖雨须贤佐，汗简书名是隐沦。"]},{"t":"拟赋老子灯","f":"七言律诗","c":["孤竹形容立彩裳，赤乌流处便鹰扬。","东皇藜火传天禄，南极芒寒应寿昌。","空洞已知心事白，虚名犹觉鬓毛苍。","谁怜两目眵昏客，射策曾观上国光。"]},{"t":"抚松图","f":"七言律诗","c":["三径归来乐此生，涉园成趣似渊明。","门前五柳初摇落，庭外孤松渐长成。","正好盘桓当美景，何妨赋咏到闲情。","华轩又见开华扁，为有邻翁识姓名。"]},{"t":"元夕次陈尹子善韵 其一","f":"七言律诗","c":["严城五夜启重关，灯火交光似大山。","秾李谩誇游妓辈，传柑遥忆侍臣班。","西楼凉月归来晚，南陌和风笑语间。","可是吴儿贪乐事，踏歌到晓不知还。"]},{"t":"元夕次陈尹子善韵 其二","f":"七言律诗","c":["月色分明胜昨宵，游人街上踏琼瑶。","马头尘土从飞仆，鳌背星辰欲动摇。","梅弄粉香风不定，柳添黄色雪才消。","太平有象黎民乐，一曲笙歌倚洞箫。"]},{"t":"元夕次陈尹子善韵 其三","f":"七言律诗","c":["神仙宫府画图开，端使诗人咏有莱。","灯火直从天半落，绮罗都向月中来。","已闻献策瞻龙衮，又见吹笙下凤台。","莫遁草茅无补报，也曾终夕望三台。"]},{"t":"望云图","f":"七言律诗","c":["长空望极转销沉，独立苍茫辨远岑。","爱日每关为子意，看云长动忆亲心。","自怜五色衣将弊，谁记三山路更深。","莫遁大行成往事，诗传陟岵有遗音。"]},{"t":"方叔几午峰书舍诗卷","f":"七言律诗","c":["白云孙子笔砚灵，明德与汝称惟馨。","午峰门对结精舍，三传阁束穷遗经。","时来华裾识葱翠，夜半梨杖吹烟青。","慈亲和胆助勤苦，伫听唱名当大廷。"]},{"t":"分题得钟山送沈明德","f":"七言律诗","c":["钟山正对石头城，进士元非隐士名。","好看龙蟠并虎踞，争教鹤怨与猿惊。","三春游兴云同远，千里归心月共明。","去去会登群玉府，致身何必羡蓬瀛。"]},{"t":"分题得秦淮送杜士能","f":"七言律诗","c":["春波城下自涟漪，一舸夷犹任所之。","月过女墙潮落后，烟笼寒水夜分时。","双双堂燕衔沉见，白白淮鱼入馔知。","期子有才如杜牧，此行莫惜重题诗。"]},{"t":"送钱塘邑丞宋章甫","f":"七言律诗","c":["治世人才气自豪，起身应不愧萧曹。","春秋有学经曾试，铁石为心赋最高。","百里岂能栖凤棘，三年聊复试牛刀。","送君又到销魂处，南浦新波映去袍。"]},{"t":"大方圆上人有亭扁客航在越上远林先生索赋","f":"七言律诗","c":["老禅杯渡恐鸥惊，聊结虚亭喻物情。","春水祗疑天上坐，晚风还想月中行。","此身江海长为客，彼岸舟航浪得名。","夜半壑中谁负去，欲将此语问庄生。"]},{"t":"题郝德新又新字说卷后","f":"七言律诗","c":["一篇虺诰炳丹青，九字汤铭灿日星。","不是菜朱曾有语，安能子墨重书铭。","乾坤纳纳应无外，江汉滔滔岂暂停。","绝爱郝隆书满腹，命名称字必尊经。"]},{"t":"瑞竹杖诗","f":"七言律诗","c":["朝晖轩与竹为邻，煮笋时时得奉亲。","因见同根分二干，欲将寸草报三春。","夷齐比节无馀子，权绰连枝有后人。","扶老凭兹足流憩，莫疑五柳是前身。"]},{"t":"东圆分题七叶坡为王景周赋","f":"七言律诗","c":["森森佳木映阳坡，不比槐阴十讼多。","谁见一花如菡萏，人传七叶是娑罗。","漠貂谩藉金张业，月兔空涵海水波。","昨夜虚堂闻子落，定知仙客费吟哦。"]},{"t":"柳氏双婺卷","f":"七言律诗","c":["姑妇孀居守寂寥，闭门风雨任飘摇。","柳因秋早惊先落，松到岁寒知后凋。","一寸丹心同耿耿，百年华发共萧萧。","由来节义关名教，看取曹娥庙下潮。"]},{"t":"种菊庵为无锡钱子义赋","f":"七言律诗","c":["绕庵种菊待秋先，不道春苗已厌尝。","酒效少陵拈重碧，花怜惟演进姚黄。","满城风雨重阳意，三径荒芜几处香。","况有惠山泉可试，拟同桑苧对幽芳。"]},{"t":"九月六日病起偶成","f":"七言律诗","c":["卧病经时莫叹嗟，起来犹可岸乌纱。","药囊屡检看题遍，书帖重临作字斜。","秪觉风光吹白发，不知秋意满黄花。","自怜江海垂纶手，却倚衡门数暮鸦。"]},{"t":"送诏使还京","f":"七言律诗","c":["南闽西浙路犹赊，顷刻思光遍海涯。","五夜星辰呈贯索，九天雨露逐皇华。","归期已过清明节，行色将迎紫禁花。","风虎云龙当此日，颂成须献帝王家。"]},{"t":"送杨宗元分教海宁","f":"七言律诗","c":["闭户读书谁与邻，翻然分席海之滨。","太玄准易知先世，清白传家见后人。","蝌蚪文漫思复古，蝤蛑市近喜尝新。","独怜载酒河桥别，抍得梅花是小春。"]},{"t":"思云轩为罗师尚赋","f":"七言律诗","c":["思亲长日看云生，亲殁因轩寓旧名。","先世独推罗仲素，今人重见狄怀英。","心关瞑色随乌集，目极秋容与雁征。","每为三山歌陟岵，萧萧风雨候鸡鸣。"]},{"t":"游孤山和靖祠","f":"七言律诗","c":["山有梅花山不孤，先生甘与鹤同癯。","一杯黄土留前宋，千古清风映里湖。","疏影暗香曾入咏，淡妆浓抹自成图。","水仙祠下多秋菊，谁把寒泉当酒壶。"]},{"t":"柳庄为会稽薛德明赋","f":"七言律诗","c":["几年种柳绕村庄，翠色参天百尺长。","垂叶正当高士宅，飞花还过别人墙。","能诗杜甫憎春晓，嗜酒陶潜爱午凉。","何日棹航来鉴曲，据舷吹笛看湖光。"]},{"t":"松隐为屠景祥赋","f":"七言律诗","c":["馀杭溪上多长松，雪气遥连天柱峰。","蓝田自有韩子记，苍官不受秦人封。","风传虚籁清俗耳，日食扶苓延好容。","按图若遂归隐计，杖策许我来相从。"]},{"t":"送吴玉林分教富阳","f":"七言律诗","c":["家住双溪溪水滨，误将书剑走风尘。","散论文学过游夏，为爱山川到富春。","梦破小楼江月白，诗成古邑野梅新。","明朝又拥皋比坐，诗易那能让昔人。"]},{"t":"上元会饮次俞紫芝先辈韵","f":"七言律诗","c":["中年行乐遇新年，触目风光更接连。","夜色遥通鳷鹊观，春声先泛凤凰弦。","云中花乱疑瀛海，月下人归是洞天。","鬓点吴霜嗟老矣，踏歌槌鼓让童颠。"]},{"t":"悼王壶父","f":"七言律诗","c":["行藏多寄一壶中，枕上功名觉后空。","长吉诗多鬼仙气，宗师文有古人风。","笙悲夜月伤归鹤，弦绝春冰怨去鸿。","飞舄不知何处所，芙蓉城阙暮云红。"]},{"t":"真率斋诗为杨懋臣赋","f":"七言律诗","c":["真率应知出自如，会名又复到斋居。","举觞便可频开燕，溉釜何妨更煮鱼。","画为品题交互看，诗因分韵接连书。","子云识字无人问，白首玄经守敝庐。"]},{"t":"悼黄氏父子次周元亮韵","f":"七言律诗","c":["善人不得归乡里，此事端为识者哀。","客死忽惊枯骨返，人生那得好怀开。","眼中无复驱羊起，身后犹疑化鹤来。","丹井西颜松树在，空山斜日尚低徊。"]},{"t":"赠笔工杨均显","f":"七言律诗","c":["翁在相溪溪上居，偶因缚笔致名誉。","已烦猎者擒秋兔，更助文人校鲁鱼。","毛援犹能利天下，心殚宁肯不中书。","玉堂新样须重赠，拟效相如赋子虚。"]},{"t":"双鹤轩为鲁嗣衡赋","f":"七言律诗","c":["开轩正在西湖上，双鹤偶来能守扉。","复陂似托两黄鹄，过我疑多一羽衣。","秪道在阴其子和，宁知去郭昔人非。","仙家楼子曾相近，好伴孤云自在飞。"]},{"t":"如存堂为程进珉赋","f":"七言律诗","c":["外家宅相不须论，且筑书堂磅故园。","珠玉照人甥在侧，琼瑰赠舅母如存。","心同白水伤投璧，自极柯山念倚门。","三复渭阳诗意好，为观小序却销魂。"]},{"t":"送赵执中会试","f":"七言律诗","c":["圣主求贤在养民，儒生睹国早充宾。","一千里外知鸿鹄，四十人中见凤麟。","画舸溯风瓜渡晚，青袍沾雨杏园春。","泥金帖子须先寄，好向高堂慰二亲。"]},{"t":"送崔彦晖分教临安","f":"七言律诗","c":["临安古邑带山溪，送客西行意欲迷。","高适故人怜子美，崔群交友愧昌黎。","弯弓射圃秋观雁，看剑灯窗夜听鸡。","昭代英才初乐育，离觞不用惜分携。"]},{"t":"香橼即枸橼也康雪庭上人用赠紫芝上人因而有作予偶见之遂次其韵仍简紫芝","f":"七言律诗","c":["图寔如瓜尚得霜，老禅相赠杂青黄。","韵欺薝卜熏狮座，巧学流苏映象床。","蜡烛照来微弄影，金盆浴罢暗生香。","南州士女争雕镂，浸密涂脂取次妆。"]},{"t":"东山书隐为郑原宜赋郑本越人居东山先世徙杭遂家焉尝筑室西湖上从徐勉庵授书经因以为扁示不忘本也原直事亲以孝闻及筮仕都卫尤有声誉故赋长句以美之","f":"七言律诗","c":["东山读书隐居处，如何只在西湖边。","拟岘作记昔闻耳，思越寓吟今信然。","蔷薇花落忆李白，书带草生疑郑玄。","近闻去作幕下士，忠孝要看光简编。"]},{"t":"万竹轩诗为沈亮赋","f":"七言律诗","c":["种得筼筜得岁寒，数竿便作万竿看。","云闲不觉侵书幌，雪细从教点画阑。","纵有长丝牵紫鲤，可无明镜著青鸾。","东阳已赋郊居久，一任新来带眼宽。"]},{"t":"送郭子理归庐陵","f":"七言律诗","c":["严亲兵乱久相违，亲殁殊方骨未归。","苕水殡时先友盛，麦舟遗后故人稀。","已于名教能关系，况有文章为发挥。","此别会成迁葬计，免教空望白云飞。"]},{"t":"湘湖草堂为贡友初赋","f":"七言律诗","c":["湘湖卜宅似江郊，梅柳同栽已放稍。","春雨漏时愁在屋，秋风怒处忆飞茅。","莼丝流滑羹长用，荷叶分香饭屡包。","买得扁舟梭样大，呼童系在石塘坳。"]},{"t":"画菜次米仲谊韵","f":"七言律诗","c":["菘韭堪为早晚谋，老夫正欲拔其尤。","园葵自觉能防夏，野苋谁知亦有秋。","偶为画图思鲁直，肯因齑臼说杨修。","少陵莫道贫如庾，露薤盈筐不待求。"]},{"t":"送逯宏希远","f":"七言律诗","c":["上书曾达圣明朝，充贡仍随使者轺。","蝌蚪光生周与籍，凤凰声应舜箫韶。","杨雄献赋才无敌，逯石传家曾已遥。","抍得梅花当杨柳，春风又送木兰桡。"]},{"t":"送湛璿文衡","f":"七言律诗","c":["采绿曾看在泮池，飞黄况复值明时。","风霜雨露无非教，草木虫鱼总入诗。","把酒梅边春尚小，停车林下晚偏宜。","临行又欲歌棠棣，转忆同年是汝师。"]},{"t":"送王明善","f":"七言律诗","c":["月满西斋夜不扃，读书相对短檠青。","虫鱼草木资多识，敦厚温柔擅一经。","鹗荐此时虽衮衮，鸿飞他日更冥冥。","送行为子思王式，一曲骊驹仔细听。"]},{"t":"送沈仲名","f":"七言律诗","c":["沈约才华足起予，又因充贡别郊居。","好将言行同居寔，莫倚文章教子虚。","荐表他时称一鹗，尺书何日寄双鱼。","老夫重拭眵昏目，遥睇青云逐去车。"]},{"t":"云卧楼为卢宗文赋","f":"七言律诗","c":["金罍山色满庭除，偃仰长因饱食馀。","神女有时行雨过，仙人自昔好楼居。","龙归不觉衣裳润，蝶去方惊枕席虚。","莫向招提频借宿，且留丹壑待天书。"]},{"t":"次韵张伯雨天一井阑诗元金荪璧积庆冈物后在开元宫黄蔑楼今在王景周东圃万文远先作予因和之","f":"七言律诗","c":["玉阑铁画任歌斜，岂有人讥挂树蛇。","曾见坠星疑此石，相随落月是谁家。","辘轳声动晨牵绠，沆瀣光生夜浴砂。","阅尽开元到东圃，红楼翠幕不须誇。"]},{"t":"脑月见白牡丹为吕仲善长司赋","f":"七言律诗","c":["无边生意见荄滋，岁晚归来喜可知。","万木正当摇落后，一花如在艳阳时。","雪中不假转湘术，月下须吟李白诗。","若比玉杯真入用，疑盛春酒献瑶池。"]},{"t":"行素斋诗为韩性孜赋","f":"七言律诗","c":["海昌亦有平原裔，晚节斋居足养恬。","坐树濯泉唐李愿，经丘寻壑晋陶潜。","青衿日与谈章句，素履时能玩象占。","卖药归来人不识，杏花春雨满疏帘。"]},{"t":"旸谷轩为刘道明知事赋","f":"七言律诗","c":["扶桑暾出犹苍凉，轩楹照耀瞳眬光。","金矿铸橘一点火，丹心倾葵方寸长。","如中朱乌秩东作，似鸣仓庚眷载扬。","凤凰千仞览辉下，梧桐况复生高冈。"]},{"t":"静庵诗为德清知县陈彦荣赋","f":"七言律诗","c":["辟户为乾阖户坤，由来静者动之根。","宇安泰定天光发，肤达黄中地道尊。","谩说吉祥惟止止，须知成性本存存。","治心治事谁能此，独有希夷后世孙。"]},{"t":"雨香亭","f":"七言律诗","c":["轻雷送雨闹池蛙，藕叶生香胜似花。","但觉繁声鸣屋瓦，不须清气逼窗纱。","桐江如著高人钓，盘谷深藏隐者家。","想得亭中称寿日，碧筒杯里酌流霞。"]},{"t":"丁巳午日忽忆乙未有作追录之","f":"七言律诗","c":["江雨肥梅未作霖，天时人事日侵寻。","三年文叶能医国，五月葵花不易心。","唐殿赐衣犹有葛，扬州铸镜久无金。","投书欲吊沉湘魄，间说干戈楚地深。"]},{"t":"布谷篇","f":"七言律诗","c":["每向豳居玩物情，却怜野鸟解催耕。","雨收江上一犁足，风动林梢两个鸣。","如入画图供赋咏，莫将思怨起阴晴。","纪官此日无人问，秪问今秋万宝成。"]},{"t":"悼王观用宾","f":"七言律诗","c":["修短由来不可期，未应天道竟无知。","将闻司马终传史，犹记伯鱼初学诗。","江阻钱塘何限恨，山埋玉笥有馀悲。","老怀正复成多感，况值梅黄雨细时。"]},{"t":"友恭堂为胡拱衡赋","f":"七言律诗","c":["峨嵋山色扫晴空，中有高堂号友恭。","诗礼相传知岁久，埙篪迭奏觉春融。","枝连棣萼亲情似，树著荆花乐意同。","湖学育才先世事，子孙殊有古人风。"]},{"t":"五弦琴","f":"七言律诗","c":["闻说琴调天下治，直弦况值未加时。","在床被袗曾遭象，解愠颁侯更得夔。","和气尽从元气出，南风还类凯风诗。","缅怀千古岩廊上，爱物仁民本孝思。"]},{"t":"南屏对雪宿简公房次王子中韵","f":"七言律诗","c":["远近湖山淡复浓，此时浑失旧时容。","天寒故把瓶梅浴，雪冻难将野菜供。","东阁又吟年后句，南屏同听晚来钟。","翻疑一舸长桥过，重叠云衣护玉峰。"]},{"t":"为吴以道题红梅翠竹图","f":"七言律诗","c":["寒梅宜与竹交加，没骨图新对客誇。","翡翠剪翎分作叶，守宫流血点成花。","美人君子同千里，明月清风自一家。","威凤不来么凤悄，却因客鬓惜年华。"]},{"t":"挽邹母李恭人","f":"七言律诗","c":["恭人身殁已经年，子孝方知母氏贤。","空有杯棬存口泽，了无稊稗到心田。","一门节义谁能及，七月光阴自可怜。","好写断机投杼意，未须重补白华篇。"]},{"t":"晓望","f":"七言律诗","c":["晓日登临眼界宽，秋来随处好盘桓。","燕鸿也自关时序，松柏端如保岁寒。","伏阙惟天知对越，还家有竹报平安。","陈情一表须留藁，要与忠臣孝子看。"]},{"t":"中秋对月次张行中韵","f":"七言律诗","c":["桂树悬香四散飘，金风玉露满璇霄。","中秋有月偏澄澈，万里无云倍泬寥。","壮志每从诗上见，闲愁都向酒边消。","美人莫道音尘绝，只隔盈盈一水遥。"]},{"t":"赠铁符道人","f":"七言律诗","c":["乾刚比德行中孚，从此人间号铁符。","学道正同关尹子，传家元自管夷吾。","鹖冠礼斗天威近，龙剑飞空月影孤。","偶出市廛归去晚，桂花如雪点青芜。"]},{"t":"鸡冠花","f":"七言律诗","c":["花号鸡冠类剪裁，一丛却映凤仙开。","裹头绛帻非筹报，缠项红罗似斗回。","久养真能同槁木，恒饥宁肯啄苍苔。","亡陈不识孳孳意，玉树歌残后世哀。"]},{"t":"愚轩诗为上虞应信可赋","f":"七言律诗","c":["华轩结构地图雄，不似箪瓢陋巷中。","溪姓尚能随柳子，山灵端合避愚公。","衣冠此日何曾异，杖屦他时或与同。","樽有春醪堪独酌，更栽佳菊待西风。"]},{"t":"丁巳岁腊月二十日喜雪","f":"七言律诗","c":["快雪连朝遍海涯，眼明无处著尘沙。","腊前正欲呈三白，天下方知是一家。","今岁连云宜宿麦，何人剪水作飞花。","晚晴便觉春波阔，明日江头理钓槎。"]},{"t":"闻钟有感次荣子仁韵 其一","f":"七言律诗","c":["曾将锦瑟思华年，追忆当年重惘然。","五夜钟声来石枕，半生心事在韦编。","高楼明月狂呼酒，古道西风快著鞭。","赖有故人能过我，檐花细雨话灯前。"]},{"t":"闻钟有感次荣子仁韵 其二","f":"七言律诗","c":["欲觉闻钟记昔年，老怀多感益凄然。","轩前高柘当时种，屋上重茅近日编。","已悟达人遗破甑，还嗤市价鬻枯鞭。","目昏头白残灯里，始信聪明不及前。"]},{"t":"草庭为周元亮赋","f":"七言律诗","c":["无边风月满幽居，嬴得庭前草不除。","犹忆耳提因学礼，尚存手泽在诗书。","傍人错比康成宅，此地真疑葛亮庐。","我尔有轩曾种柘，宁知意思复何如。"]},{"t":"悼融上人","f":"七言律诗","c":["显明古刹化烟霞，甘露泉头即是家。","薝卜结成霜后寔，枇杷开到雪中花。","也知寂灭方为乐，始信浮生自有涯。","写得旧时行道影，不教尘土污袈裟。"]},{"t":"清江文会诗为崔驿丞赋","f":"七言律诗","c":["清江之水如练澄，盍簪此地皆良朋。","一钱尚怀会稽守，二松好放蓝田丞。","忘机鸥鸟偶到座，入馔鲈鱼还可罾。","兰亭陈巡在图画，新诗莫惜传溪藤。"]},{"t":"孙仲文奉亲图","f":"七言律诗","c":["敬亭山远白云层，如此高堂岂易升。","举足不能忘父母，介眉犹可及宾朋。","夏萱傍砌欣同赏，春酒盈觞忆自称。","锡类极知谁考叔，夜窗看画重挑灯。"]},{"t":"林塘幽乃会稽陈惟贤轩扁又号西畴因赠诗 其一","f":"七言律诗","c":["贺监湖头一曲开，林塘幽处著亭台。","青山在上水在下，黄鸟自啼鸥自来。","棋局不移长对奕，酒船才放即衔杯。","会稽我昔曾游地，杖履何时得重陪。"]},{"t":"林塘幽乃会稽陈惟贤轩扁又号西畴因赠诗 其二","f":"七言律诗","c":["南陌东阡欲尽头，农人指点是西畴。","风流我亦怀元亮，星聚谁能识太丘。","春及岂无耕耨事，秋成还有稻粱谋。","夕阳满地桑榆景，为看归鸦不下楼。"]},{"t":"雨中有怀次叶紫霞韵 其一","f":"七言律诗","c":["风雨秋深又满城，西畴端复望西成。","鉴湖自合归狂客，饭颗谁能问瘦生。","白发萧骚浑易感，黄花冷落尚多情。","天公欲遂登高约，只得重阳一日晴。"]},{"t":"雨中有怀次叶紫霞韵 其二","f":"七言律诗","c":["寂寂孤灯照一龛，壮年心事老年谙。","能吟快写犹无用，逐利争名更不堪。","衣服且将荷叶补，帽穿犹把菊花簪。","黄鸡紫蟹人皆醉，曲糵休言我独耽。"]},{"t":"雨中有怀次叶紫霞韵 其三","f":"七言律诗","c":["黄菊花开尚未齐，晨看偏爱露犹栖。","乍晴难得重阳节，久雨俄成十日泥。","往事忽惊风过耳，旧词空寄水平脐。","新晴愈觉秋容好，拄杖游山到处携。"]},{"t":"赠于友直写生","f":"七言律诗","c":["于翁画法出清新，气运依稀似院人。","拈笔经营方匠意，解衣盘礡自通神。","虫鱼草木知资识，月露风云绝点尘。","老去始知真有益，眼中无物不阳春。"]},{"t":"追挽王彦昭","f":"七言律诗","c":["庭下槐阴尚未稠，那知夜壑竟移舟。","忍将文字镌金石，愁见衣冠葬土丘。","雨露既濡空北望，江湖长在只东流。","孝思赖有传家子，为作高堂百世留。"]},{"t":"郑敬常求题画像因用同姓八事赞之","f":"七言律诗","c":["清白传家古所难，门名通德又开端。","履声未近星辰听，早带还经岁月看。","五色云中知姓氏，七株松下具衣冠。","毂推驿置非无意，谷口先须赋考槃。"]},{"t":"藏芸轩为陈惟德赋","f":"七言律诗","c":["曾见茅堂映德星，难兄难弟总穷经。","春藏芸草将除蠹，夜剪灯花不聚萤。","好效茝兰同作佩，宁知黍稷独非馨。","年来更得康成学，书带丛生绿满庭。"]},{"t":"芍药次王士中韵","f":"七言律诗","c":["一花开处万花残，心若黄金脸若丹。","正爱云霞烘薄暖，秪愁风雨送馀寒。","四枝曾有荆公折，两寺宁无蜀客看。","绣幕银屏深护取，莫教蜂蝶故相干。"]},{"t":"白云窗","f":"七言律诗","c":["白云长在碧窗寒，卧久袈裟转觉单。","来处就于檐下宿，晴时偏向卷中看。","阴淫鳗井朝尤爽，气压龙山午不乾。","读罢楞严方出户，天花飞满石阑干。"]},{"t":"己未端四复初以村居述怀及午日书事见示因次其韵 其一","f":"七言律诗","c":["池通细水树欹花，似是荒村老杜家。","堂上每来如客燕，园中还产在官蛙。","酒香昌独欺松叶，饭滑雕胡胜蕨芽。","石枕竹床凝午梦，觉来消得一瓯茶。"]},{"t":"己未端四复初以村居述怀及午日书事见示因次其韵 其二","f":"七言律诗","c":["节物惊心易感人，枇杷黄熟雨初匀。","新醪若得频刍瓮，旧服何妨重补纫。","门插艾枝成故事，粽包菰叶送比邻。","村居此日方泥泞，奇字谁能问子云。"]},{"t":"次韵周公辅游东阳东岘因其所述之实而赋之","f":"七言律诗","c":["每到看山眼倍明，况蓬东岘有馀清。","一时桂棹沙头拾，三日篮舆道上行。","事业每因多难见，文章端为不平鸣。","作亭曾拟羊公祜，莫道当时独好名。"]},{"t":"送云季昭为海昌训导","f":"七言律诗","c":["我名与汝姓名同，告别方知易已东。","下榻几时逢孺子，训符今代得文翁。","案头萤湿三更露，海上鹏抟六月风。","自笑穷经成白首，榴花空对酒樽红。"]},{"t":"赠周思温","f":"七言律诗","c":["过却重阳菊未黄，对花聊复举离觞。","雄姿未必非公瑾，妙算惟应是子房。","一片白云亲舍远，五更残月客窗凉。","功名自谓男儿事，富贵应期在帝乡。"]},{"t":"赠潘茂华","f":"七言律诗","c":["杭郡名医说茂华，子孙方脉世其家。","只疑庐阜千林杏，绝似何阳一县花。","道比古人端可墓，功参良相不为誇。","荣公作序能题品，愈觉芳声遍海涯。"]},{"t":"菊隐为金木才赋","f":"七言律诗","c":["先生冢世出㭦侯，种菊关心事颇幽。","清节独存三径晚，黄花又度一年秋。","尺书本草呼儿读，斗酒餐英与妇谋。","宅相作文因报德，南阳从此在南州。"]},{"t":"居闲为济人潘士中赋","f":"七言律诗","c":["安仁巳有闲居赋，后裔居闲也自宜。","身外功名何足慕，胸中今古却曾知。","松遮草屋关诗意，路踏云山入梦思。","三绝忽惊重睹日，少陵惭愧鬓成丝。"]},{"t":"题徐止善哀吾儿诗","f":"七言律诗","c":["天道茫茫竟莫回，忍看琼树掩泉台。","二三岁长能知孝，十六诗成总是哀。","夷甫钟情言服简，乐天垂泪字题崔。","会须积善如先世，重有麒麟入梦来。"]},{"t":"赠周宗性龙成教谕","f":"七言律诗","c":["昌化邑中周教谕，又为教谕到南昌。","不除庭草留春色，重采池芹带雨香。","鸷鸟何如承鹗荐，斗牛长似射龙光。","江空岁晚难为别，折得梅花当举觞。"]},{"t":"林泉读书图为徐质赋","f":"七言律诗","c":["城里看山尽不如，廛居聊复拟幽居。","道通天地方为学，志在林泉好读书。","高架香浮芸帙乱，短檠光动竹窗虚。","公侯已卜他年事，况是徐卿积善馀。"]},{"t":"题谟范堂集云轩","f":"七言律诗","c":["慈云每集招提上，此地开轩号集云。","山气有时还笼嵷，天花无处不缤纷。","随风偶作孤飞态，映日都成五色文。","知是神龙听法罢，打窗凉雨定中闻。"]},{"t":"明远夏氏界画高骈夏日山居诗意","f":"七言律诗","c":["科分界画见良工，诗意分明笔意同。","直下楼阴浑似雾，偶来花气却因风。","水晶帘动粼粼皱，云母屏开曲曲通。","闻道主翁骑鹤去，不应犹落画图中。"]},{"t":"钱舜举桃源图","f":"七言律诗","c":["闻说桃源何处寻，披图想像重沉吟。","锦云霭霭藏蓬岛，红雨纷纷落树林。","一叶渔舟迷远近，几家农舍隔幽深。","眼看宋业将移晋，惆怅先生避世心。"]},{"t":"曾瑞卿所作山水图","f":"七言律诗","c":["山关迢递野桥斜，策杖幽寻岂惮赊。","路转峰回连佛寺，鸡鸣犬吠隔人家。","白云作雨多如絮，红叶惊风少似花。","不是褐夫能貌淂，空今泉石老烟霞。"]},{"t":"己未午日次沈钦叔韵","f":"七言律诗","c":["今年两度逢端午，前月方当后月非。","到手人将蒲酒劝，满头谁插艾花归。","水亭得句题纨扇，风馆焚香试葛衣。","读罢离骚增感慨，绿阴满地客来稀。"]},{"t":"夏日书怀次沈钦叔韵","f":"七言律诗","c":["黄梅子熟暑蒸润，冬青花开云作阴。","昨宵北牖雨声急，明日西湖流水深。","论才子建得八斗，换酒太白轻千金。","幽怀欲写托长句，又闻绿树新蝉吟。"]},{"t":"五月二十日寿洪时中广文用复初韵","f":"七言律诗","c":["仙号洪崖是此翁，后身聊复寄黉宫。","春秋学外无馀子，月旦评中有至公。","清极每憎茶七椀，衰迟宁羡粟千钟。","今年两遇称觞日，赖有葵榴接续红。"]},{"t":"望云诗为常德新赋","f":"七言律诗","c":["慈母音容阻见闻，举头何处是并汾。","心思白发千茎雪，目极青天万里云。","寒逐晓鸦采点点，暖随春雁去纷纷。","八年不作斑衣舞，日下空瞻五色文。"]},{"t":"拙庵为仲和赋","f":"七言律诗","c":["灌园抱瓮不辞疲，日入还思偃息时。","鸠占鹊巢应笑拙，蝉遭螳臂竟成痴。","幽居子美留唐咏，乞巧宗元记楚词。","闻说一庵天目上，欲寻高适重相期。"]},{"t":"胡敔衡瑶芝轩","f":"七言律诗","c":["去郭轩楹也自奇，独峰相对好吟诗。","如游梁宋拾瑶草，胜在商岩采紫芝。","宝树传家成故事，铜池应瑞出当时。","多君素有亲贤意，更种幽兰寄所思。"]},{"t":"送叶继善还三衢","f":"七言律诗","c":["佩玉曾闻觐至尊，赐金殊觉被深恩。","三千远道方辞阙，九十慈亲正倚门。","台忆凤凰夜径失，字传蝌蚪竹书存。","老莱衣待归时著，拟采红椒献绿樽。"]},{"t":"丈八沟纳凉图","f":"七言律诗","c":["万个筼筜一径开，水花晚色映亭台。","日将落处船初放，诗未成时雨又催。","琥珀蔗浆供雪椀，象牙莲藕荐霞杯。","渼陂未必奇如此，何事岑参不共来。"]},{"t":"清源诗为谷士源赋","f":"七言律诗","c":["欲识清泠五类先，源头一脉自涓涓。","满除潢潦皆因雨，混浊泥沙不见天。","正本当令民绝讼，溯流还许酒称玄。","谁知谷永贤孙子，心在皇羲太古前。"]},{"t":"悼王晦岩","f":"七言律诗","c":["数到湘江独此翁，晦踪岩穴见高风。","每将鱼馔供堂上，长著羊裘钓泽中。","民讼望庐多自返，岁饥发廪与人同。","如何玉树埋黄土，赖有佳铭托鐉公。"]},{"t":"送丁自南代祀嵩岳还龙虎山","f":"七言律诗","c":["泰华恒衡列四方，崧高维岳在中央。","降神自昔生申甫，代祀于今轶汉唐。","羽士祝釐遵典礼，鸿儒染翰作文章。","遥怜蕙帐归来鹤，长向山中护草堂。"]},{"t":"郑生画卷","f":"七言律诗","c":["绘事后素知有分，如以霄漠行烟云。","华虫宗彝尧舜服，龙马神龟河洛文。","擅场妙绝推道子，解衣盘礡逢元君。","王会作图在今日，好为丹青先策勋。"]},{"t":"画","f":"七言律诗","c":["界画尝闻殿画科，却因陈迹费吟哦。","林深白日繁槐柳，池小青天足芰荷。","西路名园无复见，平泉遗石竟如何。","人间正苦逄炎热，不道凉飙此地多。"]},{"t":"赵氏碧筠轩","f":"七言律诗","c":["竹下开轩号碧筠，旧家公族尚振振。","每瞻淇澳思君子，独立湘皋望美人。","诗到东坡称作手，谱通安定悟前身。","霅溪绕舍清如玉，翡翠兰苕巧斗新。"]},{"t":"题吕信夫传","f":"七言律诗","c":["居里还同朱寿昌，传家应自吕荣阳。","学仙已悟黄梁枕，事死仍分彩服堂。","独鹤归来城郭是，三鱼跃出井泉香。","子孙又为明时用，忠孝须知系典常。"]},{"t":"听雪同张行中赋约以禁体","f":"七言律诗","c":["黄昏微霰已垂垂，侧耳还从静里知。","清讶松风茶熟后，暗疑花雨酒醒时。","黑甜今夜浑无梦，白战当年自有诗。","侵晓开窗何所见，飘然多在老梅枝。"]},{"t":"雪山","f":"七言律诗","c":["连朝积雪满亭台，一篑功成陋土堆。","银壁有痕缘削出，玉峰无翅解飞来。","趁晴更把双狮塑，傍晚犹疑独鹤回。","记取开元张彖语，冰山莫认作崔嵬。"]},{"t":"清隐堂为徐清隐赋","f":"七言律诗","c":["清隐之堂何所奇，赤岸气接银潢湄。","德公岂无刘表叹，孺子亦有陈蕃知。","不独丘园事高尚，况复河水清涟漪。","小篆有文人解读，月下凤管应曾吹。"]},{"t":"思云为松江褚伯嘉赋","f":"七言律诗","c":["三泖溶溶映九峰，白云飞处认吴淞。","思亲甚似狄仁杰，尚友当如陆士龙。","鹤鸟每从秋枕听，鲈鱼曾向午盘供。","十年不作华亭梦，月落空闻北寺钟。"]},{"t":"送金叔刚以慱学赴京","f":"七言律诗","c":["昭代搜贤设礼罗，临岐无柰别情何。","不逄错节那为器，须信宏辞自有科。","云岫龙蟠丹阙近，星河鹭起綵舟过。","遥知上苑春光早，开遍官梅白玉柯。"]},{"t":"胡拱衡峨嵋读书图","f":"七言律诗","c":["何处鑋成隐者居，桑麻榆柳翠扶疏。","溪环永泰门无辙，山对峨嵋架有书。","短帽客来时泛蚁，小舟人到日供鱼。","画图一见生诗思，高枕浑疑是我庐。"]},{"t":"挽王士贞检校","f":"七言律诗","c":["多能我亦叹多才，较艺贤关屡中魁。","南海忽惊王渤死，西河还动卜商哀。","方期捧檄三山去，谩忆乘槎万里回。","一掬平生师友泪，忍捋樽酒酬泉台。"]},{"t":"画鹤","f":"七言律诗","c":["薛公曾写十一鹤，此卷多三孰写成。","片月不来还有影，九皋飞远却无声。","赋形大小随人意，作态低昂见物情。","安得长才如杜甫，为吟老气发峥嵘。"]},{"t":"送刑部员外郎张时彦侍亲归永喜","f":"七言律诗","c":["博学登庸岂等闲，为亲捧檄为亲还。","阙廷久恋心逾赤，江海重逄鬓欲斑。","日丽凤台辞禁苑，云连雁荡认家山。","高堂定想卜乌鹊，五彩衣藏箧笥间。"]},{"t":"云林书舍为靳梦文赋","f":"七言律诗","c":["云木成林绝点尘，读书精舍有诗人。","乾坤万里市朝远，风露一堂灯火亲。","不为肥甘知隐遁，祗因勤苦见经纶。","襄阳物色归图画，谁解移家愿卜邻。"]},{"t":"南明轩为指南宗上人赋","f":"七言律诗","c":["山对南明景益奇，轩因高敞望偏宜。","倚窗好寄陶潜傲，留客须吟杜甫诗。","陇月更圆谁共宿，碧云暮合尔同思。","如何又向东林去，漏刻连花礼六时。"]},{"t":"送谢铁崖住祖庭","f":"七言律诗","c":["谢庭兰树尚青青，又捧仙书赴祖庭。","星剑夜腾龙虎气，霞衣朝拂凤凰翎。","金为宫阙知天近，铁作岩崖验地灵。","独有上清双白鹤，飞来听诵蕊珠经。"]},{"t":"送王士端赴成均","f":"七言律诗","c":["青云高步快先登，万里鹏程自此升。","经究春秋唐杜甫，志轻温饱宋王曾。","朝廷正欲招贤士，庠序宁辞失友朋。","观国充宾须第一，龙蟠虎踞是金陵。"]},{"t":"送于潜赵县承彦礼归河南","f":"七言律诗","c":["祗将琴鹤返梁园，告别匆匆莫赠言。","衣锦何须誇季子，买丝端合绣平原。","归时松菊犹三径，到处桑麻自一村。","潜水西风多落叶，临岐争忍举离樽。"]},{"t":"停云楼为四明王德修赋","f":"七言律诗","c":["停云蔼蔼在高楼，几度怀人叹阻修。","安得陶潜共延伫，也胜王粲独消忧。","昼眠忆弟劳青眼，秋望思亲惧白头。","亦有神仙解怡悦，何时骑鹤重来游。"]},{"t":"挽翁顺卿宪史","f":"七言律诗","c":["读书读律已称贤，孝友尤闻远迩传。","方喜故园归栗里，还愁沧海变桑田。","多登乌府三千日，梦熟黄粱五十年。","愧我平生曾识面，欲携鸡絮酹新阡。"]},{"t":"忠养堂为张原善赋","f":"七言律诗","c":["堂前花竹自清幽，春笋秋梨不外求。","定省岂能忘喜惧，旨甘还得及交游。","彩衣舞罢雏曾弄，绿醑斟来蚁正浮。","欲识事亲忠养意，惟应张仲是前脩。"]},{"t":"松月斋为张克敬赋","f":"七言律诗","c":["斋前尽是长松树，山月来时分外清。","龙吐大珠惟一颗，鸾窥圆镜欲三更。","秋声径度窗棂响，夜色斜穿屋角明。","不用乘槎天上去，且于江海老馀生。"]},{"t":"复锦轩为钱宗文赋","f":"七言律诗","c":["公侯复始事非誇，忠孝相传有几家。","尚忆故城各衣锦，岂容馀泽尽丝麻。","日斜湘曲乌栖树，潮上海门蜂退衙。","闲坐小轩观族谱，不知开尽一庭花。"]},{"t":"云谷为王彦常赋兼简敬仲","f":"七言律诗","c":["阴阴幽谷只藏云，杖策曾来访隐君。","山合转添成巃嵷，水回偏觉带氤氲。","不须剥栗思工部，正欲来禽寄石军。","翻忆临江贤大守，何时樽酒细论文。"]},{"t":"九日游吴山次韵","f":"七言律诗","c":["陈迹空存事往非，却因山色认依稀。","风轻破帽何曾落，潮迅征帆却似飞。","有酒当朝陶清节，无诗空忆谢玄晖。","古今不尽登临意，醉插黄花步月归。"]},{"t":"芳桂堂","f":"七言律诗","c":["大书芳桂揭高堂，甚似燕山窦十郎。","会见五枝承雨露，应知独秀饱风霜。","种槐庭外宁无地，栽柳门前自有庄。","秪用一经勤教子，嬴金未必胜天香。"]},{"t":"来青堂","f":"七言律诗","c":["容膝方谋屋数间，未应海岱异荆蛮。","移家渐近前溪水，排闼平分隔岸山。","锦瑟湘娥人不见，金茎汉雀自飞还。","满帘草色琴书罢，独爱高人对我闲。"]},{"t":"万山窝","f":"七言律诗","c":["门外尘无一点红，结窝正在万山中。","似知剡曲回舟者，如见伊川击壤翁。","晚对翠屏消暇日，时闻黄鸟忆豳风。","不须安乐重题扁，已觉夫来俗虑空。"]},{"t":"回顾庵","f":"七言律诗","c":["茫茫六合自高深，一望方知有古今。","沧海白鸥从浩荡，长空孤鸟付消沉。","东冈南涧频经目，春雨秋霜总在心。","赖有小庵当绝顶，花时无日不登临。"]},{"t":"次张一中赠友诗韵","f":"七言律诗","c":["清朝有道野无贤，乔木新莺屡见迁。","秋色遥连萧寺树，虹光下射米家船。","一壶浮蚁倾杯美，三尺肥鲈入馔鲜。","幕府长官才思敏，草书诗句满花笺。"]},{"t":"题莫景行棣华碑","f":"七言律诗","c":["传家谱牒今无恙，达世歌辞每见情。","原上鹡鸰曾共难，山中鸥鸟亦同盟。","及时行乐俱闲暇，晚节交游各老成。","零落棣华谁与问，紫霞柶处是佳城。"]},{"t":"赠陈惟铭北行","f":"七言律诗","c":["汝兄捧檄倅沧州，远别常思共被秋。","已效诗人咏棠棣，更从乡老识松楸。","季方论德难为弟，太史能文岂好游。","此日甘旨频在念，还家须早莫淹留。"]},{"t":"岳鄂王墓","f":"七言律诗","c":["前相汪黄后相秦，力图恢复竟何人。","朱仙路近旌旗晚，古汴城高草木春。","江月照空埋剑狱，胡沙遮断属车尘。","栖霞岭下将军冢，夜夜悲风起石麟。"]},{"t":"青田山房","f":"七言律诗","c":["好溪正绕青田县，留子山房在上头。","采得松花堪酿酒，种来莲叶可为舟。","鹤迷空翠晴犹湿，龙带归云夜不收。","兄弟娱亲无限乐，拔援丛桂欲淹留。"]},{"t":"美人图","f":"七言律诗","c":["不踏金莲步不移，搔头仍是玉蟠螭。","自将凤管调银字，谁把鸳机织锦丝。","得伴有时来斗草，遣怀随处共弹棋。","鸣鸠乳燕青春晚，谢却繁花几万枝。"]},{"t":"梅花清梦为沈士敬赋","f":"七言律诗","c":["香凝燕寝宵未分，急雨打窗浑不闻。","美人忆在湘江水，行路恍隔梨花云。","残灯纸帐尚知我，落月屋梁疑见君。","西湖东阁两奇绝，眼中蝴蝶何纷纷。"]},{"t":"翠涛轩","f":"七言律诗","c":["松轩谁作翠涛扇，数聿丹青犹未乾。","江头曾记八月听，石上况得双株看。","己因吹万问天籁，还如后凋知岁寒。","清流一掬可洗耳，何时与子共盘桓。"]},{"t":"集古句送郑彦才赴京","f":"七言律诗","c":["为君书此报京华，凤吹声如隔彩霞。","庭下已生书带草，马头初见米囊花。","晨摇玉佩趋金殿，夜泊秦淮卖酒家。","君在江南相忆否，乌衣巷口夕阳斜。"]},{"t":"游虎跑泉次坡仙韵","f":"七言律诗","c":["杖藜偶到南山上，一见灵泉即驰仰。","每炊云子白于脂，曾洗雕胡大如掌。","何年巨兽启神踪，长日还飙递馀响。","须防投石犯清泠，观法由来非妄想。"]},{"t":"梅雪四律代张翚徐术陆平沈廉赋 其一","f":"七言律诗","c":["北风日日吼枯株，点检春光定有无。","半树里深犹妩媚，一枝檠重更模糊。","芳香未露还因冷，疏影浑迷不为晡。","想得孤山人迹灭，扁舟谁复访林逋。"]},{"t":"梅雪四律代张翚徐术陆平沈廉赋 其二","f":"七言律诗","c":["天教姑射会滕神，邂垢相逢自主宾。","纵使积成三尺冻，如何藏得一分春。","饥乌啄处栖难定，么凤飞来认未真。","蜡屐正愁山路滑，无由重折赠诗人。"]},{"t":"梅雪四律代张翚徐术陆平沈廉赋 其三","f":"七言律诗","c":["梅开岂与雪相谋，雪到梅边分外幽。","算老只除松强项，论交还使竹低头。","增添冷艳疑临镜，封闭寒香不入楼。","对此一时清兴发，西湖船胜剡溪舟。"]},{"t":"梅雪四律代张翚徐术陆平沈廉赋 其四","f":"七言律诗","c":["老干柔条被雪封，五花还与六花重。","从渠易改清癯态，到底难藏冷淡容。","弄色却非怜冻雀，收香长是误寒蜂。","何如插向铜鉼里，煮水煎茶兴更浓。"]},{"t":"拟赋桃灯杖 其一","f":"七言律诗","c":["形如新月带微弯，相伴银缸影不单。","寸草有心须用尽，双花报喜莫教残。","留连孤主知天晓，沾溉馀膏觉夜寒。","赖得主翁频举手，简编宁向暗中看。"]},{"t":"拟赋桃灯杖 其二","f":"七言律诗","c":["陶铸功名谢切磋，频挑试问夜如何。","从前扶策心长在，到底推移力更多。","次第烧残三寸草，分明垂下一枝荷。","短檠他日宁同弃，好效昌黎重作歌。"]},{"t":"拟赋桃灯杖 其三","f":"七言律诗","c":["斜倚弯弯玉一枝，策勋虽小贵逄时。","近床不厌频挑早，开卷宁辞再举迟。","乘暗每于贪睡后，生明多在正心时。","独怜映雪囊萤者，如此形容想未知。"]},{"t":"拟赋桃灯杖 其四","f":"七言律诗","c":["儒家此物用筵篿，浸润膏油节愈坚。","倒影每来书卷上，尽心长向酒樽前。","搔头已逼穷年景，举手能成不夜天。","想像流光端可比，只从暗里自推迁。"]},{"t":"拟赋桃灯杖 其五","f":"七言律诗","c":["灯掭还于盏面横，却因挑剔强为名。","赋形且截长为短，举手能教暗作明。","轻助草生还有色，缓推花落更无声。","美人闲却金钗股，却笑蛾眉尽未成。"]},{"t":"香奁八咏 其一 黛眉颦色","f":"七言律诗","c":["春山低压不成妆，捲起珠帘认渺茫。","鸳翠巧于愁里故，螺青难比画时长。","从教西子倾吴国，肯使文君老蜀乡。","莫指图中小颦处，恐惊胡马动渔阳。"]},{"t":"香奁八咏 其二 香颊啼痕","f":"七言律诗","c":["伤心何事损铅华，玉露无声玉箸斜。","獭髓凝膏痛如意，胡沙吹面泣琵琶。","愁淹锦字和衣揾，怕界妚妆倩酒遮。","翻忆昨宵残烛暗，一帘春雨湿梨花。"]},{"t":"香奁八咏 其三 金盆沐发","f":"七言律诗","c":["金盆潋滟匆浮脂，鬓发如云试沐时。","雪坏石苔梳翠线，波明池柳蘸青丝。","频添沉水心思懒，未尽兰膏手握迟。","却把罗巾拭馀润，爱他红日上花枝。"]},{"t":"香奁八咏 其四 月奁匀面","f":"七言律诗","c":["初开玉匣遣眉颦，再御铅华情指匀。","白兔宫深颙望久，影娥池冷艳妆新。","英蓉绿水偏宜晓，芍药金盘可待春。","不似前时中酒后，厌厌怀抱易生嗔。"]},{"t":"香奁八咏 其五 金钱卜欢","f":"七言律诗","c":["底事春来减玉肌，藁砧一去杳无期。","定知玉箸偷垂处，正在金钱暗掷时。","握粟几朝空出卜，采蘋何地重相随。","下阶羞见宜男草，背立东风听子规。"]},{"t":"香奁八咏 其六 绣床凝思","f":"七言律诗","c":["午窗风暖唾茸香，无语停斜倚绣床。","意懒不缘闻喙木，情伤端为剌鸳鸯。","絮毬滚处从圆碎，綵缕抛时任短良。","唤起一春心上事，数声莺语隔垂杨。"]},{"t":"香奁八咏 其七 花尘春迹","f":"七言律诗","c":["双鸳微步不须扶，谁蹑行踪认有无。","春径尘香初彷佛，晚风花落又模糊。","凌波罗袜骛神女，衬地金莲陋玉奴。","几度含毫空想像，却怜新月印平湖。"]},{"t":"香奁八咏 其八 云窗秋梦","f":"七言律诗","c":["碧天云散月三更，人在纱窗梦欲成。","灯焰有花随蝶化，簟纹如水怕蛩鸣。","钱唐谩听当年曲，巫峡空含此夜情。","檐马无端又惊起，满怀幽恨不分明。"]},{"t":"雪中八咏次睢宗吉韵 其一 雪梅","f":"七言律诗","c":["斗白争青共岁寒，比同颜色不多般。","散来龙脑都成片，剪碎鲛绡却作团。","风细易教钗舞燕，月明难许镜窥鸾。","瘦筇就地闲书字，秪恐明朝迹又漫。"]},{"t":"雪中八咏次睢宗吉韵 其二 雪竹","f":"七言律诗","c":["三径难同蒋诩游，窥檐犹自问稀稠。","直于晚岁方知节，更待清风始点头。","阻食凤凰端有感，迷巢翡翠谩生愁。","季卿若有王猷兴，安得仙人叶作舟。"]},{"t":"雪中八咏次睢宗吉韵 其三 雪柳","f":"七言律诗","c":["柔枝曾记插军持，佛日光明每借晖。","纵使粉妆春态度，何如珠压旧腰围。","粘条缕缕俱成带，溜汁涓涓可染衣。","一夜东风浑不见，看灯人匀月中归。"]},{"t":"雪中八咏次睢宗吉韵 其四 雪雀","f":"七言律诗","c":["白翎彷佛似裙拖，为问乌桓事若何。","无角畏寒穿古屋，有雏怜馁恋前窠。","野田泥湿难寻粟，门径人稀易设罗。","闻道上林无限树，春风还尔旧枝柯。"]},{"t":"雪中八咏次睢宗吉韵 其五 雪雁","f":"七言律诗","c":["一般整整与斜斜，疑是春归趁柳花。","瑞比凤凰逄盛旦，清同蝴蝶梦南华。","远遵震泽迷银渚，暗度衡阳聚玉沙。","半折风蒲坡老句，并和图画落谁家。"]},{"t":"雪中八咏次睢宗吉韵 其六 雪狮","f":"七言律诗","c":["搏雪依稀类若麟，却将毛毳变珠珍。","金铃綵索聊为饰，玉爪银牙宛似真。","方讶吼风能吐舌，秪愁见睍莫存身。","兽炉兽炭回春处，想像题诗笔有神。"]},{"t":"雪中八咏次睢宗吉韵 其七 雪水","f":"七言律诗","c":["只将兴灭论荣枯，众有安能胜一无。","阳火炼来还作永，阴崖滴下不成珠。","寒消帘幕冰如箸，润及瓶罂夜有炉。","白浪绿波随处看，明朝春色满江湖。"]},{"t":"雪中八咏次睢宗吉韵 其八 雪灯","f":"七言律诗","c":["灯花为喜雪为祥，又向穷阴见一阳。","星夜松明疑石屋，霜天渔火记江乡。","连城白璧元无价，照乘明珠自有光。","曾踏春冰穿市过，少年犹忆醉平康。"]},{"t":"雪湖八景次瞿宗吉韵 其一 鹫岭雪峰","f":"七言律诗","c":["大地浑无一点瑕，光明都属梵王家。","两峰高并疑堆王，一道中分类剖瓜。","已为岧峣知鹫岭，还因凛冽记龙沙。","此时翻忆监关句，谁复能开顷刻花。"]},{"t":"雪湖八景次瞿宗吉韵 其二 冷泉雪涧","f":"七言律诗","c":["下有流泉上有松，诸山罗列玉芙蓉。","垆头又酿谁家酒，屐齿应嫌此处踪。","汲去煮茶随瓮抱，引来刳木入厨供。","涧边亭子无人宿，空使援号昨夜峰。"]},{"t":"雪湖八景次瞿宗吉韵 其三 巢古雪阁","f":"七言律诗","c":["人间蓬岛是孤山，高阁清虚类广寒。","木处恐颠从此稳，僧居疑小较来宽。","瑶花琪树绿边绕，玉宇琼楼向上安。","里外湖光明似镜，有梅花处好凭阑。"]},{"t":"雪湖八景次瞿宗吉韵 其四 南屏雪钟","f":"七言律诗","c":["翠屏化作玉千层，楼近钟疏恍若凭。","和雪送来清沥沥，穿云透出慢腾腾。","华鲸谩意秋号月，铁马浑疑夜响冰。","一百八声才击罢，雷峰又点塔中灯。"]},{"t":"雪湖八景次瞿宗吉韵 其五 西陵雪樵","f":"七言律诗","c":["湖曲风寒战齿牙，不知高树已翻鸦。","远持斤斧黏冰片，旋斫柴薪带雪花。","市上淂钱沽斗酒，担头悬笠插山茶。","路人试问归何处，笑指西陵是我家。"]},{"t":"雪湖八景次瞿宗吉韵 其六 断桥雪棹","f":"七言律诗","c":["山逗晴光玉气浮，我来乘兴似王猷。","桥迷螮蝀高高耸，船压玻瓈细细流。","雪后未回花外棹，雨中曾唤柳阴舟。","遥思寂寞春寒夜，一舸归来起白鸥。"]},{"t":"雪湖八景次瞿宗吉韵 其七 苏堤雪柳","f":"七言律诗","c":["寒梢不耐北风狂，何似东风万缕黄。","西子画来螺黛浅，苏公行处马蹄香。","兰同旧叶堪为佩，藕比新丝可织裳。","待得春归飞絮乱，画船移近柳边傍。"]},{"t":"雪湖八景次瞿宗吉韵 其八 孤山雪梅","f":"七言律诗","c":["冻木晨闻噪毕逋，孤山景好胜披图。","翠禽巢失应难认，皓鹤笼空不受呼。","已见万花开北陇，莫教一片落西湖。","快晴更待黄昏月，疏影随身不用扶。"]},{"t":"七月朔寿徐大参五十韵","f":"五言古诗","c":["光岳千年合，车书万里全。","天开斯地辟，主圣自臣贤。","有美坐人杰，由来系薮渊。","景星方快睹，时雨必开先。","盛世逄三五，贤人出半千。","黄冈饶巨竹，赤壁亘长烟。","物论咸称首，才名孰比肩。","传芳由柏业，体道契松佺。","大厦须梁栋，前贤赖简编。","玉壶澄皓月，清庙永朱弦。","书岂阳冰亚，诗应子美专。","威仪畴若此，阀阅固依然。","远借长风便，亲承湛露涓。","一麾初出守，百辟共朝天。","履听星辰上，光分日月边。","岂惟衣服衮，端有笔如椽。","版籍登民数，丝纶振吏铨。","玉文龙矫矫，紫诰凤翩翩。","御酒浮卮满，宫花插帽偏。","阶辞天表近，帐阻地隅填。","野色明朱绂，川容动彩旃。","地连淮海外，省镇浙江堧。","奕奕三台位，煌煌五纬躔。","阴阳资燮理，封域待旬宣。","丙魏萧曹接，韩欧富范联。","政刑随日化，风俗与时迁。","析木初飞鹊，高槐尚噪蝉。","今朝云郁丽，后夜月婵娟。","弧矢逄华旦，椿楸见大年。","秋期先六日，佳气蔼初筵。","寿域宏千里，春台广八埏。","正名恢乐地，种德布心田。","鹓鹭思同列，麟麒喜满前。","岂无瓜似枣，亦有藕如船。","仙鹿衔朱草，神龟上碧莲。","歌怜莺睍睆，舞爱鹤翩跹。","自是青云器，仍兼紫府权。","劳谦延下士，致泰启重乾。","事业期周召，文华继许燕。","公其为辅弼，走也与陶甄。","有道千钧重，无私一鉴悬。","考功齐郭令，论帙拟彭篯。","愈觉勋庸盛，尤知志操坚。","作兴周礼乐，整顿禹山川。","已注长生箓，当为不老仙。","未容居绿垑，宁许见华颠。","素积阴功厚，能同造物旋。","偕行追九老，众妙入重玄。","欲祝先天算，还歌七月篇。","愿言多寿祉，流庆日绵绵。"]},{"t":"七月流火","f":"五言古诗","c":["人间逄七月，大火向西流。","民事终嫌晚，天时始应秋。","三星低北户，万象拱南州。","箕尾同成纬，珠玑异缀旒。","金波分穆穆，银汉与悠悠。","类烛辉瑶席，疑萤度玉楼。","色连朱阁迥，光动翠帘幽。","栗烈将催候，晶荧故眩眸。","气随霜露变，事逐岁年遒。","布帛堪为褐，狐狸可制裘。","先时还有备，卒岁每无忧。","偶读豳风作，端为大业谋。","愿陈忠厚意，万一贲皇猷。"]},{"t":"葛孝子诗五十韵","f":"楚辞体","c":["古云孝悌至，可与神明通。","其深入厚地，其高亘苍穹。","上广圣之治，下变时之雍。","流观孝子传，乃见古人风。","保定地清远，形胜当要冲。","天民有苗裔，良知自孩童。","氏续并明彊，道继勾漏洪。","温其玉出璞，烂兮金在镕。","岂惟竭其力，亦复殚其恭。","堂前荆树紫，阶下萱花红。","身无千钟禄，心有一寸彤。","板舆快秋爽，菜服明春浓。","常存怀橘念，每感断机功。","覆杯戒前日，温席当严冬。","但知子力尽，孰计时运终。","王纲一解纽，四海皆兴戎。","无城不兵甲，无地不燧烽。","南方乱豺虎，中泽飞雁鸿。","堪舆岂不大，仓卒难为容。","他山号明府，拔地多奇峰。","避难屡跻险，充饥晅致供。","俄然大风作，出自空谷中。","其行若有隧，其孽为召凶。","亟思逃匿地，庶保圣善躬。","朅来众黔首，过半摧霜锋。","生还访故里，旧业无遗踪。","所恃靡毫发，惟孝持心胸。","神忽凭妪体，言犹在人聪。","汝能笃以孝，吾斯启其衷。","匪为一时幸，永俾后裔隆。","易水流汤汤，金台屹崇崇。","岂无慷慨士，亦有文章公。","皆言葛孝子，不愧江次翁。","官将立华表，人岂弃黄钟。","绣衣行荐鹗，彩笔竞雕虫。","为亲捧儒檄，讲道居黉宫。","遂令燕赵俗，直与邹鲁同。","忽罹陟屺戚，已从若堂封。","哀伤动桑梓，悲惨连楸松。","诵诗后蓼莪，读礼先檀弓。","深戚养之薄，殊胜祭者丰。","端因事迹美，益见传语工。","圣世惇孝悌，淳风迈义农。","车书涀文轨，声教渐西东。","孝子复有子，承宗亦兴宗。","梧冈孤凤鸣，柏府一马骢。","移悌为长顺，移孝为君忠。","垂名照青史，应瑞踰黄琮。","我歌孝子诗，锡类期无穷。"]},{"t":"顾定之墨竹","f":"五言古诗","c":["淮南善画竹，其世宗虎头。","前身萧恊律，后身文湖州。","浓墨逼景献，健毫从澹游。","清如李息齐，劲若柯丹丘。","子昂固莫及，仲敏或可侔。","素得金错法，向背分刚柔。","兴来秪一扫，挥处踰双钩。","两叶已笼夏，风枝仍报秋。","遂令爱竹者，不必穿林幽。","尝闻维摩像，神光烛遐陬。","何如君子容，苍颜照清流。","胸中有渭川，湛水同悠悠。","载歌瞻菉咏，吾其企前脩。"]},{"t":"为华子宜赋山隐","f":"五言古诗","c":["招隐何处所，宛在栎山岑。","人同西岳号，地异真源寻。","履随绿玉枝，冠映青瑶簪。","罗月炯颜色，松风洒尘襟。","鍊液变白雪，烧丹成紫金。","传授龙马图，啸歌鸾凤音。","稽首希夷子，寥寥同此心。"]},{"t":"沈绍宗东图轩","f":"五言古诗","c":["隐候美孙子，学古将入官。","长以空洞腹，负此苜蓿盘。","轩东地颇衍，日出作愈艰。","偶得树艺术，永充朝夕箪。","种蔬不欲密，瘦地方易殚。","种蔬不欲稀，粝食味易阑。","学圃固云陋，灌园乃所安。","杞菊春可揽，葵藿时加餐。","之子方挟策，同寅俟弹冠。","不爱东门瓜，不爱九畹兰。","爱此菽水奉，宜尔萱亲欢。","有圃当耕锄，有田可游观。","一朝蠖之屈，九万鹏斯抟。","相期阆风上，高步青云端。"]},{"t":"半闲道人画卷","f":"五言古诗","c":["馀杭佳山水，我昔曾一游。","缅怀丘园隐，自得林塘幽。","映门尽嘉树，隔岸皆平畴。","岂惟慕巢许，亦复谈伊周。","母以半闲号，忘此终身忧。","苟怀豫逸志，不与乾刚侔。","愿子慎明德，勖哉企前脩。"]},{"t":"云林小隐为崔彦晖赋","f":"五言古诗","c":["白云何英英，荫此嘉木林。","云气有卷舒，林木恒萧森。","久矣慕高躅，于焉遂初心。","举头弁山高，濯足苕水深。","草堂自秋爽，松厅空夕阴。","冥鸿飞避弋，野鹤下听琴。","载歌招隐童，重赋归来吟。","白驹在空谷，毋遐金玉音。"]},{"t":"静斋诗为朱君政赋","f":"五言古诗","c":["幽居绝尘想，众山罗其前。","缘好得深造，以寂成静专。","斋虚空生白，宇定先烛天。","罢琴挂空壁，熏炉玩遗编。","荷凉下飞鹭，槐署来鸣蝉。","悠哉岁月外，阔为天地先。","贻言紫阳氏，保贞期永年。"]},{"t":"敬义斋诗为金华吴景昭赋","f":"五言古诗","c":["斋居抱冲素，萧然洁尘襟。","敛收学乃臻，驰骛志益淫。","斯须起一发，俄顷弥千寻。","畴知主宰功，宛在方寸心。","灵扃异蛰户，广术非蹄涔。","帷兹敬义立，翼若神明临。","金华延陵裔，立守翰墨林。","韦编日孜孜，碧窗昼阴阴。","履道固云坦，浚德斯其深。","嗟予坐狂斐，得反期规箴。","永言直方理，庶播金玉音。"]},{"t":"鄱阳王节妇诗","f":"五言古诗","c":["朝华夕已披，春叶秋先零。","贞心类松柏，岁晏弥青青。","文川李氏女，防身动如经。","自归太原家，目不窥外庭。","上堂问舅姑，下堂觞醁醽。","遭时有战伐，渭流浊其泾。","草窃起旁郡，鼪鼯杂膻腥。","舅也保乡里，击贼无留停。","夫也慎居守，率众环郊坰。","节妇当此时，事姑肃仪刑。","舅荣夫已亡，痛哭羸其形。","先有两儿女，玉雪怜娉婷。","与姑共抚之，闭门昼长扃。","柰何姑继殁，只影空伶俜。","尚职祭祀礼，蘋蘩荐芳馨。","教女夜绩麻，教儿夜囊萤。","父母虽孔迩，胡能自归宁。","今年五十馀，鬓发微星星。","儿成女有归，往事犹梦醒。","有司重节义，飞章上朝廷。","花诰来翩翩，华表高亭亭。","行者为叹息，居者增晶荧。","至今太原家，芳名蔼观听。","人生谅有涯，聚散如云萍。","纲常苟沦丧，不愧天地灵。","女史固有箴，列女亦有屏。","我歌节妇篇，君子当刻铭。"]},{"t":"海旸子诗为李彦实赋","f":"五言古诗","c":["晨兴候沙际，望见蓬莱云。","蓬莱渺何许，稽首云中君。","曜灵登搏桑，举世知为昕。","中天撰龙辔，六合无嚣氛。","云何海旸子，未谢沙鸥群。","观水必观澜，献曝同献芹。","望洋昧所观，逐影徒为勤。","积流成大川，学古求多闻。","寸阴圣者惜，子当惜其分。"]},{"t":"牧隐诗为李文照赋","f":"五言古诗","c":["川原澹微风，草色绿以齐。","牛羊散平野，欲与苍烟迷。","麾肱毕来升，鞭策何用携。","所以隐君子，于焉记幽栖。","朝牧日在东，暮牧日在西。","尔羊无百尾，尔牛无千蹄。","对之忽两忘，俯仰惟端倪。","因兹崇隐德，岂顾犊与羝。"]},{"t":"赠医士沈士贞","f":"五言古诗","c":["庖丁能治牛，师旷能治音。","畴知扁鹊术，异迹同其心。","五行播四序，偏胜恒为淫。","柰何蕞尔躯，禦此寒暑侵。","岐黄世云远，奥义难重寻。","长沙继扁鹊，论议横古今。","不有刘张徒，奚辨石与琳。","钱唐医之薮，名士朋盍簪。","惟兹隐候裔，声价兼南金。","厚施远食报，券积高于岑。","朅来金闺彦，有疾虞将深。","神丹进刀圭，捷若磁引针。","功成不受馈，拂衣归茂林。","我夙慕其人，与语开尘襟。","安得双鲤鱼，为之溉釜鬵。","尽询养生秘，启我聋且瘖。","会面谅可期，因风寄长吟。"]},{"t":"怀云轩图为王子中题","f":"五言古诗","c":["严亲在高堂，征夫在天涯。","所以于此时，瞻云每兴怀。","念子失怙恃，悠然坐松斋。","感此无定姿，邈若音容乖。","四方及上士，怅望胡能偕。","因之为此图，氤氲抱丹崖。","似当日之夕，山气何其佳。","显亲系揭名，古训期免谐。","愿言作霖雨，行当咏三槐。"]},{"t":"听潮轩图为夏伯玘题","f":"五言古诗","c":["观水必观澜，听潮每听音。","乃于无声处，见此天地心。","方其潮未上，大江一蹄涔。","将耳欲听之，寥寥杳难寻。","及夫潮既落，汹涌成消沉。","又复以耳听，默默真如瘖。","惟于初至时，辟阖阳与阴。","吹地殷鼙鼓，从风鉴铁金。","之子于此轩，危坐正其襟。","悟兹寂感理，阅尽古与今。","已无言语述，况著丹青临。","我听不以耳，孰知听逾深。","拟将布声意，写入无弦琴。"]},{"t":"仙山访隐图","f":"五言古诗","c":["仙山渺何许，飞楼跨苍穹。","谁携九节杖，直入烟霞中。","雨馀千涧急，略彴微径通。","松花落金粉，衣袂回春风。","幽怀何以写，赖有爨下桐。","吴江脱屣后，不逐陶朱公。","还来白云里，挥弦送飞鸿。","苕溪隐君子，苦心乃良工。","五岳在只手，三山入双瞳。","每于生纸上，经营意无穷。","我知图画理，能使尘虑空。","胡为效病鹤，局促遭樊笼。","何当赋招隐，山幽多桂丛。"]},{"t":"布谷篇","f":"五言古诗","c":["鸣鸠本鹄鵴，形状鹴鸠殊。","江东呼拨谷，布谷江南呼。","桑间拂其羽，长与载胜俱。","一鸣雨霢霂，再鸣雨沾濡。","三鸣未及已，惊起耕田夫。","扶犁乃毕出，荷锸争前趋。","我闻少皞氏，凤鸣来应图。","纪官此司空，信为德之符。","愿言反淳风，圣世跻唐虞。","持此鸣鸠篇，远献王者都。"]},{"t":"蔼萱堂诗为夏伯玘赋","f":"五言古诗","c":["丛丛堂下萱，蔼蔼枝上花。","岂无众草木，独此能荣华。","况当朱明候，连续开丹葩。","蜻蜓飞南圃，蝴蝶飞东家。","何如小尾蜂，朝暮报两衙。","寸心固云殚，慈母恩无涯。","锡类古所敦，永言非重誇。"]},{"t":"雪樵为吴江谢聘之赋","f":"五言古诗","c":["大雪满天地，山林何所樵。","不辨凡草水，但见英琼瑶。","琼瑶固云美，政恐难琢雕。","草木亦已落，犹存旧根苗。","厉禁苟不废，庶可成夭乔。","柰何旦旦伐，无异见睍消。","惟兹谢家树，松柏见后凋。","昔宰安丘邑，今沂浙江潮。","手板方释手，腰斧仍在腰。","栋梁尚可得，榱桶不待招。","所忧岁年晚，雨雪恒瀌瀌。","蕃鲜回玉烛，光华丽璇霄。","四海一灵囿，君其老刍荛。"]},{"t":"谷隐为郑元谅赋","f":"楚辞体","c":["西都方遘患，凤兮叹德衰。","谷口郑子真，于马少栖迟。","躬耕本逃名，雄也反誉之。","虽违括囊意，庶合知几辞。","如何定山阳，令族适在兹。","隐德尚先世，食粟匪茹芝。","黄鸟忽嘤鸣，白驹当絷维。","所以庞德公，终为隐者师。"]},{"t":"鸳鸯篇","f":"五言古诗","c":["赣水白于练，芳池成委区。","濯濯出水莲，宁受尘垢污。","鸳鸯忽飞下，雌雄日相娱。","惟唼地中藻，不衔池上芦。","惟偕池中鲤，不杂池上凫。","霜风一夕发，池荒莲叶枯。","雄者方垂翼，雌者已就殂。","睢鸩知有别，精卫志不渝。","物性固莫夺，民心焉可诬。","至今南冈树，落月空啼乌。"]},{"t":"筼轩为吴兼喜赋","f":"五言古诗","c":["青山映华轩，窗户何玲珑。","凤鸟久不至，筼筜自成丛。","之子延陵后，读书此轩中。","昼阴兼夏绿，古色谢春红。","心虚事恒集，本立道自充。","投竿出鳞鲫，炙简祛蠹虫。","敲门思有待，题句惭未工。","安得文太守，深谷写高风。"]},{"t":"报德诗为郭伯瑆赋","f":"五言古诗","c":["朋友死无归，殡之谅非艰。","能于贤者施，大胜独与鳏。","贤者亦有子，兵乱不得还。","乱定子方至，临穴出涕潸。","报德斯以德，不在父字间。","文字苟不泯，世教诚相关。","道山郁嵯峨，苕水流潺湲。","相去数千里，可望不可攀。","一朝函骨返，无复莱衣班。","子固有戚容，人亦皆欢颜。","民胞物与意，砭订愚以顽。","呜呼子深氏，义重踰丘山。"]},{"t":"送李守约","f":"五言古诗","c":["清商变炎景，蘋末回高飙。","之子有远行，方舟已齐桡。","兹行何所之，钟陵郁岧峣。","于时际昌运，四海胥来朝。","严君任王家，玉佩联金貂。","岂不有所怀，怅望川原遥。","今辰复何辰，草虫鸣要要。","感此秋气集，颇觉心旌摇。","趋庭会有期，俪立英琼瑶。","出门道可由，进学德乃昭。","去去当努力，焚膏永凉宵。"]},{"t":"康上人画 其一 雪窗玩梅","f":"五言古诗","c":["林扃掩孤寂，落木无馀声。","道人坐空山，那知岁峥嵘。","夜寒窗有雪，渐与茅屋平。","不悟梅花閒，但觉鼻观清。","残经未能了，映隙窥微明。","愿以第一义，于焉證无生。"]},{"t":"康上人画 其二 南坞耕云","f":"五言古诗","c":["山云有幽姿，南捂春更好。","鞭起露地牛，布种皆药草。","宁辞袈裟单，但恐稂莠恼。","根茎固云殊，所贵辨之早。","况以梯稗秋，每食敢求饱。","感兹泽物功，童闲不教扫。"]},{"t":"送赵永贞改丞德化县以万水千山路孤舟几日程为韵 其一","f":"五言古诗","c":["郎官宰新邑，别酒须更劝。","随行但琴鹤，况乃仆夫健。","担簦与负书，累憩不知倦。","于时春已阑，花卉杂藤蔓。","丈夫贵逢时，进尺从退寸。","鹏程从此开，抟风当九万。"]},{"t":"送赵永贞改丞德化县以万水千山路孤舟几日程为韵 其二","f":"五言古诗","c":["万方既宁谧，二老亦兴起。","皇风播九州，贤路隘百里。","钱唐虽古邑，人民半凋毁。","持危与扶颠，非公畴可倚。","胡为移他邑，又使风俗美。","贰丞何人斯，谱乘自天水。"]},{"t":"送赵永贞改丞德化县以万水千山路孤舟几日程为韵 其三","f":"五言古诗","c":["水流必赴壑，况乃值大川。","伟哉朝宗意，浴日乃滔天。","昨日哦庭松，明朝犯蛮烟。","皇威遍四海，所见如目前。","勿谓道路难，民事在所先。","会看一士谔，当胜诺者千。"]},{"t":"送赵永贞改丞德化县以万水千山路孤舟几日程为韵 其四","f":"五言古诗","c":["千里复万里，道路多间关。","况复春尽时，好鸟声绵蛮。","贤宰离旧邑，车辕庶民攀。","贰事非敢专，亦当念茕鳏。","遄期构大厦，寒士皆欢颜。","去去不可留，怅望空云山。"]},{"t":"送赵永贞改丞德化县以万水千山路孤舟几日程为韵 其五","f":"五言古诗","c":["山云无定期，水月有真遇。","叔度虽云贤，来时柰何暮。","今辰复何辰，送别江口渡。","俄然发棹歌，惊起沙上鹭。","名儒为席珍，猾吏乃民蠹。","百里勿谓卑，从兹启贤路。"]},{"t":"送赵永贞改丞德化县以万水千山路孤舟几日程为韵 其六","f":"五言古诗","c":["路人为我言，行者方载途。","如何贤贰宰，征马思南徂。","有声盈我俎，有酒盈我壶。","饮食非所念，所念民力劬。","官府有贤良，庠序多范模。","为政虽云艰，要在德不孤。"]},{"t":"送赵永贞改丞德化县以万水千山路孤舟几日程为韵 其七","f":"五言古诗","c":["孤云在天末，可望不可留。","昔何为而敛，今何为而浮。","一朝从飞龙，变化弥九州。","应知三农意，翘首待有秋。","沛然作霖雨，江漠皆同流。","愿言乘长风，济川有虚舟。"]},{"t":"送赵永贞改丞德化县以万水千山路孤舟几日程为韵 其八","f":"五言古诗","c":["舟行何遥遥，南风飏旗尾。","江上无杂花，青青尽芦苇。","于时潮已平，波动日光炜。","中流双舻鸣，爱此儿郎伟。","饯行岂无诗，成章愧其斐。","会看展骥足，如公信无几。"]},{"t":"送赵永贞改丞德化县以万水千山路孤舟几日程为韵 其九","f":"五言古诗","c":["几年客燕山，问学畴与匹。","贰邑来钱唐，吏事师儒术。","邑庠久荒芜，赤手建宫室。","不有经济心，成效安可必。","勖哉教养功，为事贵其实。","凤鸟宁早栖，朝阳待他日。"]},{"t":"送赵永贞改丞德化县以万水千山路孤舟几日程为韵 其十","f":"五言古诗","c":["日出春雾消，江头潮水平。","舟人理轻棹，送客联诸生。","州县虽徒劳，由兹至公卿。","仁爱在民物，举世皆和亨。","请看萧曹业，承作邦家荣。","南溟岂不遥，万里开鹏程。"]},{"t":"奉和许章检校陪祭有作三十韵","f":"五言古诗","c":["学古始入官，为有民社寄。","此理均人臣，矧职居相位。","祀典遵百王，法守由一揆。","丘陵以为坛，陶匏以为器。","既严神祗称，复辨上下次。","成众本乎天，成形本乎地。","牲牢贵腯充，礼乐尚明备。","瞻仰民所崇，财用国攸系。","两仪同乾坤，七庙异涣萃。","日临斋戒期，卜叶享祀利。","不愆斯不忘，能备乃能祭。","皇风浩无垠，盛世宁有替。","于时蛰虫惊，应候玄鸟至。","风霆为昭明，山川载神气。","钟钟鸣鼓钟，秩秩陈簠簋。","翩然云之来，允矣诚所致。","有美文武臣，夙抱纯一志。","燎明夜向晨，月白天在水。","鹄立俨当中，骏奔走其际。","欣欣神乐康，简简福相炽。","湛露流玉阶，令风袭琼佩。","方当感格时，已著充满意。","礼行士无哗，乐奏神所莅。","益之以十朋，介之以繁祉。","祈报止春秋，敬恭止坛壝。","玉烛一鼎调，金成万宝遂。","三献迄有终，九府均被赐。","岂期康衢民，获睹放勋世。","雷动车马还，日出海波沸。","作诗聊记年，皇明甲寅岁。"]},{"t":"南山纪事诗为杨复初赋","f":"五言古诗","c":["子云每好奇，招我游山泽。","偏兹会佳趣，历览尽幽僻。","维阳有崇山，日出烟雾隔。","穷探不知远，但觉多寒阨。","萦回林麓深，窈窕蹊径窄。","陟冈纵奇观，未至心已怿。","屹然峙浮图，天孤一峰碧。","百折乃肯下，磅礡势辟易。","前面苍龙首，后负灵鳌脊。","雄踞虎妥尾，雌伏乌敛翮。","地胜气所钟，土色状琥珀。","上有百岁梅，下有千岁柏。","左右脩竹林，森森列矛戟。","乃于隐约间，凝然结幽宅。","不知何人地，欲问山中客。","同游忽告予，先人此窀穸。","为言经营难，小立话畴昔。","兹山莘精蓝，蟠据无罅隙。","惜土如惜金，谁能此藏魄。","忆昔先人存，颇有风水癖。","偶读青乌经，送识来龙脉。","穷探得兹穴，屡请竟莫获。","因之号南山，以志聊自释。","神游心不忘，遗命在易箦。","再请拒益坚，衷情从内迫。","负愆背若芒，失措手犹螫。","三年读礼经，方寸恒戚戚。","昨承郡国荐，专教上海席。","世变之京师，所历备艰厄。","亲骨未入土，此实入子责。","匪惟热中肠，亦复泚其额。","还家踰一纪，终请始不惜。","方将议封树，讵意远行役。","及归岁云暮，故地启新辟。","俄于畚锸下，石露见刻画。","三复穆陵诗，摩挲出圭璧。","若曰风雨寒，草草奚所适。","重约舞凤笙，迟归在朝夕。","昔藏事已非，今获语可绎。","百年如合符，此理疑感格。","愿徵先生言，庶为生者益。","我观孝子志，百顺无一逆。","临事苟获为，努力甘毁瘠。","于心或有慊，神明谅能谪。","如子克奉襄，众指见巨擘。","古来卜吉事，往往著简册。","致鸟表清忠，眠牛发陈迹。","佳哉滕公城，欲堕王果石。","子也慎其终，今闻永无斁。","勿谓经营难，馀庆善所积。"]},{"t":"赠潘德厚","f":"五言古诗","c":["洪武戊午秋，佳辰又重九。","门前冬青树，想像如五柳。","中有避俗翁，于焉养衰朽。","俄闻扣门声，乃见二三叟。","水心吾忘年，虎头吾畏友。","偶偕安仁裔，所见知所守。","湛然若渊泉，温其类琼玖。","云是主粟官，才能世无偶。","奔走事先集，易若屈伸肘。","杭郡冠东南，仓廪过陵阜。","出纳既有程，经营亦非苟。","尚不遗撮圭，况乃累升斗。","昔闻闲居时，板舆奉慈母。","郡国举孝廉，惟汝独称首。","赋诗中书堂，落笔海潮吼。","青袍方里身，美誉已腾口。","禄仕安敢择，所贵为母寿。","柰何不及养，中心讵能剖。","今年属兔丧，文字复徵取。","请解来钱唐，见者惟恐后。","书成华其行，河桥重携手。","从兹到三泖，湖水清且浏。","鲈鱼入板罾，香粳出舂臼。","因之作画图，可以识某某。","示我索题诗，成章愧呈丑。","胡能继殊珍，但可供覆瓿。","譬之多稼田，也复容稂莠。","恭惟圣明朝，文化被九有。","图书出河洛，麟凤在郊薮。","貂蝉变兜婺，金印联组绶。","贤者屹山岳，能者环培塿。","芃芃棫朴姿，尔在薪与槱。","嗟我晚闻道，倾盖蒙发蔀。","登临此日同，留别不能久。","赠以黄金花，西风一杯酒。"]},{"t":"辛亥岁秋帘分韵得上字","f":"五言古诗","c":["明时圣主作，文治在所尚。","声教极被渐，舆图混轮广。","科目网多士，纲维属良相。","朝廷尽明扬，岩穴竭搜访。","世岂乏栋梁，意在得工匠。","棘阑重开设，茅拔皆闻望。","有来君子儒，俱为丈人行。","校艺辨妍媸，立言关得丧。","岂无欧苏出，敢与晁董抗。","再鼓勇诸生，三叹永一倡。","易书本黄虞，礼乐宗素王。","论或准贾生，骚岂比荀况。","神奇化臭腐，垒洗见盆盎。","金镛或在悬，玉卮恐无当。","治音贵和平，赘语删冗长。","细句独茧抽，雄篇怒涛涨。","千军期独扫，百川可东障。","措辞喜华丽，赋质陋木强。","有美凤鸣岗，无取马立仗。","抚序渐萧条，举目忽清旷。","河汉澹微云，天雨绝纤坱。","月色秋正佳，潮声夜逾壮。","帘风乱星烛，檐露袭斗帐。","蟋蟀已居壁，莓苔欲侵桁。","念兹岁如流，母使情益荡。","谋谁兔三窟，能著屐几緉。","千虑有得失，万事付遗忘。","为学竟荒唐，扪膺益惆怅。","昆崙有丹丘，蓬莱有方丈。","愿接卢敖游，相期九天上。"]},{"t":"雪竹轩图为彭彦明赋","f":"五言古诗","c":["北风天大寒，平地雪三尺。","萧然轩窗外，见此万竿碧。","此君有高节，岂但密如箦。","类彼轩中人，相看共贞白。","谁欤作此画，光景照凡席。","形神恍其间，那知故园隔。","岂无九节杖，亦有双蜡屐。","清兴如可乘，山阴访陈迹。"]},{"t":"松雨斋为胡拱衡赋","f":"五言古诗","c":["西山澹幽姿，脩眉亘天宇。","飞来石上云，散作松间雨。","前声犹淅沥，后势稍轩舞。","风惊八月涛，地裂万雷鼓。","斯须籁画息，惨淡形可睹。","谁谓工之良，自觉心也苦。","于焉名斋居，允矣好奇古。","愿效谪仙吟，因之梦天姥。"]},{"t":"竹居为张行中赋","f":"五言古诗","c":["我观隐者居，种竹皆绕屋。","无竹俗其人，无人俗其竹。","纷纷迷籓篱，往往遍林麓。","岂不怀渭川，因之咏淇澳。","如何一丈地，有此数竿玉。","遂今篷蒿室，便拟筼筜谷。","笋出亲可供，充庖胜野蔌。","叶落童自青，燎釜助山木。","秪因幽事关，颇觉生理足。","夜眠闻秋声，晓起见寒绿。","繁欲加斧斤，因或资简牍。","会当留高枝，他年凤凰宿。"]},{"t":"兰雪斋为沈德源赋","f":"五言古诗","c":["猗猗谷中兰，粲粲丛上雪。","春风有时来，绿艳终不灭。","志士多古怀，君子有贞节。","于焉抱清润，允矣全脩洁。","孔操寡知音，郢歌谩成阕。","兴言得同心，援琴写幽咽。"]},{"t":"送曾子员归庐陵侍亲","f":"五言古诗","c":["潜鱼无扬鬐，归乌有敛翮。","物性安固然，谁谓天地窄。","要路多通津，高足谅且策。","严亲已华颠，胡为事行役。","宁食青原菽，不食蓟丘麦。","宁饮桂溪水，不宿燕市驿。","昨暮寒蝉鸣，今晨归骑迫。","欲采芙蓉花，难以遗远客。","赖有和陶辞，因之慰安适。","子道在养志，竭力甘毁瘠。","锡类古所敦，相望海云隔。"]},{"t":"画菜 其一","f":"五言古诗","c":["芥能清我心，助养颇为急。","春畦雨露濡，根叶每沾湿。","园丁亦云劳，小摘日供给。","燥吻殊可怜，时时啜齑汁。","壮年功名心，青紫如地拾。","谁言纳须弥，秪用子一粒。","披图见纷披，胡为在原隰。","岁晏思灌园，抱瓮当日汲。"]},{"t":"画菜 其二","f":"五言古诗","c":["高田宜种蔬，下田宜种穑。","岁馑与饥同，安敢望肉食。","雨馀理荒畦，甲拆资地力。","会看根本长，取之戒勿亟。","天公怜我贫，此物颇不啬。","便如终岁谋，十瓮拟可得。","今笑披画图，流涎欲沾臆。","长能咬菜根，天下无此色。"]},{"t":"洪武甲寅冬十二月祀岳王仁和知县四明陈子善先生夜宿祠下有作因次其韵","f":"楚辞体","c":["我行古剑关前路，正见岳王坟上树。","坟前湖水日夜东，万古不流忠烈去。","汴梁城里胡尘飞，炎精一蔽天无辉。","宫墙烟柳自春昼，画梁燕子将谁依。","新愁又到西湖柳，万缕黄金拂人首。","长条折取赠行人，谁酹英雄一樽酒。","四弦弹出陌上花，推手为琵却手琶。","坡仙有语谁解道，独歌缓缓妾还家。","往古来今无限思，欲著春风恐无地。","杜鹃秪解管兴亡，蝴蝶何曾知寤寐。","可怜冻雀纥干山，致身不似艮岳间。","翠华已见去冉冉，琼佩无复来珊珊。","西湖信美人间少，彷佛十洲与三岛。","独有荒坟老树身，拱把如今成合抱。","白云只在山之巅，随风忽堕诗人前。","酒酣载歌白云曲，万事知心惟有天。","宋家秦桧遇元载，奴计专和前志改。","岂无祖逖空渡江，亦有鲁连终蹈海。","呜呼自坏万里城，谁挽天河重洗兵。","朱仙灵旗一朝返，中原此恨何时平。","昔闻哲王用人杰，鳌极何曾有崩裂。","天之所坏不可支，剑锋竟染苌弘血。","背嵬将军万夫雄，丈八蛇矛成武功。","左传一篇长在手，正欲运筹帷幄中。","大羊腥膻期尽扫，胡虏前徒万戈倒。","咄哉和议竟盈廷，此理无由问穹昊。","子复生孙孙有子，移山不信愚公死。","英灵气在天地问，每到祠前即兴起。","升堂再拜有所思，中兴奸相真小儿。","良弓遽藏高乌在，万古千秋伤有为。","皇纲讵可成乌有，谁念青衣类黔首。","堂堂庙貌民具瞻，公论由来在身后。","朅来吊古心自疑，浩歌似有山灵知。","苍茫雷电动神马，恍惚风云生大旗。","秋复春兮春复夏，四时拜扫祠堂下。","也知天定能胜人，列土分茅号王者。","丈夫生死有重轻，死非其地如无生。","吁嗟吁嗟岳少保，自公之死国不宁。","二帝只在黄龙城，眼枯天地终无情。","何如父子麒麟冢，离乱之馀除乘拱。","不教斤斧犯松楸，肯使牛羊上丘垄。","诗人夜宿听山泉，出户满目皆荒烟。","不闻金鼓殷地发，但见玉镜当空悬。","忠臣之志何烈烈，报国惟公心似缺。","明年卤簿迓为神，湖上花朝春二月。"]},{"t":"景献太子墨竹","f":"七言古诗","c":["古来画竹谁最豪，萧悦不及王维高。","文同之后到景献，学得南唐金错刀。","齐纨新裂裁成扇，顷刻春雷穿铁砚。","图成标以袅翠名，宛似黄陵庙前见。","九疑峰高云气迷，天寒日暮娥英啼。","乎中瑶瑟不敢鼓，恐有凤凰来上栖。","宣和年间好时节，徽庙丹青更奇绝。","南渡王孙爱墨君，犹是东都旧枝叶。","二百年来迹已陈，烟梢露叶长清新。","有熊乘衣今复睹，制筒未必无伶伦。","诗人尚友须千古，寞搜心内良工苦。","安得此图挂北窗，坐听秋声起风雨。"]},{"t":"布谷篇","f":"七言古诗","c":["阳春布德鹰化鸩，眼虽可识心和柔。","野人因见拂其羽，有事南亩并西畴。","桑林阴阴桑葚熟，彷佛禽言如布谷。","秋成准拟去输官，农务当勤何待促。","周家开国本务农，艰难王业存豳风。","仓庚鸣鹃俱在咏，布谷应候将无同。","田家望雨由清哢，况闻处处催春种。","黍稷今年如满家，布谷之祥胜灵凤。"]},{"t":"赠朱仲谊之京师就其子启文养","f":"七言古诗","c":["河桥柳青不忍折，临岐顿觉中肠热。","百年几见一代人，二月重为千里别。","我居北郭遭乱离，韦编大义犹日披。","有颀而长过我者，不通名姓知为谁。","借我大义汗漫读，因注首肯疑心服。","掷还上马竟南征，高举飘飘类鸿鹄。","明年我中己亥科，思之不见将柰何。","每从儒者谈彷佛，恐有仙客来经过。","昨者相逢知姓字，云是崆峒邹道士。","注得参同只自看，仍以苑经造馀子。","棘闱校卷又相逢，风帘官烛摇秋红。","诗成不许众吏写，八分作字何其工。","从此文游成莫逆，学不能同颇能识。","作文状我衰陋容，三诵真如见颜色。","今春人作凤台行，佳儿彩服遥相迎。","西子湖头一杯酒，三叠阳关歌渭城。","渭城自远台城近，碧草绿液空掩映。","行行无限好江山，物色分留待吟咏。","江东日暮多白云，见云未必如见君。","云间若有双飞鹤，为我衔来天上文。"]},{"t":"赵大年芦雁图","f":"七言古诗","c":["平林带烟波渺渺，风低葭菼秋声小。","望中疑是彭蠡湖，十百为群尽阳乌。","楚天未雪无雨霜，南来岂必谋稻粱。","哀音若欣云路迥，老翅不厌关河长。","汀州水落成平陆，散乱凫鹥聚沙曲。","低飞不肯俾寒鸦，犹绕荒村破茅屋。","屋中有客挥五弦，从之不得心茫然。","何人图画能著此，赵氏丹青称大年。","徽庙元年颂凤历，此图正是当时迹。","便从宣和到靖康，艮岳禽声起秋夕。","古往今来几盛衰，摩挲老眼竟成悲。","良工心苦人莫识，似写周宣鸿雁诗。"]},{"t":"悼沧蟾","f":"楚辞体","c":["沧溟接云水皆立，鼋鼍赑屃蟾蜍泣。","珊瑚声碎海若愁，犀角香消桂娥浥。","蟾为影兮沧为形，都将皎洁同清泠。","九霄倒下湛虚白，万古直上涵空青。","逝邪亏邪复何有，不抵生前一杯酒。","海枯月没双眼月，始识人间亡是叟。"]},{"t":"画山水","f":"七言古诗","c":["遥山倚天翠蛾扫，编地成丸怪天小。","方诸药幻茧楮香，咫尺烟云生缥缈。","依岩缚屋若不齐，人家高下清溪西。","野桥终日才度马，村店傍午俄闻鸡。","昔年曾过冯公岭，树木萧森葛衣冷。","目中览尽千万山，始觉此身凌绝顶。","邮亭夜宿天未明，仆夫惮远催早行。","满前好句吟不得，今见此图同此情。","南宋院人专尽局，宫中每进更筹轴。","偶蒙一笑便承恩，肯信封疆日将促。","江山万里开画图，妙绝更有元晖无。","会须收拾入指掌，掷杖跳入壶公壶。"]},{"t":"画马为顾彦明赋","f":"七言古诗","c":["老骥伏枥志千里，烈士松心同不已。","因思饮水向天山，枕上边声梦中起。","昨者试洛江之干，蹴踏细浪成狂澜。","青丝络头系乘柳，云湿五花犹未乾。","朱衣奚官在坰野，不独爱马尤知马。","一顾冀北无留良，秪使世间观画者。","画师今古孰后先，曾韩古有今龙眠。","近时亦有任水监，不及吴兴为自然。","吴兴父子真游戏，皮氏丹青亦同嗜。","曾貌前朝十二闲，落笔颇得吴兴意。","摩挲树者重入图，韩公所记今则无。","歌行屈指能几教，谪仙少陵并大苏。","虎头好古宁论价，神骏端令万人讶。","他年按图倘得之，拟献君王赤墀下。"]},{"t":"包山玩月次睢宗吉韵","f":"七言古诗","c":["昔我曲江观恐涛，越山不及吴山高。","如何古有任公子，一钓乃能连共鳌。","我今杖藜寻翠麓，地有白云人不俗。","丹房火冷碧窗虚，夜半秋声撼林竹。","踏歌连臂下仙坛，目断西山吴彩鸾。","桂花飞帘作香雪，转首便觉秋阑珊。","人生欢乐难再得，始信光阴如遇客。","陶令空披漉酒巾，谢公谩著登山屐。","庵前堵墙如白虹，洞门不掩来江风。","分师半席师已许，经筵蜡烛摇秋红。","郊何为寒岛何瘦，新雨能来宁论旧。","今宵烂熳得好晴，知是何人补天漏。","少壮而老理则常，胡能不死凋三光。","放麑西巴诚不忍，歌凤接舆无乃狂。","兹游可继五君咏，祀事同陪匪乘兴。","中庭坐待明月来，树影团团一时并。"]},{"t":"关山雪霁图","f":"七言古诗","c":["前峰后峰雪模糊，东村西村春有无。","快雪时晴入佳想，况复见此关山图。","关山迢递相联属，玉洁珠光眩人目。","扶桑飞上金毕逋，暗水流澌度空谷。","野桥行遇路三叉，青旗插檐沽酒家。","驱驴倦客得少憩，怅望远道还咨嗟。","诗翁好事常起早，天寒秪恐梅花老。","柴门时有故人来，阶下白云须用扫。","此图一日落尘寰，笔法依希荆与关。","人生远游固云乐，何似在家长看山。","我本识字耕夫耳，占祥便作丰年喜。","田园归隐会有时，麦饭饱餐茅屋底。"]},{"t":"郁鲁珍画","f":"楚辞体","c":["平生山水尝见之，不意画图如此奇。","松雪老仙得其理，笔端幻出无声诗。","森森千丈长松下，中有高人韵潇洒。","挥弦岂为送飞鸿，情性因之自陶写。","杏坛绝响几秋春，谁信经成能致麟。","黎阳先生真隐者，为假山水传其神。","溪山苍苍溪水绿，君胡为兮在空谷。","他时倘鼓宓贱琴，更效南风歌一曲。"]},{"t":"画梅","f":"七言古诗","c":["玉龙寒嘶银粟下，山色昏冥如破瓦。","老枝枯蘖无眩容，暗里阳春生一罅。","东风团雪作好花，明月落在诗人家。","远移何必得健步，秃兔败茧能荣华。","花光补之俱寂寞，王冤后来观此作。","岁寒重约到狐山，共倚巢居旧时阁。"]},{"t":"牧童画","f":"七言古诗","c":["田家养牛缘种谷，童不解耕还解牧。","日暮麾之匍匐归，犹向笼中顾鸲鹆。","西风入树秋有声，千村万落皆收成。","截来短笛吹未得，拍手时时歌太平。","太平气象难摹写，依稀似在桃林野。","披图见此黑牡丹，始信戴篙善画者。"]},{"t":"吴山对雪诗","f":"楚辞体","c":["腊前有雪宜三白，笑倒田翁手齐拍。","去年天气不多寒，盈寸犹难况盈尺。","嗟予亦是田舍翁，敢以玉山高两峰。","二贤珠玉在我侧，绿发青瞳颧颊红。","久交共喜情怀尽，意行不觉吴山近。","松间小径纵萦迂，竹杖芒鞋须一进。","山前相府何潭潭，山中道院邻禅庵。","兴来偶到故人宅，出果行酒方交谈。","岁如何兮岁云暮，白首重来乩前度。","湖山倒浸水晶奁，玉树琼林归措顾。","山阳先生坐高堂，挺然特立逾脩篁。","谁怜衰翁方避俗，寒窗痴坐如绳僵。","失喜一时观二妙，剡曲回舟岂同调。","明朝呵笔和新诗，檐有梅花须索笑。"]},{"t":"美人折花图","f":"七言古诗","c":["深宫细雨流光湿，蔷薇吐花红欲涪。","美人梳洗出帘迟，云拥髻鬟高一尺。","爱花呼婢折来看，一枝疑荐黄金盘。","却嫌绿剌暗伤人，整顿玉织肩黛攒。","笑语追随真有意，绣罗衣裳照珠翠。","长安水畔若相逢，不是杜陵心亦醉。","胎阳燕子尾延延，皱裙无计留飞仙。","春风人面解传得，始信丹青非偶然。"]},{"t":"二美人图 其一","f":"曲","c":["黄金买妾身，何曾买妾心。","妾身岂愿死，义重千黄金。","主家珊瑚高比树，如意声中落红雨。","堕楼化作兰麝尘，不复樽前为君舞。","按图哀怨起绿珠，晋家事业真剥肤。"]},{"t":"二美人图 其二","f":"曲","c":["金屋岂无人，三千当一身。","如何把玉笛，吹动渔阳尘。","梨园歌舞成消歇，海棠飞作胭脂雪。","空遗罗袜不生尘，香冷马嵬坡下月。","按图哀怨起玉环，唐家事业真厚颜。"]},{"t":"画梅集杜句","f":"七言古诗","c":["东阁官梅动诗兴，多才依旧能潦倒。","绝笔长风起纤未，乱插繁花向晴昊。","却德年年人醉时，千朵万朵压枝低。","不知明月为谁好，武陵春树他人迷。","中夜起坐万感集，山鬼㗀嚘雪霜逼。","岁暮穷阴耿未已，临风三嗅馨香泣。"]},{"t":"送谢铁崖游龙虎山","f":"楚辞体","c":["有美人兮怀远游，逍遥九州复九州。","暂来淮芝与吴越，五云飞上千金裘。","八公山在淝水上，草水尚若森戈矛。","澄江如练谁解道，况闻好鸟喧春洲。","东山蔷薇几回落，昔人何处青苔稠。","钱唐故宫尽未黍，帝子一去江空流。","客儿亭前高兴发，便欲著屐穷深幽。","天难二鸣更五点，海日涌出黄金虬。","瑶笙声断白鹤远，知有子晋从浮丘。","蟠桃开花今已寔，似许方朔重来偷。","如何去作龙虎客，远慕漠代张留侯。","我闻仙翁号虚靖，草庵宛在山之陬。","长乘丹光翳彩凤，或有紫气随青牛。","子能候之问至道，黄庭内景非难求。","四方上下游已遍，归来十二仙人楼。","楼中长啸弄明月，握手一笑三千秋。"]},{"t":"次张行中见寄韵","f":"七言古诗","c":["巧言如簧自口出，含沙射影过于蜮。","不思黄鸟嘤其鸣，返效青蝇白者黑。","自非蟠根别利器，真以委形同槁木。","偶然得集类武陵，率尔成章道长吉。","策足便可登要津，高举惟须振六翮。","文从字顺乃立言，意会神交岂容默。","跃冶每怪不祥金，剖璞姑怜三献玉。","寂寥颇若大音希，浑厚真如元气毓。","追逐还能到李杜，压倒何须论元白。","悦理自信犹悦刍，好德谁能如好色。","六义端因诗序知，千虑却同愚者得。","会当载酒过子云，况有候芭作玄足。"]},{"t":"陈居中进马图","f":"七言古诗","c":["明王慎德蛮夷宾，尺天寸地皆王臣。","远人重译贡龙马，流沙万里来麒麟。","金丸声动佛郎国，宝剑气接明河津。","不知何年离榆塞，但见此日朝枫宸。","毛騧生来玉琢鼻，钱骢隐起花攒鳞。","最后赭白信无敌，如此丹青款有神。","腾骧欲飞使者喜，控制不得奚奴嗔。","我闻陈阅善匠意，无乃韩干为前身。","按之图中得所以，借哉世上遗其真。","骊黄牝牡不易索，九方率后知何人。"]},{"t":"月轩为海日张侯赋","f":"七言古诗","c":["轩前月来人不知，月来岂与人相期。","张侯心中有明月，一举目间恒在兹。","昔年见月亲具在，今年见月亲何之。","玄霜徒劳至兔捣，桂树摇落秋风枝。","海昌之地亘百里，斯民父母非侯谁。","民之望侯如望月，高悬一鉴分妍媸。","公馀燕坐此轩下，中夜矫首空驰思。","琼楼玉宇在天上，安得酹入黄金卮。","霓裳不及彩衣舞，凭轩谩忆趋庭时。","天王天下民父母，光华旦旦无盈亏。","海隅苍生因不被，依光已为贤侯期。","一轩虽小关孝治，此理亦自良心推。","永锡尔类思不匮，谓子不信徵诸诗。"]},{"t":"鬼猎图","f":"七言古诗","c":["终南进士乃好武，野魅山精皆部伍。","蒐田也欲从四时，作气恍如聆一鼓。","铜钲先鸣地欲裂，皂盖后张风为举。","蹇驴足跛不受鞭，良犬尾摇何用组。","锦绦未许纵苍鹰，铁絙犹能缚玄虎。","跳踉众鬼为卒徒，矍铄一翁作谋主。","或为狼顾背拔鎗，或作猱升前试斧。","鸱鸣口应已张弓，蛇偃肩担来彀弩。","身凭大盾宛转遮，手弄飞槌高下舞。","坐作击剌众莫当，进退超骧孰敢侮。","狰狞以觉口吐牙，轻捷浑疑臂生羽。","逐禽不假御车舆，获兽何劳施网罟。","亦知尘世有司存，颇类神仙足官府。","画工后辈效前人，戏笔何年追旧谱。","已无吴生名坛场，复有颜辉好奇古。","周易取象车载一，韩子送穷名数五。","如斯情状不易知，更欲形容亦良苦。","谩于唐殿啖虚耗，何似渔阳制胡虏。","且须留取作岁除，爆竹一声春满宇。"]},{"t":"望云图","f":"曲","c":["上山看云云在天，下山看云云在山。","朝行巳与云俱出，暮归复与云俱还。","在山之云不可执，在天之云不可攀。","白衣苍狗须臾变化岂有定，乃在孝子方寸之中间。","刘郎有亲舍杉关，关上白云长自闲。","驱驰王事归养不可得，岂畏七闽尚去行路之多艰。","朅来西湖弄潺湲，春风好鸟鸣??。","思亲不见出涕潸，衣裳在笥空斑斓。","他年彩诰或可须，累累印绾青丝纶，君恩一日如赐环。","刻木肖像双亲颜，并州参军若是班。","此图此意百千万载留人寰，吾诗夸矣人其删。"]}]};